_V11_GATE_THREAD_LOCK = threading.RLock()


@contextmanager
def _durable_learning_v11_gate_lock(store: Any) -> Iterator[None]:
    """Serialize V11 qualification and delayed-attempt ordering across processes."""
    lock_path = store.protocols / ".durable-learning-v11-gate.lock"
    with _V11_GATE_THREAD_LOCK:
        if os.name == "nt":
            store._ensure_windows_collection(store.protocols)
        flags = os.O_CREAT | os.O_RDWR
        if os.name == "posix":
            flags |= getattr(os, "O_NOFOLLOW", 0)
        descriptor = os.open(lock_path, flags, 0o600)
        locked = False
        try:
            info = os.fstat(descriptor)
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                raise ValueError("durable_learning_v11_gate_lock_invalid")
            if os.name == "nt":
                import msvcrt
                if info.st_size == 0:
                    os.write(descriptor, b"\0")
                os.lseek(descriptor, 0, os.SEEK_SET)
                msvcrt.locking(descriptor, msvcrt.LK_LOCK, 1)
            elif os.name == "posix":
                import fcntl
                fcntl.flock(descriptor, fcntl.LOCK_EX)
            else:
                raise ValueError("durable_learning_v11_gate_lock_platform_unsupported")
            locked = True
            yield
        finally:
            try:
                if locked:
                    if os.name == "nt":
                        import msvcrt
                        os.lseek(descriptor, 0, os.SEEK_SET)
                        msvcrt.locking(descriptor, msvcrt.LK_UNLCK, 1)
                    else:
                        import fcntl
                        fcntl.flock(descriptor, fcntl.LOCK_UN)
            finally:
                os.close(descriptor)
