def _verify_condition_worker_baseline_runtime_manifest_pair(
        manifests: Mapping[str, Mapping[str, Any]]) -> None:
    """Require the two v2 launch manifests to describe reciprocal branch roots."""
    if not isinstance(manifests, Mapping) or set(manifests) != set(_CONDITIONS):
        raise ValueError(
            "durable_learning_worker_baseline_manifest_pair_invalid")
    root_names = {"state", "history", "session", "journal"}
    for condition in _CONDITIONS:
        manifest = manifests[condition]
        peer_condition = next(item for item in _CONDITIONS if item != condition)
        peer = manifests[peer_condition]
        if (not isinstance(manifest, Mapping)
                or not isinstance(peer, Mapping)
                or manifest.get("schema_version") !=
                    "sentientos.durable_learning_worker_baseline_runtime_manifest:v2"
                or peer.get("schema_version") !=
                    "sentientos.durable_learning_worker_baseline_runtime_manifest:v2"
                or manifest.get("peer_condition") != peer_condition
                or manifest.get("peer_branch_id") != peer.get("branch_id")
                or peer.get("peer_condition") != condition
                or peer.get("peer_branch_id") != manifest.get("branch_id")
                or not isinstance(manifest.get("roots"), Mapping)
                or not isinstance(manifest.get("peer_roots"), Mapping)
                or not isinstance(peer.get("roots"), Mapping)
                or not isinstance(peer.get("peer_roots"), Mapping)
                or set(manifest["roots"]) != root_names
                or set(manifest["peer_roots"]) != root_names
                or set(peer["roots"]) != root_names
                or set(peer["peer_roots"]) != root_names):
            raise ValueError(
                "durable_learning_worker_baseline_manifest_pair_mismatch")
        for root_name in root_names:
            if (manifest["peer_roots"][root_name] !=
                    peer["roots"][root_name]
                    or peer["peer_roots"][root_name] !=
                        manifest["roots"][root_name]):
                raise ValueError(
                    "durable_learning_worker_baseline_manifest_pair_roots_mismatch")


def _verify_condition_worker_baseline_manifest_sessions(
        manifests: Mapping[str, Mapping[str, Any]],
        branch_preflight: Mapping[str, Any]) -> None:
    """Bind manifest session IDs to the protocol's sealed branch preflight."""
    session_digests = (branch_preflight.get("condition_session_id_digests")
        if isinstance(branch_preflight, Mapping) else None)
    if (not isinstance(manifests, Mapping)
            or set(manifests) != set(_CONDITIONS)
            or not isinstance(session_digests, Mapping)
            or set(session_digests) != set(_CONDITIONS)
            or any(not isinstance(manifests[condition], Mapping)
                or not isinstance(manifests[condition].get("session_id"), str)
                or digest_payload({"session_id":
                    manifests[condition]["session_id"]}) !=
                        session_digests[condition]
                for condition in _CONDITIONS)):
        raise ValueError(
            "durable_learning_worker_baseline_manifest_session_preflight_mismatch")


class DurableLearningAccessProbeInterruptedError(ValueError):
    """A worker-side probe failure with its immutable interruption artifact."""

    def __init__(self, *, artifact_id: str, artifact_digest: str,
            failure_phase: str) -> None:
        self.artifact_id = artifact_id
        self.artifact_digest = artifact_digest
        self.failure_phase = failure_phase
        super().__init__(
            "durable_learning_access_probe_interrupted:" + artifact_id)


class DurableLearningBaselineInterruptedError(ValueError):
    """A baseline worker lifecycle stopped with an immutable interruption record."""

    def __init__(self, *, artifact_id: str, artifact_digest: str,
            failure_phase: str) -> None:
        self.artifact_id = artifact_id
        self.artifact_digest = artifact_digest
        self.failure_phase = failure_phase
        super().__init__(
            "durable_learning_worker_baseline_interrupted:" + artifact_id)


class DurableLearningWorkerBaselineExitError(ValueError):
    """A one-shot baseline worker failed the supervisor exit check."""

    def __init__(self, failure_code: str) -> None:
        if failure_code not in {
                "baseline_worker_exit_timeout",
                "baseline_worker_exit_nonzero"}:
            raise ValueError("durable_learning_worker_exit_failure_code_invalid")
        self.failure_code = failure_code
        super().__init__(failure_code)


def _condition_branch_preflight_artifact_id(protocol: Mapping[str, Any], *,
        schema_version: int = 6) -> str:
    suffix = digest_payload({"protocol_digest": protocol["protocol_digest"]})[7:31]
    if schema_version == 1:
        return "devexp-durable-learning-branch-preflight-" + suffix
    if schema_version == 2:
        return "devexp-durable-learning-branch-preflight-v2-" + suffix
    if schema_version == 3:
        return "devexp-durable-learning-branch-preflight-v3-" + suffix
    if schema_version == 4:
        return "devexp-durable-learning-branch-preflight-v4-" + suffix
    if schema_version == 5:
        return "devexp-durable-learning-branch-preflight-v5-" + suffix
    if schema_version == 6:
        return "devexp-durable-learning-branch-preflight-v6-" + suffix
    raise ValueError("durable_learning_branch_preflight_schema_invalid")


