def _verify_condition_worker_recovery_access_setup(value: Any, *,
        protocol: Mapping[str, Any], profile_pair: Mapping[str, Any],
        recovery_manifests: Mapping[str, Mapping[str, Any]],
        require_complete: bool = False) -> dict[str, Any]:
    """Validate recovery read grants and journal-only modification rights."""
    required = {"schema_version", "protocol_id", "protocol_digest",
        "profile_pair_digest", "manifest_digest_by_condition",
        "grants_by_condition", "all_requested_grants_applied",
        "effective_access_verified", "peer_denial_verified",
        "filesystem_isolation_verified", "retention_contrast_eligible",
        "authority", "setup_digest"}
    if (not isinstance(value, Mapping) or set(value) != required
            or value.get("schema_version") !=
                "sentientos.windows_appcontainer_recovery_access_setup:v1"
            or value.get("protocol_id") != protocol.get("protocol_id")
            or value.get("protocol_digest") != protocol.get("protocol_digest")
            or value.get("profile_pair_digest") !=
                profile_pair.get("profile_pair_digest")
            or not isinstance(recovery_manifests, Mapping)
            or set(recovery_manifests) != set(_CONDITIONS)
            or value.get("manifest_digest_by_condition") != {
                condition: recovery_manifests[condition].get("manifest_digest")
                for condition in _CONDITIONS}
            or type(value.get("all_requested_grants_applied")) is not bool
            or (require_complete and value.get(
                "all_requested_grants_applied") is not True)
            or any(value.get(key) is not False for key in (
                "effective_access_verified", "peer_denial_verified",
                "filesystem_isolation_verified", "retention_contrast_eligible",
                "authority"))
            or not isinstance(value.get("grants_by_condition"), Mapping)
            or set(value["grants_by_condition"]) != set(_CONDITIONS)):
        raise ValueError("durable_learning_worker_recovery_access_setup_invalid")
    profiles = profile_pair.get("condition_profiles")
    if not isinstance(profiles, Mapping) or set(profiles) != set(_CONDITIONS):
        raise ValueError("durable_learning_worker_recovery_profiles_invalid")
    all_applied = True
    for condition in _CONDITIONS:
        grants = value["grants_by_condition"][condition]
        expected = {"state": "condition_receipt_read",
            "history": "condition_receipt_read",
            "session": "condition_receipt_read",
            "journal": "branch_state_modify"}
        if not isinstance(grants, Mapping) or set(grants) != set(expected):
            raise ValueError("durable_learning_worker_recovery_grants_invalid")
        sid = profiles[condition].get("appcontainer_sid")
        manifest_roots = recovery_manifests[condition].get("roots")
        if not isinstance(manifest_roots, Mapping) or set(manifest_roots) != expected.keys():
            raise ValueError(
                "durable_learning_worker_recovery_manifest_roots_invalid")
        for name, policy in expected.items():
            record = grants[name]
            if isinstance(record, Mapping) and record.get("status") == "failed":
                all_applied = False
                if (require_complete or set(record) != {"status", "access_policy",
                        "reason_code", "mutation_state", "authority"}
                        or record.get("access_policy") != policy
                        or not isinstance(record.get("reason_code"), str)
                        or record.get("mutation_state") not in {
                            "not_attempted", "api_call_outcome_unknown",
                            "api_reported_failure", "api_succeeded_unverified",
                            "acl_verified"}
                        or record.get("authority") is not False):
                    raise ValueError(
                        "durable_learning_worker_recovery_grant_failure_invalid")
                continue
            grant = record.get("grant") if isinstance(record, Mapping) else None
            identity = grant.get("directory_identity") if isinstance(
                grant, Mapping) else None
            expected_identity = manifest_roots[name].get("identity")
            if (not isinstance(record, Mapping)
                    or set(record) != {"status", "access_policy", "grant"}
                    or record.get("status") != "applied"
                    or record.get("access_policy") != policy
                    or not isinstance(grant, Mapping)
                    or grant.get("schema_version") !=
                        "sentientos.windows_appcontainer_directory_acl:v1"
                    or not isinstance(identity, Mapping)
                    or type(identity.get("volume_serial")) is not int
                    or not isinstance(identity.get("file_id_hex"), str)
                    or re.fullmatch(r"[0-9a-f]{32}",
                        identity["file_id_hex"]) is None
                    or dict(identity) != expected_identity
                    or grant.get("package_sid") != sid
                    or grant.get("access_policy") != policy
                    or grant.get("directory_allow_ace_present") is not True
                    or grant.get("file_inherit_allow_ace_present") is not True
                    or grant.get("package_sid_deny_ace_present") is not False
                    or grant.get("effective_access_verified") is not False
                    or grant.get("peer_denial_verified") is not False
                    or grant.get("retention_contrast_eligible") is not False
                    or grant.get("authority") is not False):
                raise ValueError(
                    "durable_learning_worker_recovery_grant_invalid")
    if (value.get("all_requested_grants_applied") is not all_applied
            or value.get("setup_digest") != digest_payload({
                key: item for key, item in value.items()
                if key != "setup_digest"})):
        raise ValueError(
            "durable_learning_worker_recovery_access_setup_digest_invalid")
    return dict(value)


def _verify_condition_worker_recovery_exchange_map(*,
        condition_exchanges: Any, protocol: Mapping[str, Any], status: str,
        worker_process_observations: Mapping[str, Any]) -> dict[str, list[dict[str, Any]]]:
    """Revalidate persisted recovery requests and supervisor-bound exchanges."""
    from .durable_learning_condition_worker_rpc import (
        ConditionWorkerRPCDispatcher, verify_condition_worker_rpc_request)
    operations = ["inspect_baseline", "recover_acquisition_receipts",
        "prepare_consolidation_snapshot", "consolidate_branch"]
    if (not isinstance(condition_exchanges, Mapping)
            or not set(condition_exchanges) <= set(_CONDITIONS)):
        raise ValueError("durable_learning_worker_recovery_exchanges_invalid")
    if (status != "interrupted"
            and (set(condition_exchanges) != set(_CONDITIONS)
                or any(not isinstance(condition_exchanges[condition], list)
                    or len(condition_exchanges[condition]) != 4
                    for condition in _CONDITIONS))):
        raise ValueError(
            "durable_learning_worker_recovery_exchange_sequence_incomplete")
    checked: dict[str, list[dict[str, Any]]] = {}
    for condition, raw_rows in condition_exchanges.items():
        if (not isinstance(raw_rows, list) or len(raw_rows) > 4
                or any(not isinstance(row, Mapping) or set(row) != {
                    "request", "exchange"} for row in raw_rows)):
            raise ValueError(
                "durable_learning_worker_recovery_exchanges_invalid")
        rows: list[dict[str, Any]] = []
        for index, raw in enumerate(raw_rows):
            request = verify_condition_worker_rpc_request(raw["request"])
            if (request.get("protocol_id") != protocol.get("protocol_id")
                    or request.get("protocol_digest") !=
                        protocol.get("protocol_digest")
                    or request.get("condition") != condition
                    or request.get("operation") != operations[index]):
                raise ValueError(
                    "durable_learning_worker_recovery_request_scope_invalid")
            exchange = raw["exchange"]
            if exchange is None:
                if status != "interrupted" or index != len(raw_rows) - 1:
                    raise ValueError(
                        "durable_learning_worker_recovery_unobserved_exchange_invalid")
                rows.append({"request": request, "exchange": None})
                continue
            fields = {"schema_version", "request_id", "condition",
                "operation", "response_status", "response_result_digest",
                "peer_process_id", "peer_process_creation_time_100ns",
                "request_response_bound", "process_start_nonce_matched",
                "process_isolation_verified", "filesystem_isolation_verified",
                "retention_contrast_eligible", "authority"}
            has_result = request["operation"] in {
                "inspect_baseline", "recover_acquisition_receipts",
                "prepare_consolidation_snapshot"}
            if has_result:
                fields.add("response_result")
            if (not isinstance(exchange, Mapping) or set(exchange) != fields
                    or exchange.get("schema_version") !=
                        "sentientos.windows_appcontainer_pipe_rpc_exchange:v1"
                    or exchange.get("request_id") != request["request_id"]
                    or exchange.get("condition") != condition
                    or exchange.get("operation") != request["operation"]
                    or exchange.get("response_status") not in {
                        "completed", "rejected", "failed"}
                    or not isinstance(exchange.get("response_result_digest"), str)
                    or _HEX_DIGEST.fullmatch(
                        exchange["response_result_digest"]) is None
                    or type(exchange.get("peer_process_id")) is not int
                    or exchange["peer_process_id"] <= 0
                    or type(exchange.get(
                        "peer_process_creation_time_100ns")) is not int
                    or exchange["peer_process_creation_time_100ns"] <= 0
                    or exchange.get("request_response_bound") is not True
                    or exchange.get("process_start_nonce_matched") is not True
                    or any(exchange.get(key) is not False for key in (
                        "process_isolation_verified", "filesystem_isolation_verified",
                        "retention_contrast_eligible", "authority"))):
                raise ValueError(
                    "durable_learning_worker_recovery_exchange_invalid")
            if has_result:
                result = exchange.get("response_result")
                operation = request["operation"]
                response_status = exchange["response_status"]
                result_required = (response_status == "completed"
                    or (operation == "inspect_baseline"
                        and response_status == "rejected"))
                if ((result_required and not isinstance(result, Mapping))
                        or (operation == "inspect_baseline"
                            and response_status == "failed" and result is not None)
                        or (operation == "prepare_consolidation_snapshot"
                            and response_status != "completed"
                            and result is not None)
                        or (operation == "recover_acquisition_receipts"
                            and response_status != "completed"
                            and result is not None)
                        or (result is not None and
                            (not isinstance(result, Mapping)
                                or ConditionWorkerRPCDispatcher._result_digest(
                                    result) != exchange[
                                        "response_result_digest"]))):
                    raise ValueError(
                        "durable_learning_worker_recovery_exchange_result_mismatch")
                if (operation == "recover_acquisition_receipts"
                        and response_status == "completed"):
                    required = {"receipt_index_digest", "receipt_count",
                        "bundle_digest", "store_artifact_digest",
                        "store_artifact_digest_bound", "receipt_ref_count",
                        "receipt_ref_set_digest", "exact_store_set_match",
                        "store_index_reloaded",
                        "verifier_allowlist_matches_store",
                        "source_invocation_receipts_reverified",
                        "peer_artifacts_opened", "automatic_replay_performed",
                        "authority"}
                    if (set(result) != required
                            or any(not isinstance(result.get(key), str)
                                or _HEX_DIGEST.fullmatch(result[key]) is None
                                for key in ("receipt_index_digest", "bundle_digest",
                                    "store_artifact_digest", "receipt_ref_set_digest"))
                            or type(result.get("receipt_count")) is not int
                            or result["receipt_count"] != len(
                                request["payload"]["task_digests"])
                            or type(result.get("receipt_ref_count")) is not int
                            or result["receipt_ref_count"] < result["receipt_count"]
                            or any(result.get(key) is not True for key in (
                                "store_artifact_digest_bound", "exact_store_set_match",
                                "store_index_reloaded",
                                "verifier_allowlist_matches_store"))
                            or any(result.get(key) is not False for key in (
                                "source_invocation_receipts_reverified",
                                "peer_artifacts_opened", "automatic_replay_performed",
                                "authority"))):
                        raise ValueError(
                            "durable_learning_worker_recovery_receipt_proof_invalid")
            rows.append({"request": request, "exchange": dict(exchange)})
        checked[condition] = rows
    if status in {"completed", "reconciliation_not_available", "interrupted"}:
        terminal = [checked[condition][-1]["exchange"]["response_status"]
            for condition in _CONDITIONS
            if checked.get(condition)
            and checked[condition][-1]["exchange"] is not None]
        prefix_incomplete = any(row["exchange"]["response_status"] != "completed"
            for rows in checked.values() for row in rows[:-1])
        if (prefix_incomplete
                or (status == "completed" and any(item != "completed"
                    for item in terminal))
                or (status == "reconciliation_not_available"
                    and (any(item not in {"completed", "rejected"}
                            for item in terminal)
                        or "rejected" not in terminal))):
            raise ValueError(
                "durable_learning_worker_recovery_terminal_status_mismatch")
    for condition, rows in checked.items():
        observation = worker_process_observations.get(condition)
        if isinstance(observation, Mapping):
            for row in rows:
                exchange = row["exchange"]
                if (exchange is not None
                        and (exchange["peer_process_id"] !=
                                observation.get("process_id")
                            or exchange["peer_process_creation_time_100ns"] !=
                                observation.get(
                                    "process_creation_time_100ns"))):
                    raise ValueError(
                        "durable_learning_worker_recovery_process_binding_mismatch")
    return checked


def _verify_condition_worker_recovery_launch_evidence(*,
        evidence: Any, protocol: Mapping[str, Any], intent: Mapping[str, Any],
        observations: Mapping[str, Any],
        profile_pair: Mapping[str, Any] | None,
        recovery_inputs: Mapping[str, Any] | None) -> None:
    """Bind persisted launch claims to the process identities and intent."""
    if evidence is None:
        return
    profiles = (profile_pair.get("condition_profiles")
        if isinstance(profile_pair, Mapping) else None)
    staged = (recovery_inputs.get("staged_by_condition")
        if isinstance(recovery_inputs, Mapping) else None)
    fields = {"schema_version", "protocol_id", "profile_pair_digest",
        "worker_observations", "both_condition_sids_match_observed_process_tokens",
        "conversation_store_process_isolation_verified",
        "filesystem_isolation_verified", "retention_contrast_eligible",
        "authority", "pipe_endpoints_created_for_both_conditions",
        "pipe_names_by_condition", "supervisor_process_id",
        "supervisor_process_creation_time_100ns",
        "environment_block_sha256_by_condition",
        "receipt_store_artifact_digest_by_condition",
        "access_probe_manifest_digest_by_condition",
        "baseline_runtime_manifest_digest_by_condition",
        "baseline_protocol_environment_bound", "rpc_dispatch_verified"}
    if (not isinstance(evidence, Mapping) or set(evidence) != fields
            or evidence.get("schema_version") !=
                "sentientos.windows_appcontainer_worker_pair_launch:v1"
            or evidence.get("protocol_id") != protocol.get("protocol_id")
            or evidence.get("profile_pair_digest") !=
                (profile_pair.get("profile_pair_digest")
                    if isinstance(profile_pair, Mapping) else None)
            or not isinstance(evidence.get("profile_pair_digest"), str)
            or _HEX_DIGEST.fullmatch(evidence["profile_pair_digest"]) is None
            or evidence.get("both_condition_sids_match_observed_process_tokens")
                is not True
            or evidence.get("pipe_endpoints_created_for_both_conditions") is not True
            or evidence.get("baseline_protocol_environment_bound") is not True
            or any(evidence.get(key) is not False for key in (
                "conversation_store_process_isolation_verified",
                "filesystem_isolation_verified", "retention_contrast_eligible",
                "rpc_dispatch_verified", "authority"))
            or type(evidence.get("supervisor_process_id")) is not int
            or evidence["supervisor_process_id"] <= 0
            or type(evidence.get("supervisor_process_creation_time_100ns"))
                is not int
            or evidence["supervisor_process_creation_time_100ns"] <= 0):
        raise ValueError(
            "durable_learning_worker_recovery_launch_evidence_invalid")
    executable_digests = intent.get("worker_executable_digest_by_condition")
    worker_observations = evidence.get("worker_observations")
    if (not isinstance(worker_observations, Mapping)
            or set(worker_observations) != set(_CONDITIONS)
            or not isinstance(executable_digests, Mapping)
            or set(executable_digests) != set(_CONDITIONS)):
        raise ValueError(
            "durable_learning_worker_recovery_launch_observations_invalid")
    for condition in _CONDITIONS:
        worker = worker_observations[condition]
        saved = observations.get(condition)
        profile = profiles.get(condition) if isinstance(profiles, Mapping) else None
        input_row = staged.get(condition) if isinstance(staged, Mapping) else None
        if (not isinstance(worker, Mapping) or not isinstance(saved, Mapping)
                or not isinstance(profile, Mapping)
                or not isinstance(input_row, Mapping)
                or worker.get("protocol_id") != protocol.get("protocol_id")
                or worker.get("condition") != condition
                or worker.get("process_id") != saved.get("process_id")
                or worker.get("process_creation_time_100ns") !=
                    saved.get("process_creation_time_100ns")
                or digest_payload(dict(worker)) != saved.get(
                    "observation_digest")
                or worker.get("requested_executable_sha256") !=
                    executable_digests.get(condition)
                or not isinstance(worker.get("requested_executable_sha256"), str)
                or _HEX_DIGEST.fullmatch(
                    worker["requested_executable_sha256"]) is None
                or worker.get("token_is_appcontainer") is not True
                or not isinstance(worker.get("appcontainer_sid"), str)
                or re.fullmatch(r"S-1-15-2-(?:[0-9]+-)*[0-9]+",
                    worker["appcontainer_sid"]) is None
                or worker["appcontainer_sid"].casefold() !=
                    str(profile.get("appcontainer_sid", "")).casefold()
                or worker.get("profile_name") != profile.get("profile_name")
                or worker.get("profile_local_data_path") != profile.get(
                    "profile_local_data_path")
                or worker.get("profile_local_data_root_identity") != profile.get(
                    "profile_local_data_root_identity")
                or worker.get("enabled_capability_count") != 0
                or worker.get("inherited_handles_requested") is not False
                or worker.get("job_object_bound") is not True
                or worker.get("job_active_process_limit") != 1
                or worker.get("profile_sid_matches_observed_process_sid")
                    is not True
                or worker.get("authority") is not False):
            raise ValueError(
                "durable_learning_worker_recovery_launch_process_binding_invalid")
    map_specs = {
        "pipe_names_by_condition": (set(_CONDITIONS), False),
        "environment_block_sha256_by_condition": (set(_CONDITIONS), True),
        "receipt_store_artifact_digest_by_condition": (set(_CONDITIONS), True),
        "access_probe_manifest_digest_by_condition": (None, True),
        "baseline_runtime_manifest_digest_by_condition": (set(_CONDITIONS), True)}
    for key, (expected, is_digest_map) in map_specs.items():
        value = evidence.get(key)
        if (not isinstance(value, Mapping)
                or (expected is not None and set(value) != expected)
                or (expected is None and set(value) not in (set(),
                    set(_CONDITIONS)))):
            raise ValueError(
                "durable_learning_worker_recovery_launch_map_invalid")
    expected_environment = {condition: worker_observations[condition].get(
        "environment_block_sha256") for condition in _CONDITIONS}
    expected_receipts = {condition: staged[condition][
        "acquisition_receipt_bundle_artifact"].get("artifact_digest")
        for condition in _CONDITIONS}
    expected_manifests = {condition: staged[condition]["runtime_manifest"].get(
        "manifest_digest") for condition in _CONDITIONS}
    if (dict(evidence["environment_block_sha256_by_condition"]) !=
            expected_environment
            or dict(evidence["receipt_store_artifact_digest_by_condition"]) !=
                expected_receipts
            or dict(evidence["baseline_runtime_manifest_digest_by_condition"]) !=
                expected_manifests
            or evidence["access_probe_manifest_digest_by_condition"] != {}):
        raise ValueError(
            "durable_learning_worker_recovery_launch_input_binding_invalid")
        if is_digest_map and any(not isinstance(item, str)
                or _HEX_DIGEST.fullmatch(item) is None
                for item in value.values()):
            raise ValueError(
                "durable_learning_worker_recovery_launch_map_invalid")
    pipe_names = list(evidence["pipe_names_by_condition"].values())
    if (any(not isinstance(name, str) or not name or len(name) > 512
            for name in pipe_names)
            or len(set(pipe_names)) != len(pipe_names)):
        raise ValueError(
            "durable_learning_worker_recovery_launch_pipe_names_invalid")


def _verify_condition_worker_recovery_lifecycle(*,
        status: str, failure_phase: str | None, launch_evidence: Any,
        exchanges: Mapping[str, Any], observations: Mapping[str, Any]) -> None:
    """Require process-pair evidence before accepting worker RPC or terminal claims."""
    terminal = status in {"completed", "reconciliation_not_available"}
    conditions_with_exchanges = {condition for condition, rows in exchanges.items()
        if rows}
    if launch_evidence is None:
        if (terminal or conditions_with_exchanges
                or (status == "interrupted"
                    and failure_phase != "worker_pair_launch")
                or observations and (status != "interrupted"
                    or failure_phase != "worker_pair_launch")):
            raise ValueError(
                "durable_learning_worker_recovery_launch_evidence_required")
        return
    if (not isinstance(launch_evidence, Mapping)
            or set(observations) != set(_CONDITIONS)
            or not conditions_with_exchanges and terminal):
        raise ValueError(
            "durable_learning_worker_recovery_launch_lifecycle_invalid")
    if any(condition not in observations for condition in conditions_with_exchanges):
        raise ValueError(
            "durable_learning_worker_recovery_exchange_without_process_invalid")


def _verify_condition_worker_baseline_read_access_setup(value: Any, *,
        protocol: Mapping[str, Any], profile_pair: Mapping[str, Any],
        require_complete: bool = False) -> dict[str, Any]:
    """Validate condition-local read-only grants without treating them as isolation."""
    root_names = {"state", "history", "session", "journal"}
    if (not isinstance(value, Mapping)
            or set(value) != {"schema_version", "protocol_id",
                "protocol_digest", "profile_pair_digest",
                "manifest_digest_by_condition", "grants_by_condition",
                "all_requested_grants_applied", "effective_access_verified",
                "peer_denial_verified", "filesystem_isolation_verified",
                "retention_contrast_eligible", "authority", "setup_digest"}
            or value.get("schema_version") !=
                "sentientos.windows_appcontainer_baseline_read_access_setup:v1"
            or value.get("protocol_id") != protocol.get("protocol_id")
            or value.get("protocol_digest") != protocol.get("protocol_digest")
            or value.get("profile_pair_digest") !=
                profile_pair.get("profile_pair_digest")
            or type(value.get("all_requested_grants_applied")) is not bool
            or (require_complete and value.get(
                "all_requested_grants_applied") is not True)
            or any(value.get(key) is not False for key in (
                "effective_access_verified", "peer_denial_verified",
                "filesystem_isolation_verified", "retention_contrast_eligible",
                "authority"))
            or not isinstance(value.get("manifest_digest_by_condition"), Mapping)
            or set(value["manifest_digest_by_condition"]) != set(_CONDITIONS)
            or any(not isinstance(digest, str)
                or _HEX_DIGEST.fullmatch(digest) is None
                for digest in value["manifest_digest_by_condition"].values())
            or not isinstance(value.get("grants_by_condition"), Mapping)
            or set(value["grants_by_condition"]) != set(_CONDITIONS)):
        raise ValueError(
            "durable_learning_worker_baseline_read_access_setup_invalid")
    profiles = profile_pair.get("condition_profiles")
    if not isinstance(profiles, Mapping) or set(profiles) != set(_CONDITIONS):
        raise ValueError(
            "durable_learning_worker_baseline_read_access_profiles_invalid")
    applied = True
    for condition in _CONDITIONS:
        grants = value["grants_by_condition"][condition]
        if not isinstance(grants, Mapping) or set(grants) != root_names:
            raise ValueError(
                "durable_learning_worker_baseline_read_access_grants_invalid")
        sid = profiles[condition].get("appcontainer_sid")
        for record in grants.values():
            if isinstance(record, Mapping) and record.get("status") == "failed":
                applied = False
                if (require_complete or set(record) != {"status",
                        "reason_code", "mutation_state", "authority"}
                        or not isinstance(record.get("reason_code"), str)
                        or record.get("mutation_state") not in {
                            "not_attempted", "api_call_outcome_unknown",
                            "api_reported_failure", "api_succeeded_unverified",
                            "acl_verified"}
                        or record.get("authority") is not False):
                    raise ValueError(
                        "durable_learning_worker_baseline_read_access_failure_invalid")
                continue
            grant = record.get("grant") if isinstance(record, Mapping) else None
            identity = (grant.get("directory_identity")
                if isinstance(grant, Mapping) else None)
            if (not isinstance(record, Mapping)
                    or set(record) != {"status", "grant"}
                    or record.get("status") != "applied"
                    or not isinstance(grant, Mapping)
                    or grant.get("schema_version") !=
                        "sentientos.windows_appcontainer_directory_acl:v1"
                    or not isinstance(identity, Mapping)
                    or type(identity.get("volume_serial")) is not int
                    or not isinstance(identity.get("file_id_hex"), str)
                    or re.fullmatch(r"[0-9a-f]{32}",
                        identity["file_id_hex"]) is None
                    or not isinstance(grant.get("package_sid"), str)
                    or not isinstance(sid, str)
                    or grant["package_sid"].casefold() != sid.casefold()
                    or grant.get("access_policy") != "condition_receipt_read"
                    or grant.get("directory_allow_ace_present") is not True
                    or grant.get("file_inherit_allow_ace_present") is not True
                    or grant.get("package_sid_deny_ace_present") is not False
                    or grant.get("effective_access_verified") is not False
                    or grant.get("peer_denial_verified") is not False
                    or grant.get("retention_contrast_eligible") is not False
                    or grant.get("authority") is not False):
                raise ValueError(
                    "durable_learning_worker_baseline_read_access_grant_invalid")
    if (value.get("all_requested_grants_applied") is not applied
            or value.get("setup_digest") != digest_payload({
                key: item for key, item in value.items()
                if key != "setup_digest"})):
        raise ValueError(
            "durable_learning_worker_baseline_read_access_setup_digest_invalid")
    return dict(value)
