    def persist_condition_worker_access_probe_interruption(self, *,
            protocol: Mapping[str, Any],
            runtime_access_setup: Mapping[str, Any],
            failure_phase: str, launch_call_returned: bool,
            worker_process_observations: Mapping[str, Mapping[str, Any]],
            created_endpoint_conditions: Sequence[str],
            accepted_pipe_conditions: Sequence[str],
            cleanup_errors: Sequence[str], failure_type: str) -> dict[str, Any]:
        """Seal a failed worker lifecycle so its protocol cannot be retried."""
        self._require_protocol_persisted(protocol)
        branch_preflight = self.load_condition_branch_preflight(protocol)
        profile_pair_artifact = self.load_condition_appcontainer_profile_pair(
            protocol)
        if profile_pair_artifact is None:
            raise ValueError(
                "durable_learning_access_probe_profile_pair_required")
        semantic = {"schema_version":
                "sentientos.durable_learning_worker_access_probe_interruption:v1",
            "protocol_id": protocol["protocol_id"],
            "protocol_digest": protocol["protocol_digest"],
            "branch_preflight_id": branch_preflight["preflight_id"],
            "branch_preflight_digest": branch_preflight["preflight_digest"],
            "profile_pair_artifact_id": profile_pair_artifact["artifact_id"],
            "profile_pair_artifact_digest":
                profile_pair_artifact["artifact_digest"],
            "runtime_access_setup": dict(runtime_access_setup),
            "failure_phase": failure_phase, "launch_call_started": True,
            "launch_call_returned": launch_call_returned,
            "worker_process_observations": {
                condition: dict(observation)
                for condition, observation in worker_process_observations.items()},
            "created_endpoint_conditions": list(created_endpoint_conditions),
            "accepted_pipe_conditions": list(accepted_pipe_conditions),
            "cleanup_errors": list(cleanup_errors),
            "failure_type": failure_type, "retry_blocked": True,
            "authority": False}
        artifact_digest = digest_payload(semantic)
        artifact_id = "devexp-durable-learning-access-probe-interruption-" + \
            protocol["protocol_id"][-24:] + "-" + artifact_digest[:24]
        artifact = {**semantic, "artifact_digest": artifact_digest,
            "artifact_id": artifact_id}
        from .durable_learning_access_probe_artifact import (
            verify_worker_access_probe_interruption)
        verify_worker_access_probe_interruption(artifact, protocol=protocol,
            branch_preflight=branch_preflight,
            profile_pair_artifact=profile_pair_artifact)
        self._store._write_immutable(
            self._store.runs / f"{artifact_id}.json", artifact)
        persisted = self.load_condition_worker_access_probe_interruption(
            protocol=protocol, artifact_id=artifact_id)
        if persisted != artifact:
            raise ValueError(
                "durable_learning_access_probe_interruption_persistence_mismatch")
        return persisted

