def _project_durable_learning_report_v27(report: Mapping[str, Any]
        ) -> dict[str, Any]:
    """Restore v27's metadata-only transfer report for stored evaluations."""
    projected = _project_durable_learning_report_v28(report)
    projected["schema_version"] = (
        "sentientos.durable_learning_outcome_set_verification:v27")
    transfer = projected.get("task_family_transfer_structure")
    if isinstance(transfer, Mapping):
        transfer = dict(transfer)
        transfer["schema_version"] = (
            "sentientos.durable_learning_task_family_transfer_structure:v1")
        for field in ("acquisition_unique_probe_input_count",
                "acquisition_probe_input_occurrence_count",
                "delayed_probe_unique_probe_input_count",
                "delayed_probe_input_occurrence_count",
                "cross_phase_probe_input_overlap_count"):
            transfer.pop(field, None)
        shared = transfer.get("shared_declared_families")
        if isinstance(shared, list):
            transfer["shared_declared_families"] = [
                {key: value for key, value in row.items()
                    if key not in {"acquisition_unique_probe_input_count",
                        "acquisition_probe_input_occurrence_count",
                        "delayed_probe_unique_probe_input_count",
                        "delayed_probe_input_occurrence_count",
                        "cross_phase_probe_input_overlap_count"}}
                if isinstance(row, Mapping) else row for row in shared]
        transfer["interpretation"] = (
            "declared_metadata_alignment_only_not_task_equivalence_or_transfer")
        projected["task_family_transfer_structure"] = transfer
    return projected


def _project_durable_learning_report_v28(report: Mapping[str, Any]
        ) -> dict[str, Any]:
    """Restore v28's family macro without leave-one-out sensitivity fields."""
    projected = _project_durable_learning_report_v29(report)
    projected["schema_version"] = (
        "sentientos.durable_learning_outcome_set_verification:v28")
    macro = projected.get("task_family_macro_effect_summary")
