def _project_durable_learning_report_v29(report: Mapping[str, Any]
        ) -> dict[str, Any]:
    """Restore v29 without the later acquisition/probe trajectory report."""
    projected = _project_durable_learning_report_v30(report)
    projected["schema_version"] = (
        "sentientos.durable_learning_outcome_set_verification:v29")
    projected.pop("task_family_phase_effect_trajectory", None)
    return projected


def _project_durable_learning_report_v31(report: Mapping[str, Any]
        ) -> dict[str, Any]:
    """Restore v31 confidence summaries without task-level Brier spread."""
    projected = dict(report)
    projected["schema_version"] = (
        "sentientos.durable_learning_outcome_set_verification:v31")
    summaries = projected.get("confidence_score_summary")
    if isinstance(summaries, Mapping):
        summaries = {phase: (dict(summary)
            if isinstance(summary, Mapping) else summary)
            for phase, summary in summaries.items()}
        for summary in summaries.values():
            if not isinstance(summary, dict):
                continue
            paired = summary.get("paired_answered_probe_comparison")
            if isinstance(paired, Mapping):
                paired = dict(paired)
                paired.pop("task_level_effect_summary", None)
                summary["paired_answered_probe_comparison"] = paired
        projected["confidence_score_summary"] = summaries
    return projected


def _verify_condition_worker_access_probe_manifest_pair(*, protocol_id: str,
        profiles: Mapping[str, Any],
        manifests: Mapping[str, Mapping[str, Any]]) -> dict[str, dict[str, Any]]:
    """Verify both manifests and their shared reciprocal sentinel identity."""
    from .windows_appcontainer_access import (
        verify_condition_worker_access_probe_manifest)
    if (not isinstance(profiles, Mapping)
            or set(profiles) != set(_CONDITIONS)
            or not isinstance(manifests, Mapping)
            or set(manifests) != set(_CONDITIONS)):
        raise ValueError("durable_learning_access_probe_manifest_pair_invalid")
    checked = {condition: verify_condition_worker_access_probe_manifest(
        manifests[condition], protocol_id=protocol_id, condition=condition,
        appcontainer_sid=profiles[condition]["appcontainer_sid"])
        for condition in _CONDITIONS}
    available, withheld = (checked[_CONDITIONS[0]], checked[_CONDITIONS[1]])
    if (available["own_sentinel"] != withheld["peer_sentinel"]
            or available["peer_sentinel"] != withheld["own_sentinel"]
            or available["scorer_sentinel"] != withheld["scorer_sentinel"]):
        raise ValueError(
            "durable_learning_access_probe_manifest_pair_mismatch")
    return checked


class DurableDevelopmentalLearningRunner:
    """Run the frozen Phase C calls through an injected governed executor.

    The executor owns chat/session creation and must pass the supplied guard to
    the production pre-effect callback. The runner seals every returned
    outcome and never exposes fixture oracle parameters in the prompt.
    """

    def __init__(self, *, protocol_store: DurableDevelopmentalLearningProtocolStore,
            invocation_executor: Callable[..., Mapping[str, Any]],
            experience_source: ResidentDevelopmentalLearningExperienceSource,
            retained_state_snapshot_resolver: Callable[[], Mapping[str, Any]],
            condition_blind_scorer: Callable[..., Mapping[str, Any]],
            allow_descriptive_only_execution: bool = False,
            condition_branches: Mapping[str, DurableLearningConditionBranch] | None = None) -> None:
        if (not isinstance(protocol_store, DurableDevelopmentalLearningProtocolStore)
                or not callable(invocation_executor)
                or not callable(getattr(experience_source, "records_for_prompt", None))
                or not callable(retained_state_snapshot_resolver)
                or not callable(condition_blind_scorer)
                or (condition_branches is not None and
                    (not isinstance(condition_branches, Mapping)
                     or set(condition_branches) != set(_CONDITIONS)
                     or any(not isinstance(branch,
                         DurableLearningConditionBranch)
                         for branch in condition_branches.values())))
                or type(allow_descriptive_only_execution) is not bool):
            raise ValueError("durable_learning_runner_dependencies_invalid")
        self._store = protocol_store
        self._executor = invocation_executor
        self._experience_source = experience_source
        self._state_snapshot_resolver = retained_state_snapshot_resolver
        self._receipt_verifier = protocol_store._receipt_verifier
        self._scorer = condition_blind_scorer
        self._allow_descriptive_only_execution = (
            allow_descriptive_only_execution)
        self._condition_branches = (dict(condition_branches)
            if condition_branches is not None else None)

    def _branch_for(self, condition: str) -> DurableLearningConditionBranch | None:
        if self._condition_branches is None:
            return None
        return self._condition_branches.get(condition)

    def _experience_source_for(self, condition: str) -> Any:
        branch = self._branch_for(condition)
        return branch.experience_source if branch is not None else self._experience_source

    def _snapshot_resolver_for(self, condition: str) -> Callable[[], Mapping[str, Any]]:
        branch = self._branch_for(condition)
        return (branch.retained_state_snapshot_resolver if branch is not None
            else self._state_snapshot_resolver)

    def _executor_for(self, condition: str) -> Callable[..., Mapping[str, Any]]:
        branch = self._branch_for(condition)
        return branch.invocation_executor if branch is not None else self._executor

    def prepare_condition_worker_recovery_inputs(self, *,
            protocol: Mapping[str, Any], appcontainer_sids: Mapping[str, str],
            journal_roots_by_condition: Mapping[str, Any],
            acquisition_bundle_roots_by_condition: Mapping[str, Any],
            invocation_receipt_roots_by_condition: Mapping[str, Any]
            ) -> dict[str, Any]:
        """Stage condition-local persisted evidence and pinned branch manifests.

        This prepares immutable inputs only. Journal write ACL setup and worker
        launch remain separate so partial access setup cannot be mistaken for
        a completed recovery run.
        """
        from pathlib import Path
        from .durable_learning_condition_receipts import (
            build_condition_scoped_acquisition_receipt_bundle,
            stage_condition_scoped_acquisition_receipt_bundle)
        from .durable_learning_invocation_receipts import (
            stage_condition_invocation_receipts)
        from .durable_learning_condition_worker_backend import (
            build_condition_worker_baseline_runtime_manifest_pair)
        from .windows_handle_custody import observe_private_directory_identity

        maps = (appcontainer_sids, journal_roots_by_condition,
            acquisition_bundle_roots_by_condition,
            invocation_receipt_roots_by_condition)
        if (not isinstance(protocol, Mapping)
                or any(not isinstance(value, Mapping)
                    or set(value) != set(_CONDITIONS) for value in maps)
                or self._condition_branches is None):
            raise ValueError(
                "durable_learning_worker_recovery_preparation_arguments_invalid")
        self._verify_protocol_is_persisted(protocol)
        self._verify_condition_branch_bindings(protocol, baseline=False)
        outcomes = self._store.load_outcomes(protocol, phase="acquisition")

        def private_root(value: Any) -> tuple[Path, tuple[int, bytes]]:
            root = Path(value)
            if not root.is_absolute() or not root.is_dir():
                raise ValueError(
                    "durable_learning_worker_recovery_root_invalid")
            root = root.resolve(strict=True)
            identity = observe_private_directory_identity(root)
            if (not isinstance(identity, tuple) or len(identity) != 2
                    or type(identity[0]) is not int
                    or not isinstance(identity[1], bytes)
                    or len(identity[1]) != 16):
                raise ValueError(
                    "durable_learning_worker_recovery_root_identity_invalid")
            return root, identity

        input_roots: dict[str, dict[str, tuple[Path, tuple[int, bytes]]]] = {}
        all_paths: list[Path] = []
        staged_identity_keys: list[tuple[int, bytes]] = []
        branch_identity_keys: list[tuple[int, bytes]] = []
        for condition in sorted(_CONDITIONS):
            branch = self._condition_branches[condition]
            owner = branch.experience_source._owner
            staged_roots = {
                "bundle": private_root(
                    acquisition_bundle_roots_by_condition[condition]),
                "invocation": private_root(
                    invocation_receipt_roots_by_condition[condition]),
                "journal": private_root(
                    journal_roots_by_condition[condition])}
            branch_roots = {
                "state": Path(owner.config.state_root).resolve(strict=True),
                "history": Path(owner.writeback.store.root).resolve(strict=True),
                "session": Path(branch.conversation_session_store.root).resolve(
                    strict=True)}
            input_roots[condition] = staged_roots
            all_paths.extend(path for path, _identity in staged_roots.values())
            staged_identity_keys.extend(identity
                for _path, identity in staged_roots.values())
            all_paths.extend(branch_roots.values())
            branch_identity_keys.extend(observe_private_directory_identity(root)
                for root in branch_roots.values())
        if len(set(staged_identity_keys)) != len(staged_identity_keys):
            raise ValueError(
                "durable_learning_worker_recovery_staged_identity_overlap")
        if set(staged_identity_keys) & set(branch_identity_keys):
            raise ValueError(
                "durable_learning_worker_recovery_identity_overlap")
        for index, left in enumerate(all_paths):
            for right in all_paths[index + 1:]:
                if (left == right or left in right.parents
                        or right in left.parents):
                    raise ValueError(
                        "durable_learning_worker_recovery_roots_overlap")

        staged: dict[str, Any] = {}
        roots: dict[str, dict[str, Path]] = {}
        sessions: dict[str, str] = {}
        for condition in sorted(_CONDITIONS):
            branch = self._condition_branches[condition]
            owner = branch.experience_source._owner
            source_verifier = getattr(owner,
                "invocation_receipt_verifier", None)
            if not callable(getattr(source_verifier,
                    "verify_persisted_invocation_receipt", None)):
                source_verifier = self._receipt_verifier
            sid = appcontainer_sids[condition]
            if not isinstance(sid, str) or not sid:
                raise ValueError(
                    "durable_learning_worker_recovery_sid_invalid")
            bundle_root, bundle_identity = input_roots[condition]["bundle"]
            invocation_root, invocation_identity = input_roots[condition][
                "invocation"]
            journal_root, _journal_identity = input_roots[condition]["journal"]
            branch_roots = {"state": Path(owner.config.state_root).resolve(
                    strict=True),
                "history": Path(owner.writeback.store.root).resolve(strict=True),
                "session": Path(branch.conversation_session_store.root).resolve(
                    strict=True), "journal": journal_root}
            selected = [row for row in outcomes
                if row.get("condition") == condition]
            bundle = build_condition_scoped_acquisition_receipt_bundle(
                protocol=protocol, condition=condition, outcomes=selected,
                invocation_receipt_verifier=self._receipt_verifier)
            bundle_artifact, bundle_access = (
                stage_condition_scoped_acquisition_receipt_bundle(
                    root=bundle_root,
                    expected_root_identity=bundle_identity,
                    appcontainer_sid=sid, protocol=protocol,
                    condition=condition, bundle=bundle))

            records = owner._recover_observation_ticks(include_records=True)
            if not isinstance(records, Mapping):
                raise ValueError(
                    "durable_learning_worker_recovery_observations_invalid")
            refs: dict[str, str] = {}
            for record in records.values():
                if not isinstance(record, Mapping):
                    raise ValueError(
                        "durable_learning_worker_recovery_observation_invalid")
                receipt_id = record.get("inference_receipt_id")
                receipt_digest = record.get("inference_receipt_digest")
                if receipt_id is None and receipt_digest is None:
                    continue
                if not isinstance(receipt_id, str) or not isinstance(
                        receipt_digest, str):
                    raise ValueError(
                        "durable_learning_worker_recovery_observation_receipt_invalid")
                if receipt_id in refs and refs[receipt_id] != receipt_digest:
                    raise ValueError(
                        "durable_learning_worker_recovery_receipt_conflict")
                refs[receipt_id] = receipt_digest
            for outcome in selected:
                receipt_id = outcome.get("invocation_receipt_id")
                receipt_digest = outcome.get("invocation_receipt_digest")
                if not isinstance(receipt_id, str) or not isinstance(
                        receipt_digest, str):
                    raise ValueError(
                        "durable_learning_worker_recovery_outcome_receipt_invalid")
                if receipt_id in refs and refs[receipt_id] != receipt_digest:
                    raise ValueError(
                        "durable_learning_worker_recovery_receipt_conflict")
                refs[receipt_id] = receipt_digest
            if not refs:
                raise ValueError(
                    "durable_learning_worker_recovery_receipt_set_empty")
            invocation_artifact, invocation_access = (
                stage_condition_invocation_receipts(root=invocation_root,
                    expected_root_identity=invocation_identity,
                    appcontainer_sid=sid, protocol=protocol,
                    condition=condition,
                    receipt_refs=[{"receipt_id": receipt_id,
                        "receipt_digest": refs[receipt_id]}
                        for receipt_id in sorted(refs)],
                    source_verifier=source_verifier))
            roots[condition] = branch_roots
            sessions[condition] = branch.session_id
            staged[condition] = {
                "acquisition_receipt_bundle_artifact": bundle_artifact,
                "acquisition_receipt_bundle_access": bundle_access,
                "acquisition_receipt_bundle_root": str(bundle_root),
                "invocation_receipt_artifact": invocation_artifact,
                "invocation_receipt_access": invocation_access,
                "invocation_receipt_root": str(invocation_root),
                "invocation_receipt_count": len(refs), "authority": False}

        manifests = build_condition_worker_baseline_runtime_manifest_pair(
            protocol=protocol, appcontainer_sids=appcontainer_sids,
            session_ids=sessions, roots_by_condition=roots)
        for condition, manifest in manifests.items():
            staged[condition]["runtime_manifest"] = manifest
        inputs = {"schema_version":
                "sentientos.durable_learning_condition_recovery_inputs:v1",
            "protocol_id": protocol["protocol_id"],
            "staged_by_condition": staged, "manifest_pair_built": True,
            "worker_launched": False, "journal_write_access_granted": False,
            "authority": False}
        return self._store.persist_condition_worker_recovery_inputs(
            protocol=protocol, inputs=inputs)

    def prepare_condition_worker_recovery_setup(self, *,
            protocol: Mapping[str, Any], runtime_roots: Mapping[str, Any]
            ) -> dict[str, Any]:
        """Grant and persist the exact ACL setup required for recovery launch."""
        from pathlib import Path
        from .windows_appcontainer_access import (
            condition_worker_access_probe_mutex,
            grant_condition_worker_recovery_access,
            grant_condition_worker_runtime_read_execute)

        if not isinstance(protocol, Mapping) or not isinstance(runtime_roots, Mapping):
            raise ValueError(
                "durable_learning_worker_recovery_setup_arguments_invalid")
        protocol_id = protocol.get("protocol_id")
        with condition_worker_access_probe_mutex(protocol_id):
            self._verify_protocol_is_persisted(protocol)
            self._verify_condition_branch_bindings(protocol, baseline=False)
            prior_setup = self._store.load_condition_worker_recovery_setup(
                protocol=protocol)
            if prior_setup is not None:
                return prior_setup
            inputs = self._store.load_condition_worker_recovery_inputs(
                protocol=protocol)
            profile = self._store.load_condition_appcontainer_profile_pair(
                protocol)
            if inputs is None or profile is None:
                raise ValueError(
                    "durable_learning_worker_recovery_inputs_or_profile_missing")
            branch_roots = [Path(row["path"]).resolve(strict=True)
                for condition in _CONDITIONS
                for row in inputs["staged_by_condition"][condition][
                    "runtime_manifest"]["roots"].values()]
            staged_roots = [Path(inputs["staged_by_condition"][condition][key])
                .resolve(strict=True) for condition in _CONDITIONS
                for key in ("acquisition_receipt_bundle_root",
                    "invocation_receipt_root")]
            try:
                runtime_paths = [Path(value).resolve(strict=True)
                    for value in runtime_roots.values()]
                if (not runtime_paths
                        or any(not path.is_dir() for path in runtime_paths)
                        or any(root == other or root in other.parents
                            or other in root.parents
                            for root in runtime_paths
                            for other in (*branch_roots, *staged_roots))):
                    raise ValueError("recovery_runtime_root_overlap")
            except (OSError, RuntimeError, TypeError, ValueError) as exc:
                raise ValueError(
                    "durable_learning_worker_recovery_runtime_roots_invalid") from exc
            runtime_setup = grant_condition_worker_runtime_read_execute(
                protocol_id=protocol_id,
                profile_pair=profile["profile_pair"],
                runtime_roots=runtime_roots)
            recovery_setup = grant_condition_worker_recovery_access(
                protocol=protocol, profile_pair=profile["profile_pair"],
                recovery_manifests={condition:
                    inputs["staged_by_condition"][condition]["runtime_manifest"]
                    for condition in _CONDITIONS})
            try:
                artifact = self._store.persist_condition_worker_recovery_setup(
                    protocol=protocol, runtime_access_setup=runtime_setup,
                    recovery_access_setup=recovery_setup)
            except BaseException:
                from .windows_appcontainer_access import (
                    quarantine_active_condition_worker_access_probe)
                quarantine_active_condition_worker_access_probe(protocol_id)
                raise
            return artifact

    def launch_condition_worker_recovery(self, *,
            protocol: Mapping[str, Any],
            worker_specs: Mapping[str, Mapping[str, Any]],
            timeout_ms: int = 30_000) -> dict[str, Any]:
        """Run one persisted, four-operation, no-inference recovery attempt."""
        import os
        from pathlib import Path
        from .durable_learning_condition_receipts import (
            load_staged_condition_scoped_acquisition_receipt_bundle)
        from .windows_appcontainer_access import (
            condition_worker_access_probe_mutex)
        from .windows_appcontainer_pipe import (
            exchange_condition_worker_rpc)
        from .windows_appcontainer_process import (
            launch_condition_appcontainer_worker_pair_with_pipes)

        if (not isinstance(protocol, Mapping)
                or not isinstance(worker_specs, Mapping)
                or set(worker_specs) != set(_CONDITIONS)
                or type(timeout_ms) is not int
                or not 1 <= timeout_ms <= 30_000):
            raise ValueError(
                "durable_learning_worker_recovery_launch_arguments_invalid")
        protocol_id = protocol.get("protocol_id")
        with condition_worker_access_probe_mutex(protocol_id):
            self._verify_protocol_is_persisted(protocol)
            self._verify_condition_branch_bindings(protocol, baseline=False)
            prior_run = self._store.load_condition_worker_recovery_run(
                protocol=protocol)
            if prior_run is not None:
                return prior_run
            setup = self._store.load_condition_worker_recovery_setup(
                protocol=protocol)
            inputs = self._store.load_condition_worker_recovery_inputs(
                protocol=protocol)
            profile_artifact = self._store.load_condition_appcontainer_profile_pair(
                protocol)
            if (setup is None or inputs is None or profile_artifact is None
                    or setup.get("all_requested_grants_applied") is not True):
                raise ValueError(
                    "durable_learning_worker_recovery_setup_incomplete")
            from .windows_handle_custody import observe_directory_identity
            runtime_setup = setup.get("runtime_access_setup")
            runtime_rows = (runtime_setup.get("runtime_roots")
                if isinstance(runtime_setup, Mapping) else None)
            if not isinstance(runtime_rows, Mapping) or not runtime_rows:
                raise ValueError(
                    "durable_learning_worker_recovery_runtime_roots_missing")
            runtime_paths: list[Path] = []
            for row in runtime_rows.values():
                if not isinstance(row, Mapping):
                    raise ValueError(
                        "durable_learning_worker_recovery_runtime_root_invalid")
                root = Path(row["path"]).resolve(strict=True)
                identity = observe_directory_identity(root)
                if (not root.is_dir()
                        or identity != (row["volume_serial"],
                            bytes.fromhex(row["file_id_hex"]))):
                    raise ValueError(
                        "durable_learning_worker_recovery_runtime_root_identity_changed")
                runtime_paths.append(root)

            def runtime_covers(path: Path) -> bool:
                return any(path == root or root in path.parents
                    for root in runtime_paths)

            for condition in _CONDITIONS:
                spec = worker_specs[condition]
                argv = spec.get("argv") if isinstance(spec, Mapping) else None
                if (not isinstance(spec, Mapping)
                        or set(spec) != {"argv", "cwd", "environment"}
                        or not isinstance(argv, Sequence)
                        or isinstance(argv, (str, bytes)) or len(argv) != 3
                        or argv[1] != "-m"
                        or argv[2] !=
                            "sentientos.durable_learning_condition_recovery_worker_entrypoint"
                        or any(not isinstance(arg, str) for arg in argv)
                        or not isinstance(spec.get("environment"), Mapping)
                        or any(not isinstance(key, str)
                            or not isinstance(value, str)
                            for key, value in spec["environment"].items())):
                    raise ValueError(
                        "durable_learning_worker_recovery_worker_spec_invalid")
                executable = Path(argv[0]).resolve(strict=True)
                cwd = Path(spec["cwd"]).resolve(strict=True)
                if (not executable.is_file() or not cwd.is_dir()
                        or not runtime_covers(executable)
                        or not runtime_covers(cwd)):
                    raise ValueError(
                        "durable_learning_worker_recovery_worker_runtime_ungranted")
                environment = spec["environment"]
                reserved_environment = {"sentientos_worker_pipe_name",
                    "sentientos_worker_appcontainer_sid",
                    "sentientos_worker_protocol_id", "sentientos_worker_condition",
                    "sentientos_worker_protocol_digest",
                    "sentientos_supervisor_process_id",
                    "sentientos_supervisor_creation_time_100ns",
                    "sentientos_worker_receipt_bundle_root",
                    "sentientos_worker_receipt_store_artifact_json",
                    "sentientos_worker_invocation_receipt_root",
                    "sentientos_worker_invocation_receipt_store_artifact_json",
                    "sentientos_worker_access_probe_manifest_json",
                    "sentientos_worker_baseline_protocol_json",
                    "sentientos_worker_baseline_runtime_manifest_json",
                    "sentientos_worker_start_nonce"}
                folded_names = [key.casefold() for key in environment]
                if (len(environment) > 128
                        or len(set(folded_names)) != len(folded_names)
                        or set(folded_names) & reserved_environment
                        or any(not key or "=" in key or "\0" in key
                            or len(key) > 256 or "\0" in value
                            or len(value) > 24_000
                            for key, value in environment.items())):
                    raise ValueError(
                        "durable_learning_worker_recovery_worker_environment_invalid")
                for key, raw in environment.items():
                    if (isinstance(key, str)
                            and key.casefold() in {"pythonpath", "pythonhome"}):
                        if not isinstance(raw, str) or not raw:
                            raise ValueError(
                                "durable_learning_worker_recovery_python_path_invalid")
                        for part in raw.split(os.pathsep):
                            if not part:
                                raise ValueError(
                                    "durable_learning_worker_recovery_python_path_invalid")
                            candidate = Path(part)
                            if not candidate.is_absolute():
                                candidate = cwd / candidate
                            candidate = candidate.resolve(strict=True)
                            if not runtime_covers(candidate):
                                raise ValueError(
                                    "durable_learning_worker_recovery_python_path_ungranted")
            if self._store.load_condition_worker_recovery_intent(
                    protocol=protocol) is not None:
                raise ValueError(
                    "durable_learning_worker_recovery_retry_blocked_by_intent")
            normalized_worker_specs = {}
            executable_digests: dict[str, str] = {}
            for condition in sorted(_CONDITIONS):
                spec = worker_specs[condition]
                executable_path = Path(spec["argv"][0]).resolve(strict=True)
                executable_hash = hashlib.sha256()
                with executable_path.open("rb") as executable_stream:
                    for chunk in iter(lambda: executable_stream.read(1024 * 1024),
                            b""):
                        executable_hash.update(chunk)
                executable_digests[condition] = executable_hash.hexdigest()
                normalized_worker_specs[condition] = {
                    "argv": list(spec["argv"]),
                    "cwd": str(Path(spec["cwd"]).resolve(strict=True)),
                    "environment": dict(spec["environment"])}
            worker_specs_digest = digest_payload({"worker_specs":
                normalized_worker_specs})
            profile_pair = profile_artifact["profile_pair"]
            sids = {condition: profile_pair["condition_profiles"][condition][
                "appcontainer_sid"] for condition in _CONDITIONS}
            manifests = {condition: inputs["staged_by_condition"][condition][
                "runtime_manifest"] for condition in _CONDITIONS}
            bundle_details: dict[str, Mapping[str, Any]] = {}
            for condition in _CONDITIONS:
                row = inputs["staged_by_condition"][condition]
                bundle_artifact = row["acquisition_receipt_bundle_artifact"]
                identity = (bundle_artifact["root_identity"]["volume_serial"],
                    bytes.fromhex(bundle_artifact["root_identity"]["file_id_hex"]))
                bundle_details[condition] = (
                    load_staged_condition_scoped_acquisition_receipt_bundle(
                        root=Path(row["acquisition_receipt_bundle_root"]),
                        expected_root_identity=identity,
                        appcontainer_sid=sids[condition],
                        artifact=bundle_artifact, protocol=protocol,
                        condition=condition))
            intent = self._store.persist_condition_worker_recovery_intent(
                protocol=protocol, worker_specs_digest=worker_specs_digest,
                worker_executable_digest_by_condition=executable_digests)

            processes: dict[str, Any] = {}
            endpoints: dict[str, Any] = {}
            connections: dict[str, Any] = {}
            exchanges: dict[str, list[dict[str, Any]]] = {
                condition: [] for condition in _CONDITIONS}
            launch_evidence: Mapping[str, Any] | None = None
            failure_phase = "worker_pair_launch"
            failure: BaseException | None = None
            try:
                processes, launch_evidence, endpoints = (
                    launch_condition_appcontainer_worker_pair_with_pipes(
                        protocol_id=protocol_id,
                        protocol_digest=protocol["protocol_digest"],
                        profile_pair=profile_pair, worker_specs=worker_specs,
                        receipt_bundle_roots={condition: Path(
                            inputs["staged_by_condition"][condition][
                                "acquisition_receipt_bundle_root"])
                            for condition in _CONDITIONS},
                        receipt_bundle_store_artifacts={condition:
                            inputs["staged_by_condition"][condition][
                                "acquisition_receipt_bundle_artifact"]
                            for condition in _CONDITIONS},
                        invocation_receipt_roots={condition: Path(
                            inputs["staged_by_condition"][condition][
                                "invocation_receipt_root"])
                            for condition in _CONDITIONS},
                        invocation_receipt_store_artifacts={condition:
                            inputs["staged_by_condition"][condition][
                                "invocation_receipt_artifact"]
                            for condition in _CONDITIONS},
                        baseline_protocol=protocol,
                        baseline_runtime_manifests=manifests))
                launch_observations = (launch_evidence.get("worker_observations")
                    if isinstance(launch_evidence, Mapping) else None)
                if (not isinstance(launch_observations, Mapping)
                        or set(launch_observations) != set(_CONDITIONS)
                        or any(not isinstance(launch_observations[condition], Mapping)
                            or launch_observations[condition].get(
                                "requested_executable_sha256") !=
                                    executable_digests[condition]
                            for condition in _CONDITIONS)):
                    raise ValueError(
                        "durable_learning_worker_recovery_executable_changed")
                failure_phase = "pipe_acceptance"
                for condition in _CONDITIONS:
                    connections[condition] = endpoints[condition].accept(
                        expected_worker_observation=
                            processes[condition].observation,
                        timeout_ms=timeout_ms)

                def exchange(condition: str, operation: str,
                        payload: Mapping[str, Any]) -> dict[str, Any]:
                    process = processes[condition]
                    identity = process.observe_identity()
                    worker_observation = {**identity,
                        "process_start_nonce": process.process_start_nonce,
                        "appcontainer_sid": sids[condition]}
                    request = {"schema_version":
                            "sentientos.durable_learning_condition_worker_rpc:v1",
                        "message_type": "request",
                        "protocol_id": protocol_id,
                        "protocol_digest": protocol["protocol_digest"],
                        "condition": condition,
                        "request_id": secrets.token_hex(16),
                        "operation": operation, "payload": dict(payload),
                        "authority": False}
                    attempt = {"request": request, "exchange": None}
                    exchanges[condition].append(attempt)
                    result = exchange_condition_worker_rpc(
                        connections[condition], request,
                        worker_observation=worker_observation,
                        timeout_ms=timeout_ms)
                    attempt["exchange"] = result
                    return result

                failure_phase = "recovery_rpc"
                for condition in _CONDITIONS:
                    baseline = exchange(condition, "inspect_baseline", {})
                    baseline_result = baseline.get("response_result")
                    if (baseline.get("response_status") != "completed"
                            or not isinstance(baseline_result, Mapping)
                            or baseline_result.get(
                                "branch_root_access_matrix_verified") is not True):
                        raise ValueError(
                            "durable_learning_worker_recovery_baseline_rejected")
                    recovered = exchange(condition,
                        "recover_acquisition_receipts", {
                            "task_digests": list(
                                protocol["acquisition_task_digests"])})
                    if recovered.get("response_status") != "completed":
                        raise ValueError(
                            "durable_learning_worker_recovery_receipts_rejected")
                    bundle = bundle_details[condition]["bundle"]
                    task_receipts = bundle.get("task_receipts")
                    task_digests = protocol.get("acquisition_task_digests")
                    if (not isinstance(task_receipts, list)
                            or not isinstance(task_digests, list)
                            or [row.get("task_digest") for row in task_receipts
                                if isinstance(row, Mapping)] != task_digests):
                        raise ValueError(
                            "durable_learning_worker_recovery_bundle_order_invalid")
                    receipt_digests = [row["invocation_receipt_digest"]
                        for row in task_receipts]
                    prepared = exchange(condition,
                        "prepare_consolidation_snapshot", {
                            "acquisition_receipt_digests": receipt_digests})
                    snapshot_evidence = prepared.get("response_result")
                    if (prepared.get("response_status") != "completed"
                            or not isinstance(snapshot_evidence, Mapping)
                            or snapshot_evidence.get("branch_id") !=
                                protocol["condition_branch_ids"][condition]
                            or snapshot_evidence.get(
                                "baseline_state_matches_protocol") is not True
                            or snapshot_evidence.get(
                                "developmental_writeback_performed") is not False):
                        raise ValueError(
                            "durable_learning_worker_recovery_snapshot_rejected")
                    contract = protocol.get("condition_contract")
                    policy_digest = (contract.get(
                        "consolidation_policy_digest")
                        if isinstance(contract, Mapping) else None)
                    consolidated = exchange(condition, "consolidate_branch", {
                        "acquisition_receipt_digests": receipt_digests,
                        "consolidation_policy_digest": policy_digest,
                        "snapshot_digest": snapshot_evidence["snapshot_digest"],
                        "baseline_history_state_digest": protocol[
                            "baseline_history_state_digest"],
                        "baseline_record_refs": snapshot_evidence[
                            "baseline_record_refs"],
                        "source_fact_ids": snapshot_evidence["source_fact_ids"],
                        "allowed_history_record_refs": snapshot_evidence[
                            "allowed_history_record_refs"],
                        "withhold_developmental_history": snapshot_evidence[
                            "withhold_developmental_history"]})
                    if consolidated.get("response_status") not in {
                            "completed", "rejected"}:
                        raise ValueError(
                            "durable_learning_worker_recovery_consolidation_invalid")
                failure_phase = "worker_exit"
                for condition, process in processes.items():
                    exit_code = process.wait(timeout_ms)
                    if exit_code != 0:
                        raise ValueError(
                            "durable_learning_worker_recovery_worker_exit_invalid")
                failure_phase = "cleanup"
            except BaseException as exc:
                failure = exc

            cleanup_errors: list[str] = []
            for connection in reversed(tuple(connections.values())):
                try:
                    connection.close()
                except BaseException:
                    cleanup_errors.append("pipe_connection_close_failed")
            for endpoint in reversed(tuple(endpoints.values())):
                try:
                    endpoint.close()
                except BaseException:
                    cleanup_errors.append("pipe_endpoint_close_failed")
            observations: dict[str, dict[str, Any]] = {}
            for condition, process in processes.items():
                observation = getattr(process, "observation", None)
                if isinstance(observation, Mapping):
                    identity = {key: observation.get(key) for key in (
                        "process_id", "process_creation_time_100ns")}
                    if (type(identity["process_id"]) is int
                            and type(identity[
                                "process_creation_time_100ns"]) is int):
                        observations[condition] = {**identity,
                            "observation_digest": digest_payload(
                                dict(observation))}
                try:
                    if process.wait(0) is None:
                        process.terminate()
                    process.close()
                except BaseException:
                    cleanup_errors.append("worker_process_cleanup_failed")
            if failure is not None:
                partial = getattr(failure,
                    "partial_worker_process_observations", {})
                if isinstance(partial, Mapping):
                    for condition, observation in partial.items():
                        if (condition in _CONDITIONS
                                and condition not in observations
                                and isinstance(observation, Mapping)
                                and type(observation.get("process_id")) is int
                                and type(observation.get(
                                    "process_creation_time_100ns")) is int):
                            observations[condition] = {
                                "process_id": observation["process_id"],
                                "process_creation_time_100ns": observation[
                                    "process_creation_time_100ns"],
                                "observation_digest": digest_payload(
                                    dict(observation))}
                cleanup_errors.extend(getattr(failure,
                    "partial_worker_cleanup_errors", []))
                cleanup_errors.extend(getattr(failure,
                    "partial_pipe_cleanup_errors", []))
            if failure is None and cleanup_errors:
                failure = RuntimeError("worker_cleanup_failed")
                failure_phase = "cleanup"
            status = ("interrupted" if failure is not None else
                "completed" if all(exchange_rows[-1]["exchange"][
                    "response_status"] == "completed"
                    for exchange_rows in exchanges.values()) else
                "reconciliation_not_available")
            failure_code = None
            if failure is not None:
                candidate = getattr(failure, "failure_code", None)
                if (not isinstance(candidate, str)
                        or re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,127}",
                            candidate) is None):
                    candidate = (failure.args[0] if failure.args
                        and isinstance(failure.args[0], str)
                        and re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,127}",
                            failure.args[0]) is not None
                        else type(failure).__name__)
                failure_code = candidate
            try:
                artifact = self._store.persist_condition_worker_recovery_run(
                    protocol=protocol, intent=intent, status=status,
                    failure_phase=(failure_phase if status == "interrupted"
                        else None),
                    failure_code=(failure_code if status == "interrupted"
                        else None), worker_pair_launch=launch_evidence,
                    condition_exchanges=exchanges,
                    worker_process_observations=observations,
                    cleanup_errors=cleanup_errors)
            except BaseException:
                from .windows_appcontainer_access import (
                    quarantine_active_condition_worker_access_probe)
                quarantine_active_condition_worker_access_probe(protocol_id)
                raise
            return artifact

    def _verify_condition_branch_bindings(self,
            protocol: Mapping[str, Any], *, baseline: bool
            ) -> dict[str, Any]:
        if (not isinstance(protocol, Mapping)
                or protocol.get("schema_version") not in _BRANCH_PROTOCOL_SCHEMAS):
            return {}
        if self._condition_branches is None:
            raise ValueError("durable_learning_condition_branches_required")
        verification = verify_durable_learning_protocol(protocol)
        expected_ids = verification.get("condition_branch_ids")
        if (not isinstance(expected_ids, Mapping)
                or any(self._condition_branches[condition].branch_id !=
                    expected_ids.get(condition) for condition in _CONDITIONS)):
            raise ValueError("durable_learning_condition_branch_binding_invalid")
        self._verify_protocol_is_persisted(protocol)
        branch_verification = verify_durable_learning_condition_branches(
            protocol=protocol, branches=self._condition_branches,
            require_baseline=baseline)
        if protocol.get("schema_version") in _V10_PROTOCOL_SCHEMAS:
            if baseline:
                self._store.bind_condition_branch_preflight(protocol=protocol,
                    verification=branch_verification)
            else:
                self._store.verify_condition_branch_preflight(
                    protocol=protocol, verification=branch_verification)
        return branch_verification

    def prepare_condition_branch_preflight(self,
            protocol: Mapping[str, Any], *,
            appcontainer_profile_pair: Mapping[str, Any] | None = None
            ) -> dict[str, Any]:
        """Validate and seal the baseline branch setup without inference.

        For V10, this creates or reloads the immutable preflight artifact that
        every delayed-probe gate will require. No model call, scoring, or state
        writeback occurs here.
        """
        if (not isinstance(protocol, Mapping)
                or protocol.get("schema_version") not in _BRANCH_PROTOCOL_SCHEMAS):
            raise ValueError("durable_learning_condition_preflight_protocol_invalid")
        branch_verification = self._verify_condition_branch_bindings(
            protocol, baseline=True)
        if appcontainer_profile_pair is not None:
            profile_pair_artifact = self._store.bind_condition_appcontainer_profile_pair(
                protocol=protocol, profile_pair=appcontainer_profile_pair)
        else:
            profile_pair_artifact = self._store.load_condition_appcontainer_profile_pair(
                protocol)
        artifact = (self._store.load_condition_branch_preflight(protocol)
            if protocol.get("schema_version") in _V10_PROTOCOL_SCHEMAS else None)
        profile_data_inventory_artifacts: dict[str, dict[str, str]] = {}
        profile_data_inventory_baseline = None
        if profile_pair_artifact is not None:
            for condition in _CONDITIONS:
                observed = self._store.capture_condition_appcontainer_profile_data_inventory(
                    protocol=protocol, condition=condition)
                profile_data_inventory_artifacts[condition] = {
                    "artifact_id": observed["artifact_id"],
                    "artifact_digest": observed["artifact_digest"]}
            profile_data_inventory_baseline = (
                self._store.persist_condition_profile_data_inventory_baseline(
                    protocol=protocol,
                    inventories=profile_data_inventory_artifacts))
        return {"schema_version":
                "sentientos.durable_learning_condition_branch_preparation:v1",
            "protocol_id": protocol.get("protocol_id"),
            "branch_verification": branch_verification,
            "branch_preflight_artifact": artifact,
            "appcontainer_profile_pair_artifact": profile_pair_artifact,
            "profile_data_inventory_artifacts": profile_data_inventory_artifacts,
            "profile_data_inventory_baseline":
                profile_data_inventory_baseline,
            "inference_started": False,
            "scoring_started": False,
            "developmental_writeback_started": False,
            "authority": False}

    def run_condition_worker_access_probe(self, *,
            protocol: Mapping[str, Any],
            runtime_access_setup: Mapping[str, Any],
            access_probe_manifests: Mapping[str, Mapping[str, Any]],
            pipe_connections: Mapping[str, Any],
            worker_processes: Mapping[str, Any],
            timeout_ms: int = 30_000) -> dict[str, Any]:
        """Run the ordered file/registry preflight and persist paired evidence."""
        from .windows_appcontainer_pipe import (
            WindowsAppContainerPipeConnection,
            exchange_condition_worker_rpc)
        from .windows_appcontainer_process import WindowsAppContainerProcess
        if (not isinstance(protocol, Mapping)
                or not isinstance(access_probe_manifests, Mapping)
                or set(access_probe_manifests) != set(_CONDITIONS)
                or not isinstance(pipe_connections, Mapping)
                or set(pipe_connections) != set(_CONDITIONS)
                or not isinstance(worker_processes, Mapping)
                or set(worker_processes) != set(_CONDITIONS)
                or type(timeout_ms) is not int
                or not 1 <= timeout_ms <= 30_000):
            raise ValueError(
                "durable_learning_access_probe_run_arguments_invalid")
        self._verify_protocol_is_persisted(protocol)
        if self._condition_branches is not None:
            self._verify_condition_branch_bindings(protocol, baseline=False)
        self._store.load_condition_branch_preflight(protocol)
        profile_pair_artifact = self._store.load_condition_appcontainer_profile_pair(
            protocol)
        if profile_pair_artifact is None:
            raise ValueError(
                "durable_learning_access_probe_profile_pair_required")
        profiles = profile_pair_artifact["profile_pair"]["condition_profiles"]
        checked_manifests = _verify_condition_worker_access_probe_manifest_pair(
            protocol_id=protocol["protocol_id"], profiles=profiles,
            manifests=access_probe_manifests)
        exchanges: dict[str, Mapping[str, Any]] = {}
        for condition in _CONDITIONS:
            connection = pipe_connections[condition]
            process = worker_processes[condition]
            profile = profiles[condition]
            manifest = checked_manifests[condition]
            if (not isinstance(connection, WindowsAppContainerPipeConnection)
                    or connection.role != "supervisor"
                    or not isinstance(process, WindowsAppContainerProcess)):
                raise ValueError(
                    "durable_learning_access_probe_pipe_connection_invalid")
            try:
                identity = process.observe_identity()
                process_nonce = process.process_start_nonce
            except (AttributeError, OSError, TypeError, ValueError) as exc:
                raise ValueError(
                    "durable_learning_access_probe_process_identity_invalid") from exc
            worker_observation = {**identity,
                "process_start_nonce": process_nonce,
                "appcontainer_sid": profile["appcontainer_sid"]}
            request = {"schema_version":
                    "sentientos.durable_learning_condition_worker_rpc:v1",
                "message_type": "request",
                "protocol_id": protocol.get("protocol_id"),
                "protocol_digest": protocol.get("protocol_digest"),
                "condition": condition,
                "request_id": secrets.token_hex(16),
                "operation": "probe_access_matrix",
                "payload": {"probe_manifest_digest": (
                    manifest.get("manifest_digest")
                    if isinstance(manifest, Mapping) else None)},
                "authority": False}
            exchanges[condition] = exchange_condition_worker_rpc(
                connection, request, worker_observation=worker_observation,
                timeout_ms=timeout_ms)
            registry_request = {"schema_version":
                    "sentientos.durable_learning_condition_worker_rpc:v1",
                "message_type": "request",
                "protocol_id": protocol.get("protocol_id"),
                "protocol_digest": protocol.get("protocol_digest"),
                "condition": condition,
                "request_id": secrets.token_hex(16),
                "operation": "inventory_profile_registry",
                "payload": {"probe_manifest_digest":
                    manifest["manifest_digest"],
                    "expected_appcontainer_sid": profile["appcontainer_sid"]},
                "authority": False}
            registry_exchange = exchange_condition_worker_rpc(
                connection, registry_request,
                worker_observation=worker_observation,
                timeout_ms=timeout_ms)
            if (registry_exchange.get("response_status") != "completed"
                    or not isinstance(registry_exchange.get("response_result"), Mapping)):
                raise ValueError(
                    "durable_learning_registry_inventory_worker_rejected")
            exchanges[condition] = {
                "probe_access_matrix": exchanges[condition],
                "inventory_profile_registry": registry_exchange,
                "worker_observation": worker_observation}
            # Observe the bounded-session worker exit. A live worker remains
            # incomplete in the record; the code does not attribute its cause.
            exit_code = process.wait(timeout_ms)
            if exit_code is None or exit_code != 0:
                raise ValueError(
                    "durable_learning_worker_baseline_worker_exit_unverified")
        return self._record_condition_worker_access_probe_run(
            protocol=protocol,
            runtime_access_setup=runtime_access_setup,
            access_probe_manifests=access_probe_manifests,
            exchanges=exchanges, worker_processes=worker_processes)

    def run_condition_worker_baseline_preflight(self, *,
            protocol: Mapping[str, Any],
            expected_baseline_inventory_digests: Mapping[str, str] | None = None,
            baseline_runtime_setup_ref: Mapping[str, str] | None = None,
            pipe_connections: Mapping[str, Any],
            worker_processes: Mapping[str, Any],
            timeout_ms: int = 30_000) -> dict[str, Any]:
        """Query and persist no-inference baselines from launched condition workers."""
        from .windows_appcontainer_pipe import (
            WindowsAppContainerPipeConnection,
            exchange_condition_worker_rpc)
        from .windows_appcontainer_process import WindowsAppContainerProcess
        if (not isinstance(protocol, Mapping)
                or protocol.get("schema_version") not in _BRANCH_PROTOCOL_SCHEMAS
                or (expected_baseline_inventory_digests is not None
                    and (not isinstance(expected_baseline_inventory_digests, Mapping)
                        or set(expected_baseline_inventory_digests) !=
                            set(_CONDITIONS)
                        or any(not isinstance(value, str)
                            or _HEX_DIGEST.fullmatch(value) is None
                            for value in
                                expected_baseline_inventory_digests.values())))
                or (baseline_runtime_setup_ref is not None
                    and (not isinstance(baseline_runtime_setup_ref, Mapping)
                        or set(baseline_runtime_setup_ref) !=
                            {"artifact_id", "artifact_digest"}))
                or not isinstance(pipe_connections, Mapping)
                or set(pipe_connections) != set(_CONDITIONS)
                or not isinstance(worker_processes, Mapping)
                or set(worker_processes) != set(_CONDITIONS)
                or type(timeout_ms) is not int
                or not 1 <= timeout_ms <= 30_000):
            raise ValueError(
                "durable_learning_worker_baseline_run_arguments_invalid")
        self._verify_protocol_is_persisted(protocol)
        self._store.load_condition_branch_preflight(protocol)
        profile_pair = self._store.load_condition_appcontainer_profile_pair(
            protocol)
        if profile_pair is None:
            raise ValueError(
                "durable_learning_worker_baseline_profile_pair_required")
        profiles = profile_pair["profile_pair"]["condition_profiles"]
        prior_pair = self._store.load_condition_worker_baseline_inventory_pair(
            protocol=protocol)
        if prior_pair is not None:
            raise ValueError(
                "durable_learning_worker_baseline_pair_already_pinned")
        if self._store.load_condition_worker_baseline_interruption(
                protocol=protocol) is not None:
            raise ValueError(
                "durable_learning_worker_baseline_interruption_blocks_retry")
        if baseline_runtime_setup_ref is not None:
            runtime_setup = self._store.load_condition_worker_baseline_runtime_setup(
                protocol=protocol)
            if (runtime_setup is None
                    or runtime_setup.get("artifact_id") !=
                        baseline_runtime_setup_ref.get("artifact_id")
                    or runtime_setup.get("artifact_digest") !=
                        baseline_runtime_setup_ref.get("artifact_digest")
                    or runtime_setup.get("all_requested_grants_applied") is not True):
                raise ValueError(
                    "durable_learning_worker_baseline_runtime_setup_unverified")
        elif self._store.load_condition_worker_baseline_runtime_setup(
                protocol=protocol) is not None:
            raise ValueError(
                "durable_learning_worker_baseline_runtime_setup_reference_required")
        if self._store.find_condition_worker_baseline_inventories(
                protocol=protocol):
            raise ValueError(
                "durable_learning_worker_baseline_member_already_persisted")
        expected_digests = (dict(expected_baseline_inventory_digests)
            if expected_baseline_inventory_digests is not None else {})
        artifacts: dict[str, dict[str, Any]] = {}
        artifact_refs: dict[str, dict[str, str]] = {}
        exchanges: dict[str, dict[str, Any]] = {}
        readiness: dict[str, bool] = {}
        for condition in _CONDITIONS:
            connection = pipe_connections[condition]
            process = worker_processes[condition]
            if (not isinstance(connection, WindowsAppContainerPipeConnection)
                    or connection.role != "supervisor"
                    or not isinstance(process, WindowsAppContainerProcess)):
                raise ValueError(
                    "durable_learning_worker_baseline_pipe_binding_invalid")
            try:
                identity = process.observe_identity()
                process_nonce = process.process_start_nonce
            except (AttributeError, OSError, TypeError, ValueError) as exc:
                raise ValueError(
                    "durable_learning_worker_baseline_process_identity_invalid") from exc
            worker_observation = {**identity,
                "process_start_nonce": process_nonce,
                "appcontainer_sid": profiles[condition]["appcontainer_sid"]}
            request = {"schema_version":
                    "sentientos.durable_learning_condition_worker_rpc:v1",
                "message_type": "request",
                "protocol_id": protocol["protocol_id"],
                "protocol_digest": protocol["protocol_digest"],
                "condition": condition,
                "request_id": secrets.token_hex(16),
                "operation": "inspect_baseline",
                "payload": ({"expected_baseline_inventory_digest":
                    expected_digests[condition]}
                    if condition in expected_digests else {}),
                "authority": False}
            exchange = exchange_condition_worker_rpc(connection, request,
                worker_observation=worker_observation,
                timeout_ms=timeout_ms)
            report = exchange.get("response_result")
            if (exchange.get("response_status") not in {"completed", "rejected"}
                    or not isinstance(report, Mapping)):
                raise ValueError(
                    "durable_learning_worker_baseline_report_unavailable")
            exit_code = process.wait(timeout_ms)
            if exit_code is None:
                raise DurableLearningWorkerBaselineExitError(
                    "baseline_worker_exit_timeout")
            if exit_code != 0:
                raise DurableLearningWorkerBaselineExitError(
                    "baseline_worker_exit_nonzero")
            artifact = self._store.persist_condition_worker_baseline_inventory(
                protocol=protocol, condition=condition,
                worker_observation=worker_observation,
                worker_rpc_exchange=exchange,
                worker_exit_code=exit_code,
                expected_baseline_inventory_digest=expected_digests.get(
                    condition),
                inventory=report)
            artifacts[condition] = artifact
            artifact_refs[condition] = {
                "artifact_id": artifact["artifact_id"],
                "artifact_digest": artifact["artifact_digest"]}
            exchanges[condition] = exchange
            readiness[condition] = artifact["baseline_ready"]
        paired_artifact = (
            self._store.persist_condition_worker_baseline_inventory_pair(
                protocol=protocol, condition_inventories=artifact_refs,
                baseline_runtime_setup_ref=baseline_runtime_setup_ref))
        result = {"schema_version":
                ("sentientos.durable_learning_worker_baseline_preflight:v2"
                    if baseline_runtime_setup_ref is not None else
                    "sentientos.durable_learning_worker_baseline_preflight:v1"),
            "protocol_id": protocol["protocol_id"],
            "protocol_digest": protocol["protocol_digest"],
            "condition_artifacts": artifacts,
            "paired_artifact": paired_artifact,
            "worker_exchanges": exchanges,
            "baseline_ready_by_condition": readiness,
            "paired_baseline_ready": all(readiness.values()),
            "inference_started": False,
            "scoring_started": False,
            "developmental_writeback_started": False,
            "retention_contrast_eligible": False,
            "authority": False}
        if baseline_runtime_setup_ref is not None:
            result["baseline_runtime_setup"] = dict(
                baseline_runtime_setup_ref)
        return result

    def launch_condition_worker_baseline_preflight(self, *,
            protocol: Mapping[str, Any],
            baseline_runtime_manifests: Mapping[str, Mapping[str, Any]] | None = None,
            baseline_roots_by_condition: Mapping[str, Mapping[str, Any]] | None = None,
            session_ids_by_condition: Mapping[str, str] | None = None,
            runtime_roots: Mapping[str, Any],
            worker_specs: Mapping[str, Mapping[str, Any]],
            expected_baseline_inventory_digests: Mapping[str, str] | None = None,
            timeout_ms: int = 30_000) -> dict[str, Any]:
        """Grant per-branch read access, launch, capture, and clean up baseline workers."""
        from .windows_appcontainer_access import (
            condition_worker_access_probe_mutex,
            grant_condition_worker_baseline_read_access,
            grant_condition_worker_runtime_read_execute)
        from pathlib import Path

        manifests_supplied = baseline_runtime_manifests is not None
        roots_supplied = baseline_roots_by_condition is not None
        sessions_supplied = session_ids_by_condition is not None
        generated_inputs_valid = (
            isinstance(baseline_roots_by_condition, Mapping)
            and set(baseline_roots_by_condition) == set(_CONDITIONS)
            and isinstance(session_ids_by_condition, Mapping)
            and set(session_ids_by_condition) == set(_CONDITIONS)
            and all(isinstance(baseline_roots_by_condition[condition], Mapping)
                and isinstance(session_ids_by_condition[condition], str)
                and bool(session_ids_by_condition[condition])
                for condition in _CONDITIONS))
        manifest_inputs_valid = (isinstance(baseline_runtime_manifests, Mapping)
            and set(baseline_runtime_manifests) == set(_CONDITIONS))
        if (not isinstance(protocol, Mapping)
                or protocol.get("schema_version") not in _BRANCH_PROTOCOL_SCHEMAS
                or (manifests_supplied and (not manifest_inputs_valid
                    or roots_supplied or sessions_supplied))
                or (not manifests_supplied and not generated_inputs_valid)
                or not isinstance(runtime_roots, Mapping)
                or not runtime_roots
                or not isinstance(worker_specs, Mapping)
                or set(worker_specs) != set(_CONDITIONS)
                or (expected_baseline_inventory_digests is not None
                    and (not isinstance(expected_baseline_inventory_digests, Mapping)
                        or set(expected_baseline_inventory_digests) !=
                            set(_CONDITIONS)
                        or any(not isinstance(value, str)
                            or _HEX_DIGEST.fullmatch(value) is None
                            for value in
                                expected_baseline_inventory_digests.values())))
                or type(timeout_ms) is not int
                or not 1 <= timeout_ms <= 30_000):
            raise ValueError(
                "durable_learning_worker_baseline_launch_arguments_invalid")
        protocol_id = protocol["protocol_id"]
        with condition_worker_access_probe_mutex(protocol_id):
            self._verify_protocol_is_persisted(protocol)
            branch_verification = self._verify_condition_branch_bindings(
                protocol, baseline=True)
            if self._store.load_condition_worker_baseline_inventory_pair(
                    protocol=protocol) is not None:
                raise ValueError(
                    "durable_learning_worker_baseline_pair_already_pinned")
            prior_interruption = (
                self._store.load_condition_worker_baseline_interruption(
                    protocol=protocol))
            if prior_interruption is not None:
                return {"schema_version":
                        "sentientos.durable_learning_worker_baseline_supervised_run:v1",
                    "protocol_id": protocol_id,
                    "status": "prior_worker_baseline_interrupted",
                    "baseline_interruption": {
                        "artifact_id": prior_interruption["artifact_id"],
                        "artifact_digest": prior_interruption["artifact_digest"]},
                    "worker_pair_launch": None,
                    "baseline_preflight": None,
                    "authority": False}
            prior_setup = self._store.load_condition_worker_baseline_runtime_setup(
                protocol=protocol)
            if prior_setup is not None:
                return {"schema_version":
                        "sentientos.durable_learning_worker_baseline_supervised_run:v1",
                    "protocol_id": protocol_id,
                    "status": "prior_baseline_runtime_setup_unresolved",
                    "baseline_runtime_setup_artifact": {
                        "artifact_id": prior_setup["artifact_id"],
                        "artifact_digest": prior_setup["artifact_digest"]},
                    "worker_pair_launch": None,
                    "baseline_preflight": None,
                    "authority": False}
            if self._store.find_condition_worker_baseline_inventories(
                    protocol=protocol):
                raise ValueError(
                    "durable_learning_worker_baseline_member_already_persisted")
            profile_artifact = self._store.load_condition_appcontainer_profile_pair(
                protocol)
            if profile_artifact is None:
                raise ValueError(
                    "durable_learning_worker_baseline_profile_pair_required")
            profile_pair = profile_artifact["profile_pair"]
            profiles = profile_pair["condition_profiles"]
            if not manifests_supplied:
                from .durable_learning_condition_worker_backend import (
                    build_condition_worker_baseline_runtime_manifest_pair)
                baseline_runtime_manifests = (
                    build_condition_worker_baseline_runtime_manifest_pair(
                        protocol=protocol,
                        appcontainer_sids={condition:
                            profiles[condition]["appcontainer_sid"]
                            for condition in _CONDITIONS},
                        session_ids=session_ids_by_condition,
                        roots_by_condition=baseline_roots_by_condition))
            from .durable_learning_condition_worker_backend import (
                verify_condition_worker_baseline_runtime_manifest)
            checked_manifests = {condition:
                verify_condition_worker_baseline_runtime_manifest(
                    baseline_runtime_manifests[condition], protocol=protocol,
                    protocol_id=protocol_id,
                    protocol_digest=protocol["protocol_digest"],
                    condition=condition,
                    appcontainer_sid=profiles[condition]["appcontainer_sid"])
                for condition in _CONDITIONS}
            # Verify the reciprocal branch description before applying ACLs.
            _verify_condition_worker_baseline_runtime_manifest_pair(
                checked_manifests)
            _verify_condition_worker_baseline_manifest_sessions(
                checked_manifests, branch_verification)
            for condition in _CONDITIONS:
                branch = self._condition_branches[condition]
                owner = branch.experience_source._owner
                expected_roots = {
                    "state": owner.config.state_root,
                    "history": owner.writeback.store.root,
                    "session": branch.conversation_session_store.root}
                if checked_manifests[condition]["session_id"] != branch.session_id:
                    raise ValueError(
                        "durable_learning_worker_baseline_manifest_session_mismatch")
                resolved_expected: dict[str, Path] = {}
                resolved_supplied: dict[str, Path] = {}
                try:
                    for root_name, expected_root in expected_roots.items():
                        resolved_expected[root_name] = Path(
                            expected_root).resolve(strict=True)
                        resolved_supplied[root_name] = Path(
                            checked_manifests[condition]["roots"][
                                root_name]["path"]).resolve(strict=True)
                except (OSError, RuntimeError, TypeError, ValueError) as exc:
                    raise ValueError(
                        "durable_learning_worker_baseline_manifest_branch_root_unavailable") from exc
                for root_name, expected_root in expected_roots.items():
                    if resolved_expected[root_name] != resolved_supplied[root_name]:
                        raise ValueError(
                            "durable_learning_worker_baseline_manifest_branch_root_mismatch")
            branch_paths = [Path(row["path"]).resolve(strict=True)
                for manifest in checked_manifests.values()
                for row in manifest["roots"].values()]
            try:
                runtime_paths = [Path(value).resolve(strict=True)
                    for value in runtime_roots.values()]
                if (any(not path.is_dir() for path in runtime_paths)
                        or any(root == branch or root in branch.parents
                            or branch in root.parents
                            for root in runtime_paths for branch in branch_paths)):
                    raise ValueError("baseline_runtime_root_overlap")
            except (OSError, RuntimeError, TypeError, ValueError) as exc:
                raise ValueError(
                    "durable_learning_worker_baseline_runtime_roots_invalid") from exc
            runtime_access_setup = grant_condition_worker_runtime_read_execute(
                protocol_id=protocol_id, profile_pair=profile_pair,
                runtime_roots=runtime_roots)
            access_setup = grant_condition_worker_baseline_read_access(
                protocol=protocol, profile_pair=profile_pair,
                baseline_manifests=checked_manifests)
            try:
                setup_artifact = (
                    self._store.persist_condition_worker_baseline_runtime_setup(
                        protocol=protocol,
                        runtime_access_setup=runtime_access_setup,
                        baseline_read_access_setup=access_setup,
                        manifest_digest_by_condition={condition:
                            checked_manifests[condition]["manifest_digest"]
                            for condition in _CONDITIONS},
                        baseline_runtime_manifests=checked_manifests))
            except BaseException:
                from .windows_appcontainer_access import (
                    quarantine_active_condition_worker_access_probe)
                quarantine_active_condition_worker_access_probe(protocol_id)
                raise
            setup_ref = {"artifact_id": setup_artifact["artifact_id"],
                "artifact_digest": setup_artifact["artifact_digest"]}
            if (runtime_access_setup.get("all_requested_grants_applied") is not True
                    or access_setup.get("all_requested_grants_applied") is not True):
                phase = ("runtime_access_setup"
                    if runtime_access_setup.get("all_requested_grants_applied")
                        is not True else "baseline_read_access_setup")
                try:
                    interruption = (
                        self._store.persist_condition_worker_baseline_interruption(
                            protocol=protocol,
                            runtime_access_setup=runtime_access_setup,
                            baseline_read_access_setup=access_setup,
                            failure_phase=phase, launch_call_returned=False,
                            worker_process_observations={},
                            created_endpoint_conditions=(),
                            accepted_pipe_conditions=(), cleanup_errors=(),
                            failure_type="AccessSetupIncomplete"))
                except BaseException:
                    from .windows_appcontainer_access import (
                        quarantine_active_condition_worker_access_probe)
                    quarantine_active_condition_worker_access_probe(protocol_id)
                    raise
                return {"schema_version":
                        "sentientos.durable_learning_worker_baseline_supervised_run:v1",
                    "protocol_id": protocol_id,
                    "status": "runtime_access_incomplete",
                    "runtime_access_setup": runtime_access_setup,
                    "baseline_read_access_setup": access_setup,
                    "baseline_runtime_setup_artifact": setup_ref,
                    "baseline_interruption": {
                        "artifact_id": interruption["artifact_id"],
                        "artifact_digest": interruption["artifact_digest"]},
                    "worker_pair_launch": None,
                    "baseline_preflight": None,
                    "authority": False}

            from .windows_appcontainer_process import (
                launch_condition_appcontainer_worker_pair_with_pipes)
            processes: dict[str, Any] = {}
            endpoints: dict[str, Any] = {}
            connections: dict[str, Any] = {}
            launch_evidence: dict[str, Any] | None = None
            failure: BaseException | None = None
            failure_phase = "worker_pair_launch"
            launch_call_returned = False
            accepted_pipe_conditions: list[str] = []
            baseline_result: dict[str, Any] | None = None
            try:
                processes, launch_evidence, endpoints = (
                    launch_condition_appcontainer_worker_pair_with_pipes(
                        protocol_id=protocol_id,
                        protocol_digest=protocol["protocol_digest"],
                        profile_pair=profile_pair,
                        worker_specs=worker_specs,
                        baseline_protocol=protocol,
                        baseline_runtime_manifests=
                            checked_manifests))
                launch_call_returned = True
                failure_phase = "pipe_acceptance"
                for condition in _CONDITIONS:
                    connections[condition] = endpoints[condition].accept(
                        expected_worker_observation=
                            processes[condition].observation,
                        timeout_ms=timeout_ms)
                    accepted_pipe_conditions.append(condition)
                failure_phase = "baseline_rpc"
                baseline_result = self.run_condition_worker_baseline_preflight(
                    protocol=protocol,
                    expected_baseline_inventory_digests=(
                        expected_baseline_inventory_digests),
                    baseline_runtime_setup_ref=setup_ref,
                    pipe_connections=connections,
                    worker_processes=processes, timeout_ms=timeout_ms)
            except BaseException as exc:
                failure = exc

            cleanup_errors: list[str] = []
            for connection in reversed(tuple(connections.values())):
                try:
                    connection.close()
                except BaseException:
                    cleanup_errors.append("pipe_connection_close_failed")
            for endpoint in reversed(tuple(endpoints.values())):
                try:
                    endpoint.close()
                except BaseException:
                    cleanup_errors.append("pipe_endpoint_close_failed")
            for process in reversed(tuple(processes.values())):
                try:
                    if process.wait(0) is None:
                        process.terminate()
                    process.close()
                except BaseException:
                    cleanup_errors.append("worker_process_cleanup_failed")
            if failure is None and cleanup_errors:
                failure_phase = "cleanup"
            if failure is not None or cleanup_errors:
                observations: dict[str, dict[str, Any]] = {}
                for condition, process in processes.items():
                    observation = getattr(process, "observation", None)
                    if (isinstance(observation, Mapping)
                            and type(observation.get("process_id")) is int
                            and type(observation.get(
                                "process_creation_time_100ns")) is int):
                        observations[condition] = {
                            "process_id": observation["process_id"],
                            "process_creation_time_100ns": observation[
                                "process_creation_time_100ns"],
                            "observation_digest": digest_payload(
                                dict(observation))}
                if failure is not None:
                    partial = getattr(failure,
                        "partial_worker_process_observations", {})
                    if isinstance(partial, Mapping):
                        for condition, observation in partial.items():
                            if (condition in _CONDITIONS
                                    and condition not in observations
                                    and isinstance(observation, Mapping)
                                    and type(observation.get("process_id")) is int
                                    and type(observation.get(
                                        "process_creation_time_100ns")) is int):
                                observations[condition] = {
                                    "process_id": observation["process_id"],
                                    "process_creation_time_100ns": observation[
                                        "process_creation_time_100ns"],
                                    "observation_digest": digest_payload(
                                        dict(observation))}
                if failure is not None and getattr(
                        failure, "partial_worker_cleanup_errors", []):
                    cleanup_errors.append("worker_process_cleanup_failed")
                if failure is not None and getattr(
                        failure, "partial_pipe_cleanup_errors", []):
                    cleanup_errors.append("pipe_endpoint_close_failed")
                partial_endpoints = (getattr(failure,
                    "partial_created_endpoint_conditions", ())
                    if failure is not None else ())
                created_conditions = tuple(condition for condition in
                    _CONDITIONS if condition in partial_endpoints) \
                    if isinstance(partial_endpoints, Sequence) and not isinstance(
                        partial_endpoints, (str, bytes)) else tuple(endpoints)
                try:
                    interruption = (
                        self._store.persist_condition_worker_baseline_interruption(
                            protocol=protocol,
                            runtime_access_setup=runtime_access_setup,
                            baseline_read_access_setup=access_setup,
                            failure_phase=failure_phase,
                            launch_call_returned=launch_call_returned,
                            worker_process_observations=observations,
                            created_endpoint_conditions=created_conditions,
                            accepted_pipe_conditions=accepted_pipe_conditions,
                            cleanup_errors=cleanup_errors,
                            failure_type=(getattr(failure, "failure_code",
                                type(failure).__name__)
                                if failure is not None else "CleanupError")))
                except BaseException as persist_error:
                    from .windows_appcontainer_access import (
                        quarantine_active_condition_worker_access_probe)
                    quarantine_active_condition_worker_access_probe(protocol_id)
                    if failure is not None:
                        raise failure from persist_error
                    raise
                error = DurableLearningBaselineInterruptedError(
                    artifact_id=interruption["artifact_id"],
                    artifact_digest=interruption["artifact_digest"],
                    failure_phase=failure_phase)
                if failure is not None:
                    raise error from failure
                raise error
            return {"schema_version":
                    "sentientos.durable_learning_worker_baseline_supervised_run:v1",
                "protocol_id": protocol_id,
                "status": ("completed" if baseline_result and
                    baseline_result.get("paired_baseline_ready") is True
                    else "baseline_report_rejected"),
                "runtime_access_setup": runtime_access_setup,
                "baseline_read_access_setup": access_setup,
                "baseline_runtime_setup_artifact": setup_ref,
                "worker_pair_launch": launch_evidence,
                "baseline_preflight": baseline_result,
                "cleanup_completed": True,
                "filesystem_isolation_verified": False,
                "retention_contrast_eligible": False,
                "authority": False}

    def launch_condition_worker_access_probe(self, *,
            protocol: Mapping[str, Any],
            access_probe_manifests: Mapping[str, Mapping[str, Any]],
            runtime_roots: Mapping[str, Any],
            worker_specs: Mapping[str, Mapping[str, Any]],
            timeout_ms: int = 30_000) -> dict[str, Any]:
        """Run one protocol's supervised probe under a cross-process mutex."""
        if not isinstance(protocol, Mapping):
            raise ValueError(
                "durable_learning_access_probe_launch_arguments_invalid")
        from .windows_appcontainer_access import (
            condition_worker_access_probe_mutex)
        protocol_id = protocol.get("protocol_id")
        with condition_worker_access_probe_mutex(protocol_id):
            return self._launch_condition_worker_access_probe_locked(
                protocol=protocol,
                access_probe_manifests=access_probe_manifests,
                runtime_roots=runtime_roots, worker_specs=worker_specs,
                timeout_ms=timeout_ms)

    def _launch_condition_worker_access_probe_locked(self, *,
            protocol: Mapping[str, Any],
            access_probe_manifests: Mapping[str, Mapping[str, Any]],
            runtime_roots: Mapping[str, Any],
            worker_specs: Mapping[str, Mapping[str, Any]],
            timeout_ms: int) -> dict[str, Any]:
        """Launch both bound workers, run the probe, persist, then clean up."""
        from .windows_appcontainer_process import (
            launch_condition_appcontainer_worker_pair_with_pipes)
        from .windows_appcontainer_profile import (
            verify_condition_appcontainer_profile_pair_result)
        from .windows_appcontainer_access import (
            grant_condition_worker_runtime_read_execute)
        if (not isinstance(protocol, Mapping)
                or protocol.get("schema_version") not in _BRANCH_PROTOCOL_SCHEMAS
                or not isinstance(access_probe_manifests, Mapping)
                or set(access_probe_manifests) != set(_CONDITIONS)
                or not isinstance(runtime_roots, Mapping)
                or not runtime_roots
                or not isinstance(worker_specs, Mapping)
                or set(worker_specs) != set(_CONDITIONS)
                or type(timeout_ms) is not int
                or not 1 <= timeout_ms <= 30_000):
            raise ValueError(
                "durable_learning_access_probe_launch_arguments_invalid")
        self._verify_protocol_is_persisted(protocol)
        if self._condition_branches is not None:
            self._verify_condition_branch_bindings(protocol, baseline=False)
        profile_artifact = self._store.load_condition_appcontainer_profile_pair(
            protocol)
        if profile_artifact is None:
            raise ValueError(
                "durable_learning_access_probe_profile_pair_required")
        profile_pair = verify_condition_appcontainer_profile_pair_result(
            profile_artifact["profile_pair"],
            protocol_id=protocol["protocol_id"])
        # Runtime grants are inheritable and persist after this probe. Validate
        # the frozen sentinel manifests and ensure no granted tree can include
        # or be included by a sentinel custody directory before touching ACLs.
        from pathlib import Path
        profiles = profile_pair["condition_profiles"]
        checked_manifests = _verify_condition_worker_access_probe_manifest_pair(
            protocol_id=protocol["protocol_id"], profiles=profiles,
            manifests=access_probe_manifests)
        try:
            roots = [Path(root).resolve(strict=True)
                for root in runtime_roots.values()]
            sentinel_parents = [
                Path(target["path"]).resolve(strict=True).parent
                for manifest in checked_manifests.values()
                for target in (manifest["own_sentinel"],
                    manifest["peer_sentinel"], manifest["scorer_sentinel"])]
            if any(not root.is_dir() for root in roots):
                raise ValueError("runtime_root_not_directory")
            for root in roots:
                for parent in sentinel_parents:
                    if (root == parent or root in parent.parents
                            or parent in root.parents):
                        raise ValueError("runtime_root_overlaps_sentinel_custody")
        except (OSError, RuntimeError, TypeError, ValueError) as exc:
            raise ValueError(
                "durable_learning_runtime_root_overlaps_access_probe_sentinel") from exc
        prior_interruption = (
            self._store.find_condition_worker_access_probe_interruption(
                protocol=protocol))
        if prior_interruption is not None:
            return {"schema_version":
                    "sentientos.durable_learning_access_probe_supervised_run:v1",
                "protocol_id": protocol["protocol_id"],
                "status": "prior_worker_access_probe_interrupted",
                "runtime_access_setup": prior_interruption[
                    "runtime_access_setup"],
                "worker_access_probe_interruption": {
                    "artifact_id": prior_interruption["artifact_id"],
                    "artifact_digest": prior_interruption["artifact_digest"]},
                "worker_pair_launch": None, "probe_record": None,
                "authority": False}
        prior_attempt = (
            self._store.find_condition_worker_runtime_access_attempt(
                protocol=protocol))
        if prior_attempt is not None:
            return {"schema_version":
                    "sentientos.durable_learning_access_probe_supervised_run:v1",
                "protocol_id": protocol["protocol_id"],
                "status": "prior_runtime_access_attempt_unresolved",
                "runtime_access_setup": prior_attempt["runtime_access_setup"],
                "runtime_access_attempt_artifact": {
                    "artifact_id": prior_attempt["artifact_id"],
                    "artifact_digest": prior_attempt["artifact_digest"]},
                "worker_pair_launch": None, "probe_record": None,
                "authority": False}
        prior_completion = (
            self._store.find_condition_worker_access_probe_completion(
                protocol=protocol))
        if prior_completion is not None:
            return {"schema_version":
                    "sentientos.durable_learning_access_probe_supervised_run:v1",
                "protocol_id": protocol["protocol_id"],
                "status": "prior_access_probe_already_completed",
                "runtime_access_setup": prior_completion[
                    "runtime_access_setup"],
                "prior_access_probe_artifact": {
                    "artifact_id": prior_completion["artifact_id"],
                    "artifact_digest": prior_completion["artifact_digest"]},
                "worker_pair_launch": None, "probe_record": None,
                "authority": False}
        try:
            runtime_access_setup = grant_condition_worker_runtime_read_execute(
                protocol_id=protocol["protocol_id"], profile_pair=profile_pair,
                runtime_roots=runtime_roots)
        except BaseException as exc:
            if not isinstance(exc, Exception):
                from .windows_appcontainer_access import (
                    quarantine_active_condition_worker_access_probe)
                quarantine_active_condition_worker_access_probe(
                    protocol["protocol_id"])
            raise
        if runtime_access_setup.get("all_requested_grants_applied") is not True:
            try:
                attempt_artifact = (
                    self._store.persist_condition_worker_runtime_access_attempt(
                        protocol=protocol,
                        runtime_access_setup=runtime_access_setup))
            except BaseException:
                from .windows_appcontainer_access import (
                    quarantine_active_condition_worker_access_probe)
                quarantine_active_condition_worker_access_probe(
                    protocol["protocol_id"])
                raise
            return {"schema_version":
                    "sentientos.durable_learning_access_probe_supervised_run:v1",
                "protocol_id": protocol["protocol_id"],
                "status": "runtime_access_incomplete",
                "runtime_access_setup": runtime_access_setup,
                "runtime_access_attempt_artifact": {
                    "artifact_id": attempt_artifact["artifact_id"],
                    "artifact_digest": attempt_artifact["artifact_digest"]},
                "worker_pair_launch": None, "probe_record": None,
                "authority": False}
        processes: dict[str, Any] = {}
        endpoints: dict[str, Any] = {}
        connections: dict[str, Any] = {}
        launch_evidence: dict[str, Any] = {}
        launch_call_returned = False
        accepted_pipe_conditions: list[str] = []
        failure_phase = "worker_pair_launch"
        result: dict[str, Any] | None = None
        failure: BaseException | None = None
        try:
            processes, launch_evidence, endpoints = (
                launch_condition_appcontainer_worker_pair_with_pipes(
                    protocol_id=protocol["protocol_id"],
                    protocol_digest=protocol["protocol_digest"],
                    profile_pair=profile_pair,
                    worker_specs=worker_specs,
                    access_probe_manifests=access_probe_manifests))
            launch_call_returned = True
            failure_phase = "pipe_acceptance"
            for condition in _CONDITIONS:
                connections[condition] = endpoints[condition].accept(
                    expected_worker_observation=
                        processes[condition].observation,
                    timeout_ms=timeout_ms)
                accepted_pipe_conditions.append(condition)
            failure_phase = "probe_rpc_and_record"
            probe_record = self.run_condition_worker_access_probe(
                protocol=protocol,
                runtime_access_setup=runtime_access_setup,
                access_probe_manifests=access_probe_manifests,
                pipe_connections=connections,
                worker_processes=processes, timeout_ms=timeout_ms)
            result = {"schema_version":
                    "sentientos.durable_learning_access_probe_supervised_run:v1",
                "protocol_id": protocol["protocol_id"],
                "status": "completed",
                "runtime_access_setup": runtime_access_setup,
                "worker_pair_launch": launch_evidence,
                "probe_record": probe_record,
                "authority": False}
        except BaseException as exc:
            failure = exc

        cleanup_errors: list[str] = []
        for connection in reversed(tuple(connections.values())):
            try:
                connection.close()
            except BaseException:
                cleanup_errors.append("pipe_connection_close_failed")
        for endpoint in reversed(tuple(endpoints.values())):
            try:
                endpoint.close()
            except BaseException:
                cleanup_errors.append("pipe_endpoint_close_failed")
        for process in reversed(tuple(processes.values())):
            try:
                if process.wait(0) is None:
                    process.terminate()
                process.close()
            except BaseException:
                cleanup_errors.append("worker_process_cleanup_failed")
        if cleanup_errors and failure is None:
            failure_phase = "cleanup"
        if failure is not None or cleanup_errors:
            from .windows_appcontainer_access import (
                quarantine_active_condition_worker_access_probe)
            worker_observations: dict[str, dict[str, Any]] = {}
            for condition, process in processes.items():
                observation = getattr(process, "observation", None)
                if (not isinstance(observation, Mapping)
                        or type(observation.get("process_id")) is not int
                        or type(observation.get(
                            "process_creation_time_100ns")) is not int):
                    continue
                worker_observations[condition] = {
                    "process_id": observation["process_id"],
                    "process_creation_time_100ns": observation[
                        "process_creation_time_100ns"],
                    "observation_digest": digest_payload(dict(observation))}
            partial_observations = getattr(failure,
                "partial_worker_process_observations", {})
            if isinstance(partial_observations, Mapping):
                for condition, observation in partial_observations.items():
                    if (condition in _CONDITIONS
                            and condition not in worker_observations
                            and isinstance(observation, Mapping)
                            and type(observation.get("process_id")) is int
                            and observation["process_id"] > 0
                            and type(observation.get(
                                "process_creation_time_100ns")) is int
                            and observation["process_creation_time_100ns"] > 0):
                        worker_observations[condition] = {
                            "process_id": observation["process_id"],
                            "process_creation_time_100ns": observation[
                                "process_creation_time_100ns"],
                            "observation_digest": digest_payload(
                                dict(observation))}
            if getattr(failure, "partial_worker_cleanup_errors", []):
                cleanup_errors.append("worker_process_cleanup_failed")
            if getattr(failure, "partial_pipe_cleanup_errors", []):
                cleanup_errors.append("pipe_endpoint_close_failed")
            partial_endpoints = getattr(failure,
                "partial_created_endpoint_conditions", ())
            if isinstance(partial_endpoints, Sequence) and not isinstance(
                    partial_endpoints, (str, bytes)):
                created_endpoint_conditions = tuple(condition
                    for condition in _CONDITIONS
                    if condition in partial_endpoints)
            else:
                created_endpoint_conditions = tuple(endpoints)
            try:
                interruption = (
                    self._store.persist_condition_worker_access_probe_interruption(
                        protocol=protocol,
                        runtime_access_setup=runtime_access_setup,
                        failure_phase=failure_phase,
                        launch_call_returned=launch_call_returned,
                        worker_process_observations=worker_observations,
                        created_endpoint_conditions=created_endpoint_conditions,
                        accepted_pipe_conditions=accepted_pipe_conditions,
                        cleanup_errors=cleanup_errors,
                        failure_type=(type(failure).__name__ if failure is not None
                            else "CleanupError")))
            except BaseException as persist_error:
                quarantine_active_condition_worker_access_probe(
                    protocol["protocol_id"])
                if (failure is not None
                        and not isinstance(failure, Exception)):
                    failure.interruption_persistence_failed = True
                    raise failure from persist_error
                if failure is not None:
                    raise ValueError(
                        "durable_learning_access_probe_interruption_persistence_failed") from failure
                if not isinstance(persist_error, Exception):
                    raise
                raise ValueError(
                    "durable_learning_access_probe_interruption_persistence_failed") from persist_error
            interrupted = DurableLearningAccessProbeInterruptedError(
                artifact_id=interruption["artifact_id"],
                artifact_digest=interruption["artifact_digest"],
                failure_phase=failure_phase)
            if failure is not None:
                if not isinstance(failure, Exception):
                    failure.interruption_artifact_id = interruption["artifact_id"]
                    failure.interruption_artifact_digest = interruption[
                        "artifact_digest"]
                    raise failure
                raise interrupted from failure
            raise interrupted
        assert result is not None
        return result

    def _record_condition_worker_access_probe_run(self, *,
            protocol: Mapping[str, Any],
            runtime_access_setup: Mapping[str, Any],
            access_probe_manifests: Mapping[str, Mapping[str, Any]],
            exchanges: Mapping[str, Any],
            worker_processes: Mapping[str, Any]) -> dict[str, Any]:
        """Verify both exited workers and persist the paired probe evidence."""
        if (not isinstance(protocol, Mapping)
                or protocol.get("schema_version") not in _BRANCH_PROTOCOL_SCHEMAS
                or not isinstance(access_probe_manifests, Mapping)
                or set(access_probe_manifests) != set(_CONDITIONS)
                or not isinstance(exchanges, Mapping)
                or set(exchanges) != set(_CONDITIONS)
                or not isinstance(worker_processes, Mapping)
                or set(worker_processes) != set(_CONDITIONS)):
            raise ValueError(
                "durable_learning_access_probe_run_arguments_invalid")
        self._verify_protocol_is_persisted(protocol)
        if self._condition_branches is not None:
            self._verify_condition_branch_bindings(protocol, baseline=False)
        branch_preflight = self._store.load_condition_branch_preflight(protocol)
        profile_pair_artifact = self._store.load_condition_appcontainer_profile_pair(
            protocol)
        if profile_pair_artifact is None:
            raise ValueError(
                "durable_learning_access_probe_profile_pair_required")
        checked_manifests = _verify_condition_worker_access_probe_manifest_pair(
            protocol_id=protocol["protocol_id"],
            profiles=profile_pair_artifact["profile_pair"][
                "condition_profiles"], manifests=access_probe_manifests)
        from .windows_appcontainer_pipe import (
            verify_condition_worker_access_probe_after_exit)
        access_exchanges = {condition: exchanges[condition][
            "probe_access_matrix"] for condition in _CONDITIONS}
        completions = {condition:
            verify_condition_worker_access_probe_after_exit(
                exchange=access_exchanges[condition],
                manifest=checked_manifests[condition],
                worker_process=worker_processes[condition])
            for condition in _CONDITIONS}
        registry_inventories: dict[str, dict[str, str]] = {}
        for condition in _CONDITIONS:
            exchange = exchanges[condition]["inventory_profile_registry"]
            observation = exchanges[condition]["worker_observation"]
            artifact = self._store.persist_condition_profile_registry_inventory(
                protocol=protocol, condition=condition,
                probe_manifest_digest=checked_manifests[condition][
                    "manifest_digest"],
                worker_observation=observation,
                worker_rpc_exchange=exchange,
                inventory=exchange["response_result"])
            registry_inventories[condition] = {
                "artifact_id": artifact["artifact_id"],
                "artifact_digest": artifact["artifact_digest"]}
        registry_baseline = (
            self._store.persist_condition_profile_registry_inventory_baseline(
                protocol=protocol, inventories=registry_inventories))
        artifact = self._store.persist_condition_worker_access_probe_completions(
            protocol=protocol,
            runtime_access_setup=runtime_access_setup,
            access_probe_manifests=access_probe_manifests,
            completions=completions)
        return {"schema_version":
                "sentientos.durable_learning_access_probe_run_record:v1",
            "protocol_id": protocol["protocol_id"],
            "branch_preflight_id": branch_preflight["preflight_id"],
            "profile_pair_artifact_id": profile_pair_artifact["artifact_id"],
            "completion_artifact_id": artifact["artifact_id"],
            "completion_artifact_digest": artifact["artifact_digest"],
            "registry_inventory_artifacts": registry_inventories,
            "registry_inventory_baseline_id": registry_baseline["artifact_id"],
            "registry_inventory_baseline_digest":
                registry_baseline["artifact_digest"],
            "all_probe_checks_match": all(completions[condition].get(
                "all_probe_checks_match") is True for condition in _CONDITIONS),
            "process_isolation_verified": False,
            "filesystem_isolation_verified": False,
            "retention_contrast_eligible": False,
            "authority": False}

    def _require_retention_eligible_protocol(
            self, protocol: Mapping[str, Any]) -> None:
        verification = verify_durable_learning_protocol(protocol)
        if (verification.get("retention_contrast_eligible") is not True
                and not self._allow_descriptive_only_execution):
            raise ValueError("durable_learning_retention_contrast_ineligible")

    def _score(self, protocol: Mapping[str, Any], task_digest: str,
            phase: str, output: str) -> tuple[Mapping[str, Any], Mapping[str, Any]]:
        from .developmental_model_replacement_experiment import _verify_objective_score
        plan = _fixture_plan(protocol, _task_row(protocol, task_digest, phase))
        output_digest = digest_payload({"output": output})
        result = self._scorer(task_plan=plan, output=output,
            output_digest=output_digest)
        if (not isinstance(result, Mapping)
                or set(result) != {"score", "attestation"}
                or not isinstance(result.get("score"), Mapping)
                or not isinstance(result.get("attestation"), Mapping)):
            raise ValueError("durable_learning_score_invalid")
        try:
            score = _verify_objective_score(plan, result["score"], output_digest)
        except (TypeError, ValueError) as exc:
            raise ValueError("durable_learning_score_invalid") from exc
        attestation = dict(result["attestation"])
        if not verify_durable_learning_score_attestation(protocol=protocol,
                task_plan=plan, output_digest=output_digest,
                score=score, attestation=attestation):
            raise ValueError("durable_learning_scorer_attestation_invalid")
        return score, attestation

    def _verify_protocol_is_persisted(self,
            protocol: Mapping[str, Any]) -> None:
        verify_durable_learning_protocol(protocol)
        if self._store.load(protocol["protocol_id"]) != dict(protocol):
            raise ValueError("durable_learning_protocol_not_persisted")

    def _invoke(self, *, protocol: Mapping[str, Any], phase: str,
            condition: str, task_digest: str, prompt: str,
            pre_effect_guard: Callable[[], Mapping[str, Any]],
            caller_linkage: Mapping[str, Any]) -> dict[str, Any]:
        branch = self._branch_for(condition)
        linkage = dict(caller_linkage)
        if branch is not None:
            linkage["durable_learning_condition_branch_id"] = branch.branch_id
        result = self._executor_for(condition)(protocol=dict(protocol), phase=phase,
            condition=condition, task_digest=task_digest, prompt=prompt,
            pre_effect_guard=pre_effect_guard,
            caller_linkage=linkage)
        expected = {"output", "invocation_receipt_id",
            "invocation_receipt_digest"}
        if (not isinstance(result, Mapping) or set(result) != expected
                or not isinstance(result.get("output"), str)
                or len(result["output"].encode("utf-8")) > 4096
                or not isinstance(result.get("invocation_receipt_id"), str)
                or not isinstance(result.get("invocation_receipt_digest"), str)):
            raise ValueError("durable_learning_executor_result_invalid")
        return dict(result)

    def _existing_outcomes(self, protocol: Mapping[str, Any],
            outcomes: Sequence[Mapping[str, Any]], *, phase: str
            ) -> dict[tuple[str, str], Mapping[str, Any]]:
        if not isinstance(outcomes, Sequence) or isinstance(outcomes, (str, bytes)):
            raise ValueError("durable_learning_existing_outcomes_invalid")
        observed: dict[tuple[str, str], Mapping[str, Any]] = {
            (outcome["condition"], outcome["task_digest"]): outcome
            for outcome in self._store.load_outcomes(protocol, phase=phase)}
        for outcome in outcomes:
            verify_durable_learning_outcome(protocol, outcome,
                invocation_receipt_verifier=self._receipt_verifier)
            persisted = self._store.load_outcome(protocol,
                outcome["outcome_id"])
            if persisted != dict(outcome):
                raise ValueError("durable_learning_existing_outcome_not_persisted")
            key = (outcome.get("condition"), outcome.get("task_digest"))
            if outcome.get("phase") != phase:
                raise ValueError("durable_learning_existing_outcome_duplicate")
            if key in observed:
                if dict(observed[key]) == dict(outcome):
                    continue
                raise ValueError("durable_learning_existing_outcome_duplicate")
            observed[key] = outcome
        _verify_scheduled_condition_order(protocol,
            {(phase, condition, task_digest): outcome
                for (condition, task_digest), outcome in observed.items()},
            phase=phase)
        return observed

    def _recover_interrupted_attempts(self, *, protocol: Mapping[str, Any],
            phase: str, completed_outcomes: Mapping[tuple[str, str],
                Mapping[str, Any]],
            feedback_records: Sequence[Mapping[str, Any]] = (),
            acquisition_outcomes: Sequence[Mapping[str, Any]] = ()
            ) -> list[dict[str, Any]]:
        attempts = self._store.unresolved_invocation_attempts(protocol,
            phase=phase, completed_prompt_digests={key: outcome[
                "prompt_digest"] for key, outcome in completed_outcomes.items()})
        if not attempts:
            return []
        recover = getattr(self._receipt_verifier,
            "recover_completed_invocation", None)
        if not callable(recover):
            raise ValueError("durable_learning_attempt_unresolved")
        feedback_digests = [row.get("feedback_digest")
            for row in feedback_records]
        recovered_outcomes = []
        for attempt in attempts:
            condition = attempt["condition"]
            task_digest = attempt["task_digest"]
            if phase == "acquisition":
                experiences = (self._experience_source_for(condition).records_for_prompt(
                    protocol=protocol, task_digest=task_digest)
                    if condition == _CONDITIONS[0] else [])
                prompt = build_durable_learning_prompt(
                    task_descriptor=_task_row(protocol, task_digest,
                        phase)["descriptor"], phase=phase,
                    condition=condition, experience_records=experiences,
                    feedback_records=feedback_records)
                available_experience_digests = (
                    list(protocol["acquisition_experience_digests"])
                    if condition == _CONDITIONS[0] else [])
                preceding_feedback_digests = feedback_digests
            else:
                experiences = []
                prompt = build_durable_learning_prompt(
                    task_descriptor=_task_row(protocol, task_digest,
                        phase)["descriptor"], phase=phase,
                    condition=condition)
                available_experience_digests = []
                preceding_feedback_digests = []
            prompt_digest = digest_payload({"prompt": prompt})
            if prompt_digest != attempt["prompt_digest"]:
                raise ValueError("durable_learning_attempt_prompt_mismatch")
            recovered = recover(protocol=dict(protocol), phase=phase,
                condition=condition, task_digest=task_digest,
                prompt_digest=prompt_digest)
            if recovered is None:
                raise ValueError("durable_learning_attempt_unresolved")
            if (not isinstance(recovered, Mapping)
                    or not isinstance(recovered.get("output"), str)
                    or not isinstance(recovered.get("receipt_id"), str)
                    or not isinstance(recovered.get("receipt_digest"), str)
                    or not isinstance(recovered.get("guard_evidence"), Mapping)
                    or not isinstance(recovered.get("caller_linkage"), Mapping)):
                raise ValueError("durable_learning_recovered_invocation_invalid")
            gate = None
            gate_id = recovered["caller_linkage"].get(
                "durable_learning_probe_gate_id")
            if phase == "delayed_probe":
                if not isinstance(gate_id, str):
                    raise ValueError("durable_learning_recovered_probe_gate_missing")
                gate = self._store.load_probe_start_gate(protocol,
                    acquisition_outcomes, gate_id)
            score, scorer_attestation = self._score(protocol, task_digest,
                phase, recovered["output"])
            guard_evidence = recovered["guard_evidence"]
            outcome = make_durable_learning_outcome(protocol=protocol,
                phase=phase, condition=condition, task_digest=task_digest,
                prompt_digest=prompt_digest,
                invocation_attempt_id=attempt["attempt_id"],
                invocation_receipt_id=recovered["receipt_id"],
                invocation_receipt_digest=recovered["receipt_digest"],
                invocation_receipt_verifier=self._receipt_verifier,
                score=score, scorer_attestation=scorer_attestation,
                retained_state_digest=guard_evidence.get(
                    "retained_state_digest"),
                retained_state_record_refs=guard_evidence.get(
                    "retained_state_record_refs"),
                probe_start_gate=gate,
                available_experience_digests=available_experience_digests,
                preceding_feedback_digests=preceding_feedback_digests,
                output=recovered["output"],
                outcome_reconstruction_posture=(
                    "reconstructed_from_stored_receipt"))
            self._store.persist_outcome(protocol, outcome)
            recovered_outcomes.append(outcome)
        return recovered_outcomes

    def run_acquisition(self, *, protocol: Mapping[str, Any],
            feedback_records: Sequence[Mapping[str, Any]],
            existing_outcomes: Sequence[Mapping[str, Any]] = ()
            ) -> list[dict[str, Any]]:
        """Run any missing paired acquisition calls and persist their outcomes."""
        self._require_retention_eligible_protocol(protocol)
        self._verify_condition_branch_bindings(protocol, baseline=True)
        self._verify_protocol_is_persisted(protocol)
        existing = self._existing_outcomes(protocol, existing_outcomes,
            phase="acquisition")
        expected = {(condition, task_digest) for condition in _CONDITIONS
            for task_digest in protocol["acquisition_task_digests"]}
        if not set(existing).issubset(expected):
            raise ValueError("durable_learning_existing_acquisition_unbound")
        feedback_digests = [row.get("feedback_digest")
            for row in feedback_records if isinstance(row, Mapping)]
        if len(feedback_digests) != len(feedback_records):
            raise ValueError("durable_learning_feedback_record_invalid")
        preflight = getattr(self._receipt_verifier,
            "verify_feedback_batch", None)
        if not callable(preflight) or preflight(protocol=dict(protocol),
                feedback_records=feedback_records) is not True:
            raise ValueError("durable_learning_feedback_batch_preflight_failed")
        recovered = self._recover_interrupted_attempts(protocol=protocol,
            phase="acquisition", completed_outcomes=existing,
            feedback_records=feedback_records)
        for outcome in recovered:
            existing[(outcome["condition"], outcome["task_digest"])] = outcome
        self._store.verify_no_unresolved_attempts(protocol, phase="acquisition",
            completed_prompt_digests={key: outcome["prompt_digest"]
                for key, outcome in existing.items()})
        prepared: dict[tuple[str, str], tuple[list[dict[str, Any]], str,
            DurableLearningPromptGuard]] = {}
        for task_digest in protocol["acquisition_task_digests"]:
            for condition in protocol["condition_contract"][
                    "acquisition_order_by_task"][task_digest]:
                key = (condition, task_digest)
                if key in existing:
                    continue
                experiences = (self._experience_source_for(condition).records_for_prompt(
                    protocol=protocol, task_digest=task_digest)
                    if condition == _CONDITIONS[0] else [])
                prompt = build_durable_learning_prompt(
                    task_descriptor=_task_row(protocol, task_digest,
                        "acquisition")["descriptor"],
                    phase="acquisition", condition=condition,
                    experience_records=experiences,
                    feedback_records=feedback_records)
                attempt_prompt_digest = digest_payload({"prompt": prompt})
                guard = DurableLearningPromptGuard(protocol=protocol,
                    phase="acquisition", condition=condition,
                    task_digest=task_digest, prompt=prompt,
                    retained_state_snapshot_resolver=(
                        self._snapshot_resolver_for(condition)),
                    experience_records=experiences,
                    feedback_records=feedback_records,
                    on_pre_effect_evidence=lambda _evidence,
                        attempt_condition=condition,
                        attempt_task_digest=task_digest,
                        prompt_digest=attempt_prompt_digest:
                        self._store.begin_invocation_attempt(protocol,
                            phase="acquisition", condition=attempt_condition,
                            task_digest=attempt_task_digest,
                            prompt_digest=prompt_digest))
                prepared[key] = (experiences, prompt, guard)
        results = dict(existing)
        for task_digest in protocol["acquisition_task_digests"]:
            order = protocol["condition_contract"][
                "acquisition_order_by_task"][task_digest]
            for condition in order:
                key = (condition, task_digest)
                if key in results:
                    continue
                experiences, prompt, guard = prepared[key]
                invocation = self._invoke(protocol=protocol,
                    phase="acquisition", condition=condition,
                    task_digest=task_digest, prompt=prompt,
                    pre_effect_guard=guard, caller_linkage={})
                evidence = guard.evidence
                if not isinstance(evidence, Mapping):
                    raise ValueError("durable_learning_prompt_guard_not_invoked")
                score, scorer_attestation = self._score(protocol, task_digest,
                    "acquisition", invocation["output"])
                outcome = make_durable_learning_outcome(protocol=protocol,
                    phase="acquisition", condition=condition,
                    task_digest=task_digest, prompt_digest=guard.prompt_digest,
                    invocation_attempt_id=guard.invocation_attempt_id,
                    invocation_receipt_id=invocation["invocation_receipt_id"],
                    invocation_receipt_digest=invocation[
                        "invocation_receipt_digest"],
                    invocation_receipt_verifier=self._receipt_verifier,
                    score=score, scorer_attestation=scorer_attestation,
                    retained_state_digest=evidence["retained_state_digest"],
                    available_experience_digests=(
                        list(protocol["acquisition_experience_digests"])
                        if condition == _CONDITIONS[0] else []),
                    preceding_feedback_digests=feedback_digests,
                    output=invocation["output"])
                self._store.persist_outcome(protocol, outcome)
                results[key] = outcome
        if set(results) != expected:
            raise ValueError("durable_learning_acquisition_set_incomplete")
        verify_durable_learning_acquisition_outcomes(protocol,
            list(results.values()),
            invocation_receipt_verifier=self._receipt_verifier)
        return [dict(results[key]) for key in sorted(results)]

    def build_branch_consolidation_snapshots(self, *,
            protocol: Mapping[str, Any],
            acquisition_outcomes: Sequence[Mapping[str, Any]] = (),
            require_baseline: bool = True
            ) -> dict[str, Any]:
        """Prepare receipt-bound World-State inputs for each resident branch.

        This is read-only. A later explicit resident-owner tick must consume
        each snapshot with a condition-scoped history policy before any
        developmental writeback can be attributed to consolidation.
        """
        self._verify_protocol_is_persisted(protocol)
        self._verify_condition_branch_bindings(protocol,
            baseline=require_baseline)
        if protocol.get("feedback_policy_digest") != NO_FEEDBACK_POLICY_DIGEST:
            raise ValueError("durable_learning_consolidation_feedback_policy_unsupported")
        outcomes_by_key = self._existing_outcomes(protocol,
            acquisition_outcomes, phase="acquisition")
        expected = {(condition, task_digest) for condition in _CONDITIONS
            for task_digest in protocol["acquisition_task_digests"]}
        if set(outcomes_by_key) != expected:
            raise ValueError("durable_learning_acquisition_set_incomplete")
        all_outcomes = list(outcomes_by_key.values())
        verify_durable_learning_acquisition_outcomes(protocol, all_outcomes,
            invocation_receipt_verifier=self._receipt_verifier)
        snapshots = {condition:
            build_durable_learning_consolidation_snapshot(
                protocol=protocol, condition=condition,
                branch=self._condition_branches[condition],
                acquisition_outcomes=[outcome for outcome in all_outcomes
                    if outcome["condition"] == condition],
                invocation_receipt_verifier=self._receipt_verifier)
            for condition in _CONDITIONS}
        return {"schema_version":
                "sentientos.durable_learning_consolidation_snapshot_bundle:v1",
            "protocol_id": protocol["protocol_id"],
            "protocol_digest": protocol["protocol_digest"],
            "condition_branch_ids": {condition:
                self._condition_branches[condition].branch_id
                for condition in _CONDITIONS},
            "snapshots": snapshots,
            "resident_tick_history_policy": {
                _CONDITIONS[0]: "branch_history_available",
                _CONDITIONS[1]: "all_prior_history_withheld"},
            "withhold_developmental_history": {
                _CONDITIONS[0]: False, _CONDITIONS[1]: True},
            "scorer_outcomes_included": False,
            "feedback_policy_digest": protocol["feedback_policy_digest"],
            "developmental_writeback_performed": False,
            "retention_contrast_eligible": False,
            "authority": False}

    def run_branch_consolidation_ticks(self, *,
            protocol: Mapping[str, Any],
            acquisition_outcomes: Sequence[Mapping[str, Any]] = ()
            ) -> dict[str, Any]:
        """Run one journaled resident tick per branch from verified acquisition.

        This path remains descriptive-only because no supported protocol is
        currently retention-contrast eligible. Protocol v7 did not preregister
        a consolidation policy; v8 through v10 do, but that design binding alone
        does not establish branch isolation or retention eligibility. The path
        uses the resident owner's admitted writeback route and never passes
        scorer outcomes into either branch tick. The withheld arm must produce
        a receipt-verified typed cognition observation with no history packets.
        """
        import inspect

        if not self._allow_descriptive_only_execution:
            raise ValueError("durable_learning_descriptive_only_execution_not_enabled")
        self._verify_protocol_is_persisted(protocol)
        intents, receipts = self._store.load_consolidation_artifacts(protocol)
        if not set(receipts).issubset(intents):
            raise ValueError("durable_learning_consolidation_intent_missing")
        outcomes_by_key = self._existing_outcomes(protocol,
            acquisition_outcomes, phase="acquisition")
        expected = {(condition, task_digest) for condition in _CONDITIONS
            for task_digest in protocol["acquisition_task_digests"]}
        if set(outcomes_by_key) != expected:
            raise ValueError("durable_learning_acquisition_set_incomplete")
        all_outcomes = list(outcomes_by_key.values())
        verify_durable_learning_acquisition_outcomes(protocol, all_outcomes,
            invocation_receipt_verifier=self._receipt_verifier)
        bundle = self.build_branch_consolidation_snapshots(
            protocol=protocol, acquisition_outcomes=all_outcomes,
            require_baseline=not bool(intents))
        results: dict[str, dict[str, Any]] = {}
        for condition in _CONDITIONS:
            branch = self._condition_branches[condition]
            owner = branch.experience_source._owner
            config = getattr(owner, "config", None)
            allowed_sources = getattr(config, "allowed_source_kinds", ())
            if (not callable(getattr(owner, "run_tick", None))
                    or not callable(getattr(owner,
                        "developmental_tick_status", None))
                    or not callable(getattr(owner,
                        "developmental_tick_observations", None))
                    or not callable(getattr(getattr(owner, "writeback", None),
                        "inspect_completed_records", None))
                    or not isinstance(allowed_sources, (list, tuple))
                    or not {"developmental_experiment_input", "local_model_output"}
                        .issubset(set(allowed_sources))
                    or getattr(config, "enabled", False) is not True
                    or getattr(config, "comparison_enabled", False) is not False
                    or getattr(owner, "objective_task", None) is not None
                    or "withhold_developmental_history" not in
                        inspect.signature(owner.run_tick).parameters
                    or "durable_learning_history_record_allowlist" not in
                        inspect.signature(owner.run_tick).parameters
                    or "durable_learning_no_history_observation" not in
                        inspect.signature(owner.run_tick).parameters):
                raise ValueError("durable_learning_consolidation_owner_not_ready")
            snapshot = bundle["snapshots"][condition]
            source_fact_ids = [fact.fact_id for fact in snapshot.facts]
            tick_id = (f"durable-learning-consolidation-"
                f"{protocol['protocol_id']}-{condition}")
            baseline = intents.get(condition)
            current_state = branch.experience_source.current_history_state_snapshot()
            if baseline is None:
                if (current_state["history_state_digest"] !=
                        protocol["baseline_history_state_digest"]):
                    raise ValueError(
                        "durable_learning_consolidation_baseline_changed")
                baseline_refs = [dict(ref)
                    for ref in current_state["record_refs"]]
            else:
                baseline_refs = baseline.get("baseline_record_refs")
                if (baseline.get("tick_id") != tick_id
                        or baseline.get("snapshot_id") != snapshot.snapshot_id
                        or baseline.get("snapshot_digest") != snapshot.digest
                        or baseline.get("source_fact_ids") != source_fact_ids
                        or baseline.get("withhold_developmental_history") is not
                            (condition == _CONDITIONS[1])):
                    raise ValueError("durable_learning_consolidation_intent_conflict")
            intent = self._store.persist_consolidation_intent(protocol,
                condition=condition, branch_id=branch.branch_id,
                tick_id=tick_id, snapshot_id=snapshot.snapshot_id,
                snapshot_digest=snapshot.digest,
                baseline_history_state_digest=(
                    protocol["baseline_history_state_digest"]),
                withhold_developmental_history=(condition == _CONDITIONS[1]),
                baseline_record_refs=baseline_refs,
                source_fact_ids=source_fact_ids)
            prior_receipt = receipts.get(condition)
            if prior_receipt is not None:
                results[condition] = self._verify_persisted_consolidation_receipt(
                    protocol=protocol, branch=branch, intent=intent,
                    receipt=prior_receipt)
                continue
            tick_status = owner.developmental_tick_status(tick_id=tick_id)
            if tick_status.get("status") == "interrupted":
                raise ValueError("durable_learning_consolidation_tick_interrupted")
            if tick_status.get("status") == "completed":
                tick_row = tick_status.get("tick")
                if (not isinstance(tick_row, Mapping)
                        or tick_row.get("snapshot_id") != snapshot.snapshot_id
                        or tick_row.get("snapshot_digest") != snapshot.digest):
                    raise ValueError("durable_learning_consolidation_tick_binding_invalid")
                cycle_result: Any = None
                record_id = tick_row.get("record_id")
                receipt_id = tick_row.get("receipt_id")
                status = "recovered_completed_tick"
                selected_fact_ids: list[str] = []
                observation_ids: list[str] = []
            elif tick_status.get("status") == "not_started":
                if (current_state["history_state_digest"] !=
                        protocol["baseline_history_state_digest"]):
                    raise ValueError(
                        "durable_learning_consolidation_state_changed_before_tick")
                history_record_allowlist = (tuple(ref["record_id"]
                    for ref in _durable_learning_target_experience_refs(
                        protocol=protocol, branch=branch))
                    if condition == _CONDITIONS[0] else None)
                cycle_result = owner.run_tick(snapshot=snapshot, tick_id=tick_id,
                    withhold_developmental_history=(condition == _CONDITIONS[1]),
                    durable_learning_history_record_allowlist=(
                        history_record_allowlist),
                    durable_learning_no_history_observation=(
                        condition == _CONDITIONS[1]))
                if (getattr(cycle_result, "tick_id", None) != tick_id
                        or getattr(cycle_result, "snapshot_id", None) !=
                            snapshot.snapshot_id):
                    raise ValueError("durable_learning_consolidation_tick_result_invalid")
                record_id = getattr(cycle_result, "written_record_id", None)
                receipt_id = getattr(cycle_result, "writeback_receipt_id", None)
                status = getattr(cycle_result, "status", "unknown")
                selected_fact_ids = list(getattr(cycle_result,
                    "selected_fact_ids", ()))
                observation_ids = list(getattr(cycle_result,
                    "cognition_observation_ids", ()))
            else:
                raise ValueError("durable_learning_consolidation_tick_status_invalid")
            verified_observations = owner.developmental_tick_observations(
                tick_id=tick_id)
            verified_observation_ids = [value.get("observation_id")
                for value in verified_observations]
            if observation_ids and observation_ids != verified_observation_ids:
                raise ValueError(
                    "durable_learning_consolidation_observation_reload_mismatch")
            observation_ids = verified_observation_ids
            target_experience_refs = (_durable_learning_target_experience_refs(
                protocol=protocol, branch=branch)
                if condition == _CONDITIONS[0] else [])
            if condition == _CONDITIONS[1] and (
                    len(verified_observations) != 1
                    or verified_observations[0].get("condition_id") !=
                        "durable-learning-history-withheld"
                    or verified_observations[0].get(
                        "developmental_projection_present") is not False
                    or not _durable_learning_observation_has_no_prior_context(
                        verified_observations[0])
                    or verified_observations[0].get("retrieved_record_ids")
                    or verified_observations[0].get(
                        "retrieved_record_digests")
                    or not verified_observations[0].get("current_fact_ids")
                    or not set(verified_observations[0].get(
                        "current_fact_ids", ())).issubset(set(source_fact_ids))
                    or verified_observations[0].get("current_snapshot_id") !=
                        snapshot.snapshot_id
                    or verified_observations[0].get("current_snapshot_digest") !=
                        snapshot.digest):
                raise ValueError(
                    "durable_learning_consolidation_withheld_observation_invalid")
            if condition == _CONDITIONS[0] and (
                    len(verified_observations) != 1
                    or any(value.get("condition_id") != "with-history"
                        or not _durable_learning_observation_has_history_context(
                            value, baseline_refs,
                            target_experience_refs)
                        or not set(value.get("current_fact_ids", ())).issubset(
                            set(source_fact_ids))
                        for value in verified_observations)):
                raise ValueError(
                    "durable_learning_consolidation_available_observation_invalid")
            post_state = branch.experience_source.current_history_state_snapshot()
            _verify_append_only_consolidation_state(baseline_refs,
                post_state["record_refs"])
            baseline_by_id = {ref["record_id"]: dict(ref)
                for ref in baseline_refs}
            post_by_id = {ref["record_id"]: dict(ref)
                for ref in post_state["record_refs"]}
            new_refs = [post_by_id[key] for key in sorted(
                set(post_by_id) - set(baseline_by_id))]
            writeback_ref: dict[str, str] | None = None
            writeback_receipt_ref: dict[str, str] | None = None
            if record_id is None and receipt_id is None:
                if new_refs:
                    raise ValueError(
                        "durable_learning_consolidation_unattributed_state_change")
            elif not isinstance(record_id, str) or not isinstance(receipt_id, str):
                raise ValueError("durable_learning_consolidation_writeback_binding_invalid")
            else:
                matches = [(record, writeback_receipt)
                    for record, writeback_receipt in
                        owner.writeback.inspect_completed_records()
                    if record.record_id == record_id
                    and writeback_receipt.receipt_id == receipt_id]
                if len(matches) != 1:
                    raise ValueError("durable_learning_consolidation_writeback_unverified")
                record, writeback_receipt = matches[0]
                expected_ref = {"record_id": record.record_id,
                    "record_digest": record.record_digest}
                if (new_refs != [expected_ref]
                        or writeback_receipt.record_id != record.record_id
                        or writeback_receipt.record_digest != record.record_digest
                        or writeback_receipt.storage_verified is not True
                        or writeback_receipt.grants_authority is not False):
                    raise ValueError("durable_learning_consolidation_writeback_lineage_invalid")
                candidate = record.candidate
                facts = (candidate.get("selected_facts", ())
                    if isinstance(candidate, Mapping) else ())
                selected_fact_ids_from_record = [fact.get("fact_id")
                    for fact in facts if isinstance(fact, Mapping)]
                if (not selected_fact_ids_from_record
                        or not set(selected_fact_ids_from_record).issubset(
                            set(source_fact_ids))):
                    raise ValueError(
                        "durable_learning_consolidation_evidence_lineage_invalid")
                selected_fact_ids = selected_fact_ids_from_record
                writeback_ref = expected_ref
                writeback_receipt_ref = {"receipt_id": writeback_receipt.receipt_id,
                    "receipt_digest": writeback_receipt.receipt_digest}
            strategy_projection = build_durable_learning_strategy_projection(
                protocol=protocol, condition=condition, branch=branch,
                tick_id=tick_id, snapshot_id=snapshot.snapshot_id,
                snapshot_digest=snapshot.digest,
                source_fact_ids=source_fact_ids,
                writeback_record_ref=writeback_ref,
                writeback_receipt_ref=writeback_receipt_ref)
            if strategy_projection is not None:
                verify_durable_learning_strategy_projection(protocol,
                    condition=condition, branch_id=branch.branch_id,
                    branch=branch,
                    projection=strategy_projection)
            receipt_payload = {"schema_version":
                    "sentientos.durable_learning_consolidation_receipt:v2",
                "protocol_id": protocol["protocol_id"],
                "protocol_digest": protocol["protocol_digest"],
                "condition": condition, "branch_id": branch.branch_id,
                "intent_id": intent["intent_id"],
                "intent_digest": intent["intent_digest"],
                "tick_id": tick_id, "snapshot_id": snapshot.snapshot_id,
                "snapshot_digest": snapshot.digest,
                "resident_tick_status": status,
                "withhold_developmental_history":
                    condition == _CONDITIONS[1],
                "source_fact_ids": source_fact_ids,
                "selected_fact_ids": selected_fact_ids,
                "cognition_observation_ids": observation_ids,
                "post_history_state_snapshot": post_state,
                "new_writeback_refs": new_refs,
                "writeback_record_ref": writeback_ref,
                "writeback_receipt_ref": writeback_receipt_ref,
                "strategy_projection": strategy_projection,
                "strategy_projection_digest": (
                    strategy_projection.get("projection_digest")
                    if strategy_projection is not None else None),
                "developmental_writeback_performed": writeback_ref is not None,
                "scorer_outcomes_included": False,
                "consolidation_policy_preregistered": (
                    protocol.get("schema_version") in _POLICY_PROTOCOL_SCHEMAS),
                "retention_contrast_eligible": False,
                "authority": False}
            sealed = self._store.persist_consolidation_receipt(protocol,
                intent=intent, receipt=receipt_payload)
            results[condition] = self._verify_persisted_consolidation_receipt(
                protocol=protocol, branch=branch, intent=intent,
                receipt=sealed)
        all_writebacks = all(results[condition].get(
            "developmental_writeback_performed") is True
            for condition in _CONDITIONS)
        all_strategy_projections = all(
            isinstance(results[condition].get("strategy_projection"), Mapping)
            and results[condition].get("strategy_projection_digest") ==
                results[condition]["strategy_projection"].get("projection_digest")
            for condition in _CONDITIONS)
        return {"schema_version":
                "sentientos.durable_learning_consolidation_run:v1",
            "protocol_id": protocol["protocol_id"],
            "protocol_digest": protocol["protocol_digest"],
            "condition_receipts": results,
            "both_branch_writebacks_verified": all_writebacks,
            "both_branch_strategy_projections_verified": all_strategy_projections,
            "strategy_projections_probe_eligible": False,
            "consolidation_policy_preregistered": (
                protocol.get("schema_version") in _POLICY_PROTOCOL_SCHEMAS),
            "retention_contrast_eligible": False,
            "durable_learning_established": False,
            "authority": False}

    def _verify_persisted_consolidation_receipt(self, *,
            protocol: Mapping[str, Any],
            branch: DurableLearningConditionBranch,
            intent: Mapping[str, Any], receipt: Mapping[str, Any]
            ) -> dict[str, Any]:
        self._store._verify_consolidation_identity(receipt, artifact="receipt")
        branch_ids = verify_durable_learning_protocol(protocol).get(
            "condition_branch_ids", {})
        branch_condition = next((condition for condition in _CONDITIONS
            if branch_ids.get(condition) == branch.branch_id), None)
        if branch_condition is None:
            raise ValueError("durable_learning_consolidation_branch_unbound")
        post_state = _resolve_history_state_snapshot(lambda:
            receipt.get("post_history_state_snapshot"))
        current_state = branch.experience_source.current_history_state_snapshot()
        if (receipt.get("protocol_id") != protocol.get("protocol_id")
                or receipt.get("protocol_digest") != protocol.get("protocol_digest")
                or receipt.get("schema_version") not in {
                    "sentientos.durable_learning_consolidation_receipt:v1",
                    "sentientos.durable_learning_consolidation_receipt:v2"}
                or receipt.get("condition") not in _CONDITIONS
                or receipt.get("condition") != branch_condition
                or intent.get("condition") != branch_condition
                or intent.get("branch_id") != branch.branch_id
                or receipt.get("branch_id") != branch.branch_id
                or receipt.get("intent_id") != intent.get("intent_id")
                or receipt.get("intent_digest") != intent.get("intent_digest")
                or intent.get("protocol_id") != protocol.get("protocol_id")
                or intent.get("protocol_digest") != protocol.get("protocol_digest")
                or intent.get("baseline_history_state_digest") !=
                    protocol.get("baseline_history_state_digest")
                or receipt.get("tick_id") != intent.get("tick_id")
                or receipt.get("snapshot_id") != intent.get("snapshot_id")
                or receipt.get("snapshot_digest") != intent.get("snapshot_digest")
                or receipt.get("source_fact_ids") != intent.get("source_fact_ids")
                or not isinstance(receipt.get("source_fact_ids"), list)
                or any(not isinstance(value, str) or not value
                    for value in receipt.get("source_fact_ids", ()))
                or len(set(receipt.get("source_fact_ids", ()))) !=
                    len(receipt.get("source_fact_ids", ()))
                or not isinstance(receipt.get("selected_fact_ids"), list)
                or any(not isinstance(value, str) or not value
                    for value in receipt.get("selected_fact_ids", ()))
                or len(set(receipt.get("selected_fact_ids", ()))) !=
                    len(receipt.get("selected_fact_ids", ()))
                or not set(receipt.get("selected_fact_ids", ())).issubset(
                    set(receipt.get("source_fact_ids", ())))
                or receipt.get("withhold_developmental_history") is not
                    intent.get("withhold_developmental_history")
                or not isinstance(receipt.get("cognition_observation_ids"), list)
                or any(not isinstance(value, str) or not value
                    for value in receipt.get("cognition_observation_ids", ()))
                or len(set(receipt.get("cognition_observation_ids", ())))
                    != len(receipt.get("cognition_observation_ids", ()))
                or post_state != receipt.get("post_history_state_snapshot")
                or current_state != post_state
                or type(receipt.get("developmental_writeback_performed")) is not bool
                or receipt.get("consolidation_policy_preregistered") is not (
                    protocol.get("schema_version") in _POLICY_PROTOCOL_SCHEMAS)
                or receipt.get("retention_contrast_eligible") is not False
                or receipt.get("scorer_outcomes_included") is not False):
            raise ValueError("durable_learning_consolidation_receipt_invalid")
        owner = branch.experience_source._owner
        expected_projection = None
        if receipt.get("schema_version") == (
                "sentientos.durable_learning_consolidation_receipt:v2"):
            expected_projection = build_durable_learning_strategy_projection(
                protocol=protocol, condition=str(intent.get("condition", "")),
                branch=branch, tick_id=str(intent.get("tick_id", "")),
                snapshot_id=str(intent.get("snapshot_id", "")),
                snapshot_digest=str(intent.get("snapshot_digest", "")),
                source_fact_ids=intent.get("source_fact_ids", ()),
                writeback_record_ref=receipt.get("writeback_record_ref"),
                writeback_receipt_ref=receipt.get("writeback_receipt_ref"))
            if (expected_projection != receipt.get("strategy_projection")
                    or receipt.get("strategy_projection_digest") != (
                        expected_projection.get("projection_digest")
                        if expected_projection is not None else None)):
                raise ValueError(
                    "durable_learning_strategy_projection_receipt_invalid")
            if expected_projection is not None:
                verify_durable_learning_strategy_projection(protocol,
                    condition=str(intent.get("condition", "")),
                    branch_id=branch.branch_id, branch=branch,
                    projection=expected_projection)
        observations = owner.developmental_tick_observations(
            tick_id=str(intent.get("tick_id", "")))
        if ([value.get("observation_id") for value in observations]
                != receipt.get("cognition_observation_ids")
                or any(value.get("current_snapshot_id") !=
                    intent.get("snapshot_id")
                    or value.get("current_snapshot_digest") !=
                        intent.get("snapshot_digest")
                    for value in observations)):
            raise ValueError(
                "durable_learning_consolidation_observation_reload_mismatch")
        if expected_projection is not None:
            source_observation_ref = expected_projection.get(
                "source_observation_ref")
            source_observation_matches = [observation for observation in
                observations if isinstance(source_observation_ref, Mapping)
                and observation.get("observation_id") ==
                    source_observation_ref.get("observation_id")
                and observation.get("observation_digest") ==
                    source_observation_ref.get("observation_digest")]
            if len(source_observation_matches) != 1:
                raise ValueError(
                    "durable_learning_projection_observation_not_in_tick_receipt")
        reloaded_current_fact_ids = {fact_id
            for observation in observations
            for fact_id in observation.get("current_fact_ids", ())}
        selected_fact_ids = set(receipt.get("selected_fact_ids", ()))
        if (receipt.get("developmental_writeback_performed") is True
                and (not selected_fact_ids
                    or not selected_fact_ids.issubset(
                        reloaded_current_fact_ids))):
            raise ValueError(
                "durable_learning_writeback_fact_observation_mismatch")
        if (receipt.get("developmental_writeback_performed") is False
                and selected_fact_ids):
            raise ValueError(
                "durable_learning_unwritten_selected_facts_present")
        if intent.get("condition") == _CONDITIONS[1]:
            if (len(observations) != 1
                    or observations[0].get("condition_id") !=
                        "durable-learning-history-withheld"
                    or observations[0].get("developmental_projection_present") is not False
                    or not _durable_learning_observation_has_no_prior_context(
                        observations[0])
                    or observations[0].get("retrieved_record_ids")
                    or observations[0].get("retrieved_record_digests")
                    or not observations[0].get("current_fact_ids")
                    or not set(observations[0].get("current_fact_ids", ())).issubset(
                        set(intent.get("source_fact_ids", ())))):
                raise ValueError(
                    "durable_learning_consolidation_withheld_observation_invalid")
        else:
            target_experience_refs = _durable_learning_target_experience_refs(
                protocol=protocol, branch=branch)
            if (len(observations) != 1
                    or any(value.get("condition_id") != "with-history"
                        or not _durable_learning_observation_has_history_context(
                            value, intent.get("baseline_record_refs"),
                            target_experience_refs)
                        or not set(value.get("current_fact_ids", ())).issubset(
                            set(intent.get("source_fact_ids", ())))
                        for value in observations)):
                raise ValueError(
                    "durable_learning_consolidation_available_observation_invalid")
        baseline_refs = intent.get("baseline_record_refs")
        if (not isinstance(baseline_refs, list)
                or any(not isinstance(ref, Mapping)
                    or set(ref) not in ({"record_id", "record_digest"},
                        {"record_id", "record_digest", "receipt_id",
                            "receipt_digest"})
                    for ref in baseline_refs)):
            raise ValueError("durable_learning_consolidation_baseline_refs_invalid")
        _verify_append_only_consolidation_state(baseline_refs,
            post_state["record_refs"])
        baseline_by_id = {ref["record_id"]: dict(ref) for ref in baseline_refs}
        post_by_id = {ref["record_id"]: dict(ref)
            for ref in post_state["record_refs"]}
        added = [post_by_id[key] for key in sorted(
            set(post_by_id) - set(baseline_by_id))]
        if added != receipt.get("new_writeback_refs"):
            raise ValueError("durable_learning_consolidation_state_delta_invalid")
        writeback_ref = receipt.get("writeback_record_ref")
        receipt_ref = receipt.get("writeback_receipt_ref")
        if receipt.get("developmental_writeback_performed") is True:
            if (not isinstance(writeback_ref, Mapping)
                    or set(writeback_ref) != {"record_id", "record_digest"}
                    or added != [dict(writeback_ref)]
                    or not isinstance(receipt_ref, Mapping)
                    or set(receipt_ref) != {"receipt_id", "receipt_digest"}):
                raise ValueError("durable_learning_consolidation_writeback_ref_invalid")
            completed = owner.writeback.inspect_completed_records()
            matches = [(record, stored_receipt) for record, stored_receipt in completed
                if record.record_id == writeback_ref["record_id"]
                and record.record_digest == writeback_ref["record_digest"]
                and stored_receipt.receipt_id == receipt_ref["receipt_id"]
                and stored_receipt.receipt_digest == receipt_ref["receipt_digest"]]
            if len(matches) != 1:
                raise ValueError("durable_learning_consolidation_writeback_not_reloaded")
            candidate_facts = matches[0][0].candidate.get("selected_facts", ())
            candidate_fact_ids = [fact.get("fact_id") for fact in candidate_facts
                if isinstance(fact, Mapping)]
            if (not candidate_fact_ids
                    or not set(candidate_fact_ids).issubset(
                        set(intent.get("source_fact_ids", ())))
                    or candidate_fact_ids != receipt.get("selected_fact_ids")):
                raise ValueError("durable_learning_consolidation_evidence_binding_invalid")
        elif added or writeback_ref is not None or receipt_ref is not None:
            raise ValueError("durable_learning_consolidation_writeback_posture_invalid")
        return dict(receipt)

    def run_delayed_probes(self, *, protocol: Mapping[str, Any],
            acquisition_outcomes: Sequence[Mapping[str, Any]] = (),
            existing_outcomes: Sequence[Mapping[str, Any]] = (),
            answer_exclusion_attestations: Mapping[str, Mapping[str, Any]] | None = None
            ) -> list[dict[str, Any]]:
        """Run history-free probes only after each pre-effect delay gate opens."""
        if protocol.get("schema_version") in _V10_PROTOCOL_SCHEMAS:
            return self._run_v9_delayed_probes(protocol=protocol,
                acquisition_outcomes=acquisition_outcomes,
                existing_outcomes=existing_outcomes,
                answer_exclusion_attestations=answer_exclusion_attestations)
        if protocol.get("schema_version") == _PROTOCOL_SCHEMA_V9:
            raise ValueError(
                "durable_learning_v9_probe_consumption_not_preregistered")
        if answer_exclusion_attestations is not None:
            raise ValueError("durable_learning_exclusion_attestation_version_invalid")
        self._require_retention_eligible_protocol(protocol)
        self._verify_condition_branch_bindings(protocol, baseline=False)
        self._verify_protocol_is_persisted(protocol)
        if protocol.get("schema_version") in _BRANCH_PROTOCOL_SCHEMAS:
            if self._condition_branches is None:
                raise ValueError("durable_learning_condition_branches_required")
            intents, consolidation_receipts = (
                self._store.load_consolidation_artifacts(protocol))
            if (set(intents) != set(_CONDITIONS)
                    or set(consolidation_receipts) != set(_CONDITIONS)):
                raise ValueError(
                    "durable_learning_branch_consolidation_incomplete")
            for condition in _CONDITIONS:
                verified_consolidation = self._verify_persisted_consolidation_receipt(
                    protocol=protocol,
                    branch=self._condition_branches[condition],
                    intent=intents[condition],
                    receipt=consolidation_receipts[condition])
                if verified_consolidation.get(
                        "developmental_writeback_performed") is not True:
                    raise ValueError(
                        "durable_learning_branch_consolidation_writeback_missing")
        acquisition_by_key = self._existing_outcomes(protocol,
            acquisition_outcomes, phase="acquisition")
        expected_acquisition = {(condition, task_digest)
            for condition in _CONDITIONS
            for task_digest in protocol["acquisition_task_digests"]}
        if set(acquisition_by_key) != expected_acquisition:
            raise ValueError("durable_learning_acquisition_set_incomplete")
        verified_acquisition_outcomes = list(acquisition_by_key.values())
        verify_durable_learning_acquisition_outcomes(protocol,
            verified_acquisition_outcomes,
            invocation_receipt_verifier=self._receipt_verifier)
        if protocol.get("schema_version") == _PROTOCOL_SCHEMA_V11:
            competence = self._store.persist_withheld_acquisition_competence_assessment(
                protocol=protocol,
                acquisition_outcomes=verified_acquisition_outcomes)
            if competence.get("qualified") is not True:
                raise ValueError(
                    "durable_learning_baseline_competence_not_demonstrated:"
                    + competence["assessment_id"])
        existing = self._existing_outcomes(protocol, existing_outcomes,
            phase="delayed_probe")
        expected = {(condition, task_digest) for condition in _CONDITIONS
            for task_digest in protocol["delayed_probe_task_digests"]}
        if not set(existing).issubset(expected):
            raise ValueError("durable_learning_existing_probe_unbound")
        recovered = self._recover_interrupted_attempts(protocol=protocol,
            phase="delayed_probe", completed_outcomes=existing,
            acquisition_outcomes=verified_acquisition_outcomes)
        for outcome in recovered:
            existing[(outcome["condition"], outcome["task_digest"])] = outcome
        self._store.verify_no_unresolved_attempts(protocol,
            phase="delayed_probe", completed_prompt_digests={
                key: outcome["prompt_digest"] for key, outcome in existing.items()})
        results = dict(existing)
        state_by_condition: dict[str, tuple[str, str]] = {}
        for (condition, _), outcome in existing.items():
            signature = (outcome["retained_state_digest"], digest_payload({
                "record_refs": outcome["retained_state_record_refs"]}))
            prior = state_by_condition.setdefault(condition, signature)
            if prior != signature:
                raise ValueError("durable_learning_existing_probe_state_inconsistent")
        for task_digest in protocol["delayed_probe_task_digests"]:
            order = protocol["condition_contract"][
                "delayed_probe_order_by_task"][task_digest]
            for condition in order:
                key = (condition, task_digest)
                if key in results:
                    continue
                prompt = build_durable_learning_prompt(
                    task_descriptor=_task_row(protocol, task_digest,
                        "delayed_probe")["descriptor"],
                    phase="delayed_probe", condition=condition)

                def persist_gate(gate: Mapping[str, Any], *,
                        gate_protocol: Mapping[str, Any] = protocol,
                        gate_condition: str = condition,
                        gate_task_digest: str = task_digest) -> str:
                    signature = (gate["retained_state_digest"], digest_payload({
                        "record_refs": gate["retained_state_record_refs"]}))
                    prior = state_by_condition.setdefault(gate_condition,
                        signature)
                    if prior != signature:
                        raise ValueError(
                            "durable_learning_probe_state_changed_before_effect")
                    self._store.persist_probe_start_gate(gate_protocol,
                        verified_acquisition_outcomes, gate)
                    return self._store.begin_invocation_attempt(gate_protocol,
                        phase="delayed_probe", condition=gate_condition,
                        task_digest=gate_task_digest,
                        prompt_digest=gate["probe_prompt_digest"])

                guard = DurableLearningProbeStartGuard(protocol=protocol,
                    acquisition_outcomes=verified_acquisition_outcomes,
                    condition=condition, task_digest=task_digest,
                    probe_prompt=prompt,
                    retained_state_snapshot_resolver=(
                        self._snapshot_resolver_for(condition)),
                    invocation_receipt_verifier=self._receipt_verifier,
                    on_gate_opened=persist_gate,
                    branch_preflight=(self._store.load_condition_branch_preflight(
                        protocol) if protocol.get("schema_version") in
                            _V10_PROTOCOL_SCHEMAS else None))
                invocation = self._invoke(protocol=protocol,
                    phase="delayed_probe", condition=condition,
                    task_digest=task_digest, prompt=prompt,
                    pre_effect_guard=guard,
                    caller_linkage={
                        "durable_learning_probe_gate_id": guard.gate_id})
                gate = guard.gate_receipt
                if not isinstance(gate, Mapping):
                    raise ValueError("durable_learning_probe_gate_not_opened")
                score, scorer_attestation = self._score(protocol, task_digest,
                    "delayed_probe", invocation["output"])
                outcome = make_durable_learning_outcome(protocol=protocol,
                    phase="delayed_probe", condition=condition,
                    task_digest=task_digest, prompt_digest=guard.prompt_digest,
                    invocation_attempt_id=guard.invocation_attempt_id,
                    invocation_receipt_id=invocation["invocation_receipt_id"],
                    invocation_receipt_digest=invocation[
                        "invocation_receipt_digest"],
                    invocation_receipt_verifier=self._receipt_verifier,
                    score=score, scorer_attestation=scorer_attestation,
                    probe_start_gate=gate,
                    retained_state_digest=gate["retained_state_digest"],
                    available_experience_digests=[],
                    preceding_feedback_digests=[], output=invocation["output"])
                self._store.persist_outcome(protocol, outcome)
                results[key] = outcome
        if set(results) != expected:
            raise ValueError("durable_learning_probe_set_incomplete")
        verify_durable_learning_outcome_set(protocol,
            [*verified_acquisition_outcomes, *results.values()],
            invocation_receipt_verifier=self._receipt_verifier,
            retained_update_attribution_verifier=(
                self._store._retained_update_attribution_verifier),
            competence_authorization_receipts=(
                self._store.load_v11_competence_authorization_receipts(
                    protocol=protocol)
                if protocol.get("schema_version") == _PROTOCOL_SCHEMA_V11
                else None))
        return [dict(results[key]) for key in sorted(results)]

    def _run_v9_delayed_probes(self, *, protocol: Mapping[str, Any],
            acquisition_outcomes: Sequence[Mapping[str, Any]],
            existing_outcomes: Sequence[Mapping[str, Any]],
            answer_exclusion_attestations: Mapping[str, Mapping[str, Any]] | None
            ) -> list[dict[str, Any]]:
        """Run V10 probes through the dynamic prompt and bound evidence gate.

        Independent audit signatures are caller supplied. A committed
        interrupted invocation is recovered only after rebuilding its exact
        prompt and reloading the gate against current persisted evidence.
        """
        self._require_retention_eligible_protocol(protocol)
        self._verify_condition_branch_bindings(protocol, baseline=False)
        self._verify_protocol_is_persisted(protocol)
        if self._condition_branches is None:
            raise ValueError("durable_learning_condition_branches_required")
        attestations = answer_exclusion_attestations
        if (attestations is not None
                and (not isinstance(attestations, Mapping)
                    or set(attestations) != {_CONDITIONS[0]}
                    or not isinstance(attestations.get(_CONDITIONS[0]), Mapping))):
            raise ValueError("durable_learning_v9_exclusion_attestation_required")

        acquisition_by_key = self._existing_outcomes(protocol,
            acquisition_outcomes, phase="acquisition")
        expected_acquisition = {(condition, task_digest)
            for condition in _CONDITIONS
            for task_digest in protocol["acquisition_task_digests"]}
        if set(acquisition_by_key) != expected_acquisition:
            raise ValueError("durable_learning_acquisition_set_incomplete")
        verified_acquisition = list(acquisition_by_key.values())
        verify_durable_learning_acquisition_outcomes(protocol,
            verified_acquisition,
            invocation_receipt_verifier=self._receipt_verifier)

        intents, receipts = self._store.load_consolidation_artifacts(protocol)
        if set(intents) != set(_CONDITIONS) or set(receipts) != set(_CONDITIONS):
            raise ValueError("durable_learning_branch_consolidation_incomplete")
        artifacts = {condition: {"intent": intents[condition],
            "receipt": receipts[condition]} for condition in _CONDITIONS}

        def verify_consolidation(*, protocol: Mapping[str, Any],
                branch: DurableLearningConditionBranch,
                intent: Mapping[str, Any], receipt: Mapping[str, Any]
                ) -> Mapping[str, Any]:
            return self._verify_persisted_consolidation_receipt(
                protocol=protocol, branch=branch, intent=intent, receipt=receipt)

        for condition in _CONDITIONS:
            verified = verify_consolidation(protocol=protocol,
                branch=self._condition_branches[condition],
                intent=intents[condition], receipt=receipts[condition])
            if verified.get("developmental_writeback_performed") is not True:
                raise ValueError("durable_learning_branch_consolidation_writeback_missing")

        existing = self._existing_outcomes(protocol, existing_outcomes,
            phase="delayed_probe")
        expected = {(condition, task_digest) for condition in _CONDITIONS
            for task_digest in protocol["delayed_probe_task_digests"]}
        if not set(existing).issubset(expected):
            raise ValueError("durable_learning_existing_probe_unbound")
        results = dict(existing)
        state_by_condition: dict[str, tuple[str, str]] = {}
        for (condition, _), outcome in results.items():
            signature = (outcome["retained_state_digest"], digest_payload({
                "record_refs": outcome["retained_state_record_refs"]}))
            prior = state_by_condition.setdefault(condition, signature)
            if prior != signature:
                raise ValueError("durable_learning_existing_probe_state_inconsistent")

        available = _CONDITIONS[0]
        projection = receipts[available].get("strategy_projection")
        if not isinstance(projection, Mapping):
            raise ValueError("durable_learning_v9_available_projection_missing")
        audit_request = build_durable_learning_answer_exclusion_audit_request(
            protocol=protocol, condition=available,
            branch=self._condition_branches[available], projection=projection)
        audit_attestation = (dict(attestations[available])
            if attestations is not None else
            self._store.load_answer_exclusion_attestation_for_context(
                protocol=protocol, condition=available,
                branch=self._condition_branches[available], projection=projection,
                audit_request=audit_request))
        self._store.persist_answer_exclusion_attestation(
            protocol=protocol, condition=available,
            branch=self._condition_branches[available], projection=projection,
            audit_request=audit_request, attestation=audit_attestation)

        unresolved = self._store.unresolved_invocation_attempts(protocol,
            phase="delayed_probe", completed_prompt_digests={
                key: outcome["prompt_digest"] for key, outcome in results.items()})
        recover = getattr(self._receipt_verifier,
            "recover_completed_invocation", None)
        if unresolved and not callable(recover):
            raise ValueError("durable_learning_attempt_unresolved")
        for attempt in unresolved:
            condition = attempt["condition"]
            task_digest = attempt["task_digest"]
            branch = self._condition_branches[condition]
            attempt_projection = projection if condition == available else None
            attempt_request = audit_request if condition == available else None
            attempt_attestation = audit_attestation if condition == available else None
            prompt = build_durable_learning_strategy_probe_prompt(
                protocol=protocol, condition=condition,
                task_digest=task_digest, branch=branch,
                projection=attempt_projection, audit_request=attempt_request,
                audit_attestation=attempt_attestation)
            prompt_digest = digest_payload({"prompt": prompt})
            if prompt_digest != attempt["prompt_digest"]:
                raise ValueError("durable_learning_attempt_prompt_mismatch")
            recovered = recover(protocol=dict(protocol), phase="delayed_probe",
                condition=condition, task_digest=task_digest,
                prompt_digest=prompt_digest)
            if recovered is None:
                raise ValueError("durable_learning_attempt_unresolved")
            if (not isinstance(recovered, Mapping)
                    or not isinstance(recovered.get("output"), str)
                    or not isinstance(recovered.get("receipt_id"), str)
                    or not isinstance(recovered.get("receipt_digest"), str)
                    or not isinstance(recovered.get("guard_evidence"), Mapping)
                    or not isinstance(recovered.get("caller_linkage"), Mapping)):
                raise ValueError("durable_learning_recovered_invocation_invalid")
            gate_id = recovered["caller_linkage"].get(
                "durable_learning_probe_gate_id")
            if (not isinstance(gate_id, str)
                    or recovered["guard_evidence"].get("gate_id") != gate_id):
                raise ValueError("durable_learning_recovered_probe_gate_missing")
            gate = self._store.load_strategy_probe_start_gate(
                protocol=protocol, condition=condition, task_digest=task_digest,
                branches=self._condition_branches,
                consolidation_artifacts=artifacts,
                consolidation_artifact_verifier=verify_consolidation,
                acquisition_outcomes=verified_acquisition,
                probe_prompt=prompt, projection=attempt_projection,
                audit_request=attempt_request,
                audit_attestation=attempt_attestation,
                retained_state_snapshot_resolver=(
                    self._snapshot_resolver_for(condition)), gate_id=gate_id)
            if dict(recovered["guard_evidence"]) != gate:
                raise ValueError("durable_learning_recovered_probe_gate_mismatch")
            score, scorer_attestation = self._score(protocol, task_digest,
                "delayed_probe", recovered["output"])
            outcome = make_durable_learning_outcome(protocol=protocol,
                phase="delayed_probe", condition=condition,
                task_digest=task_digest, prompt_digest=prompt_digest,
                invocation_attempt_id=attempt["attempt_id"],
                invocation_receipt_id=recovered["receipt_id"],
                invocation_receipt_digest=recovered["receipt_digest"],
                invocation_receipt_verifier=self._receipt_verifier,
                score=score, scorer_attestation=scorer_attestation,
                probe_start_gate=gate,
                retained_state_digest=gate["retained_state_digest"],
                available_experience_digests=[],
                preceding_feedback_digests=[], output=recovered["output"],
                outcome_reconstruction_posture="reconstructed_from_stored_receipt")
            self._store.persist_outcome(protocol, outcome)
            results[(condition, task_digest)] = outcome

        self._store.verify_no_unresolved_attempts(protocol,
            phase="delayed_probe", completed_prompt_digests={
                key: outcome["prompt_digest"] for key, outcome in results.items()})

        for task_digest in protocol["delayed_probe_task_digests"]:
            order = protocol["condition_contract"][
                "delayed_probe_order_by_task"][task_digest]
            for condition in order:
                key = (condition, task_digest)
                if key in results:
                    continue
                branch = self._condition_branches[condition]
                branch_projection = projection if condition == available else None
                branch_audit_request = audit_request if condition == available else None
                branch_attestation = audit_attestation if condition == available else None
                prompt = build_durable_learning_strategy_probe_prompt(
                    protocol=protocol, condition=condition,
                    task_digest=task_digest, branch=branch,
                    projection=branch_projection,
                    audit_request=branch_audit_request,
                    audit_attestation=branch_attestation)

                def persist_gate(gate: Mapping[str, Any], *,
                        gate_condition: str = condition,
                        gate_task_digest: str = task_digest,
                        gate_prompt: str = prompt,
                        gate_projection: Mapping[str, Any] | None = branch_projection,
                        gate_audit_request: Mapping[str, Any] | None = branch_audit_request,
                        gate_attestation: Mapping[str, Any] | None = branch_attestation
                        ) -> str:
                    signature = (gate["retained_state_digest"], digest_payload({
                        "record_refs": gate["retained_state_record_refs"]}))
                    prior = state_by_condition.setdefault(gate_condition, signature)
                    if prior != signature:
                        raise ValueError("durable_learning_probe_state_changed_before_effect")
                    self._store.persist_strategy_probe_start_gate(
                        protocol=protocol, condition=gate_condition,
                        task_digest=gate_task_digest, branches=self._condition_branches,
                        consolidation_artifacts=artifacts,
                        consolidation_artifact_verifier=verify_consolidation,
                        acquisition_outcomes=verified_acquisition,
                        probe_prompt=gate_prompt, projection=gate_projection,
                        audit_request=gate_audit_request,
                        audit_attestation=gate_attestation,
                        retained_state_snapshot_resolver=(
                            self._snapshot_resolver_for(gate_condition)), gate=gate)
                    return self._store.begin_invocation_attempt(protocol,
                        phase="delayed_probe", condition=gate_condition,
                        task_digest=gate_task_digest,
                        prompt_digest=gate["probe_prompt_digest"])

                guard = DurableLearningStrategyProbeStartGuard(
                    protocol=protocol, condition=condition,
                    task_digest=task_digest, branches=self._condition_branches,
                    consolidation_artifacts=artifacts,
                    consolidation_artifact_verifier=verify_consolidation,
                    acquisition_outcomes=verified_acquisition,
                    probe_prompt=prompt, projection=branch_projection,
                    audit_request=branch_audit_request,
                    audit_attestation=branch_attestation,
                    retained_state_snapshot_resolver=(
                        self._snapshot_resolver_for(condition)),
                    invocation_receipt_verifier=self._receipt_verifier,
                    on_gate_opened=persist_gate)
                invocation = self._invoke(protocol=protocol,
                    phase="delayed_probe", condition=condition,
                    task_digest=task_digest, prompt=prompt,
                    pre_effect_guard=guard,
                    caller_linkage={"durable_learning_probe_gate_id": guard.gate_id})
                gate = guard.gate_receipt
                if not isinstance(gate, Mapping):
                    raise ValueError("durable_learning_probe_gate_not_opened")
                score, scorer_attestation = self._score(protocol, task_digest,
                    "delayed_probe", invocation["output"])
                outcome = make_durable_learning_outcome(protocol=protocol,
                    phase="delayed_probe", condition=condition,
                    task_digest=task_digest, prompt_digest=guard.prompt_digest,
                    invocation_attempt_id=guard.invocation_attempt_id,
                    invocation_receipt_id=invocation["invocation_receipt_id"],
                    invocation_receipt_digest=invocation[
                        "invocation_receipt_digest"],
                    invocation_receipt_verifier=self._receipt_verifier,
                    score=score, scorer_attestation=scorer_attestation,
                    probe_start_gate=gate,
                    retained_state_digest=gate["retained_state_digest"],
                    available_experience_digests=[],
                    preceding_feedback_digests=[], output=invocation["output"])
                self._store.persist_outcome(protocol, outcome)
                results[key] = outcome

        if set(results) != expected:
            raise ValueError("durable_learning_probe_set_incomplete")
        verify_durable_learning_outcome_set(protocol,
            [*verified_acquisition, *results.values()],
            invocation_receipt_verifier=self._receipt_verifier,
            retained_update_attribution_verifier=(
                self._store._retained_update_attribution_verifier),
            competence_authorization_receipts=(
                self._store.load_v11_competence_authorization_receipts(
                    protocol=protocol)
                if protocol.get("schema_version") == _PROTOCOL_SCHEMA_V11
                else None))
        return [dict(results[key]) for key in sorted(results)]

    def finalize(self, *, protocol: Mapping[str, Any],
            outcomes: Sequence[Mapping[str, Any]] = ()) -> str:
        """Finalize from stored evidence, checking any caller copies exactly."""
        self._verify_protocol_is_persisted(protocol)
        if not isinstance(outcomes, Sequence) or isinstance(outcomes,
                (str, bytes)):
            raise ValueError("durable_learning_existing_outcomes_invalid")
        persisted = [*self._store.load_outcomes(protocol, phase="acquisition"),
            *self._store.load_outcomes(protocol, phase="delayed_probe")]
        by_id = {row["outcome_id"]: row for row in persisted}
        if len(by_id) != len(persisted):
            raise ValueError("durable_learning_evaluation_outcome_duplicate")
        seen: set[str] = set()
        for outcome in outcomes:
            if not isinstance(outcome, Mapping):
                raise ValueError("durable_learning_existing_outcome_invalid")
            outcome_id = outcome.get("outcome_id")
            stored = by_id.get(outcome_id)
            if (stored is None or outcome_id in seen
                    or stored != dict(outcome)):
                raise ValueError("durable_learning_existing_outcome_not_persisted")
            seen.add(outcome_id)
        if protocol.get("schema_version") in _V10_PROTOCOL_SCHEMAS:
            self._verify_v9_finalization_evidence(protocol=protocol,
                outcomes=persisted)
        if protocol.get("schema_version") == _PROTOCOL_SCHEMA_V11:
            competence = self._store.load_withheld_acquisition_competence_assessment(
                protocol=protocol)
            if competence.get("qualified") is not True:
                raise ValueError(
                    "durable_learning_baseline_competence_not_demonstrated:" +
                    str(competence.get("assessment_id")))
        return self._store.persist_evaluation(protocol, persisted)

    def _verify_v9_finalization_evidence(self, *,
            protocol: Mapping[str, Any],
            outcomes: Sequence[Mapping[str, Any]]) -> None:
        """Revalidate stored auditor signature and rendered prompts at finalize."""
        self._verify_condition_branch_bindings(protocol, baseline=False)
        branch_preflight = self._store.load_condition_branch_preflight(protocol)
        if self._condition_branches is None:
            raise ValueError("durable_learning_condition_branches_required")
        delayed = [row for row in outcomes if row.get("phase") == "delayed_probe"]
        available = _CONDITIONS[0]
        available_rows = [row for row in delayed
            if row.get("condition") == available]
        if not available_rows:
            raise ValueError("durable_learning_v9_finalization_probes_missing")
        gate_digests = {row.get("probe_start_gate", {}).get(
            "audit_attestation_digest") for row in available_rows
            if isinstance(row.get("probe_start_gate"), Mapping)}
        if len(gate_digests) != 1:
            raise ValueError("durable_learning_v9_finalization_audit_binding_invalid")
        attestation_digest = next(iter(gate_digests))
        if not isinstance(attestation_digest, str):
            raise ValueError("durable_learning_v9_finalization_audit_missing")

        intents, receipts = self._store.load_consolidation_artifacts(protocol)
        if set(intents) != set(_CONDITIONS) or set(receipts) != set(_CONDITIONS):
            raise ValueError("durable_learning_branch_consolidation_incomplete")
        expected_receipt_refs = []
        for condition in _CONDITIONS:
            verified = self._verify_persisted_consolidation_receipt(
                protocol=protocol, branch=self._condition_branches[condition],
                intent=intents[condition], receipt=receipts[condition])
            if verified.get("developmental_writeback_performed") is not True:
                raise ValueError("durable_learning_branch_consolidation_writeback_missing")
            receipt_projection = receipts[condition].get("strategy_projection")
            projection_digest = (receipt_projection.get("projection_digest")
                if isinstance(receipt_projection, Mapping) else None)
            expected_receipt_refs.append({"condition": condition,
                "branch_id": self._condition_branches[condition].branch_id,
                "intent_id": intents[condition]["intent_id"],
                "intent_digest": intents[condition]["intent_digest"],
                "receipt_id": receipts[condition]["receipt_id"],
                "receipt_digest": receipts[condition]["receipt_digest"],
                "strategy_projection_digest": projection_digest})
        projection = receipts[available].get("strategy_projection")
        if not isinstance(projection, Mapping):
            raise ValueError("durable_learning_v9_available_projection_missing")
        audit_request = build_durable_learning_answer_exclusion_audit_request(
            protocol=protocol, condition=available,
            branch=self._condition_branches[available], projection=projection)
        attestation = self._store.load_answer_exclusion_attestation(
            protocol=protocol, condition=available,
            branch=self._condition_branches[available], projection=projection,
            audit_request=audit_request, attestation_digest=attestation_digest)

        for outcome in delayed:
            condition = outcome.get("condition")
            task_digest = outcome.get("task_digest")
            if condition not in _CONDITIONS or not isinstance(task_digest, str):
                raise ValueError("durable_learning_v9_finalization_probe_invalid")
            branch = self._condition_branches[condition]
            gate = outcome.get("probe_start_gate")
            if not isinstance(gate, Mapping):
                raise ValueError("durable_learning_v9_finalization_gate_missing")
            task_projection = projection if condition == available else None
            task_request = audit_request if condition == available else None
            task_attestation = attestation if condition == available else None
            prompt = build_durable_learning_strategy_probe_prompt(
                protocol=protocol, condition=condition,
                task_digest=task_digest, branch=branch,
                projection=task_projection, audit_request=task_request,
                audit_attestation=task_attestation)
            if (digest_payload({"prompt": prompt}) != outcome.get("prompt_digest")
                    or gate.get("probe_prompt_digest") !=
                        outcome.get("prompt_digest")
                    or gate.get("consolidation_receipt_refs") !=
                        expected_receipt_refs
                    or gate.get("audit_attestation_digest") != (
                        digest_payload(attestation) if condition == available
                        else None)
                    or gate.get("schema_version") !=
                        "sentientos.durable_learning_strategy_probe_start_gate:v4"
                    or gate.get("branch_preflight_id") !=
                        branch_preflight.get("preflight_id")
                    or gate.get("branch_preflight_digest") !=
                        branch_preflight.get("preflight_digest")
                    or gate.get("projection_digest") != (
                        projection.get("projection_digest")
                        if condition == available else None)):
                raise ValueError("durable_learning_v9_finalization_prompt_mismatch")


class ProductionServingDurableLearningExecutor:
    """Adapt the frozen runner to the existing governed serving controller.

    The context resolver must create or select a persisted user turn and
    provide its caller linkage, a unique correlation ID, and a response
    recorder. The recorder must persist the assistant turn against the exact
    invocation receipt and return that linkage. This adapter creates no
    session and performs no work until the runner invokes it.
    """

    def __init__(self, *, serving_inference_controller: Any,
            invocation_context_resolver: Callable[..., Mapping[str, Any]]) -> None:
        if (not callable(getattr(serving_inference_controller, "generate", None))
                or not callable(getattr(serving_inference_controller,
                    "verify_stored_chat_invocation", None))
                or not callable(invocation_context_resolver)):
            raise ValueError("durable_learning_serving_executor_dependencies_invalid")
        self._serving = serving_inference_controller
        self._context_resolver = invocation_context_resolver
        self._identity_lock = threading.Lock()
        self._used_turns: set[tuple[str, str]] = set()
        self._used_correlations: set[str] = set()

    def __call__(self, *, protocol: Mapping[str, Any], phase: str,
            condition: str, task_digest: str, prompt: str,
            pre_effect_guard: Callable[[], Mapping[str, Any]],
            caller_linkage: Mapping[str, Any]) -> dict[str, Any]:
        prepare = getattr(self._context_resolver, "prepare_serving_turn", None)
        preparation = None
        if callable(prepare):
            session_id_for_condition = getattr(self._context_resolver,
                "session_id_for_condition", None)
            expected_session_id = (session_id_for_condition(condition)
                if callable(session_id_for_condition) else
                getattr(self._context_resolver, "session_id", None))
            if not isinstance(expected_session_id, str) or not expected_session_id:
                raise ValueError(
                    "durable_learning_serving_context_session_binding_invalid")
            preparation = verify_durable_learning_serving_turn_preparation(
                prepare(protocol=dict(protocol), phase=phase,
                    condition=condition, task_digest=task_digest,
                    prompt=prompt),
                protocol_id=protocol.get("protocol_id"), phase=phase,
                condition=condition, task_digest=task_digest,
                session_id=expected_session_id)
        context = self._context_resolver(protocol=dict(protocol), phase=phase,
            condition=condition, task_digest=task_digest, prompt=prompt)
        required = {"caller", "correlation_id", "caller_linkage",
            "user_turn", "response_recorder"}
        optional = {"budget", "resource_context"}
        if (not isinstance(context, Mapping)
                or not required.issubset(context)
                or set(context) - required - optional
                or context.get("caller") != "chat_service"
                or not isinstance(context.get("correlation_id"), str)
                or not context["correlation_id"]
                or not isinstance(context.get("caller_linkage"), Mapping)
                or not callable(context.get("response_recorder"))):
            raise ValueError("durable_learning_serving_context_invalid")
        linkage = dict(context["caller_linkage"])
        session_id = linkage.get("session_id")
        user_turn_id = linkage.get("user_turn_id")
        user_turn = context.get("user_turn")
        if (not isinstance(session_id, str) or not session_id
                or not isinstance(user_turn_id, str)
                or re.fullmatch(r"turn-[0-9a-f]{24}", user_turn_id) is None
                or not isinstance(user_turn, Mapping)
                or user_turn.get("role") != "user"
                or user_turn.get("turn_id") != user_turn_id
                or user_turn.get("text") != prompt
                or user_turn.get("text_digest") != hashlib.sha256(
                    json.dumps({"text": prompt}, sort_keys=True,
                        separators=(",", ":"), ensure_ascii=False).encode(
                            "utf-8")).hexdigest()):
            raise ValueError("durable_learning_serving_user_turn_linkage_invalid")
        if context["correlation_id"] != f"chat:{session_id}:{user_turn_id}":
            raise ValueError("durable_learning_serving_correlation_binding_invalid")
        if (preparation is not None
                and (preparation.get("session_id") != session_id
                    or preparation.get("user_turn_id") != user_turn_id
                    or preparation.get("prompt") != user_turn.get("text")
                    or preparation.get("prompt_digest") !=
                        user_turn.get("text_digest")
                    or preparation.get("correlation_id") !=
                        context["correlation_id"]
                    or preparation.get("caller_linkage") != linkage)):
            raise ValueError(
                "durable_learning_serving_preparation_context_mismatch")
        if set(linkage).intersection(caller_linkage):
            raise ValueError("durable_learning_serving_linkage_collision")
        linkage.update(caller_linkage)
        turn_key = (session_id, user_turn_id)
        with self._identity_lock:
            if (turn_key in self._used_turns
                    or context["correlation_id"] in self._used_correlations):
                raise ValueError("durable_learning_serving_invocation_identity_reused")
            self._used_turns.add(turn_key)
            self._used_correlations.add(context["correlation_id"])
        receipt = self._serving.generate(prompt=prompt,
            caller=context["caller"], correlation_id=context["correlation_id"],
            budget=context.get("budget"), caller_linkage=linkage,
            resource_context=context.get("resource_context"),
            pre_effect_guard=pre_effect_guard)
        if (getattr(receipt, "status", None) != "admitted_completed"
                or not isinstance(getattr(receipt, "output_text", None), str)
                or not receipt.output_text
                or getattr(receipt, "output_truncated", True)
                or getattr(receipt, "fallback_occurred", True)):
            raise ValueError("durable_learning_serving_receipt_incomplete")
        client_request_id_digest = linkage.get("client_request_id_digest")
        if (not isinstance(client_request_id_digest, str)
                or re.fullmatch(r"[0-9a-f]{64}",
                    client_request_id_digest) is None):
            raise ValueError("durable_learning_serving_request_identity_invalid")
        verified_receipt = self._serving.verify_stored_chat_invocation(
            receipt_id=receipt.receipt_id,
            receipt_digest=receipt.receipt_digest,
            session_id=session_id, user_turn_id=user_turn_id,
            assistant_text=receipt.output_text,
            client_request_id_digest=client_request_id_digest)
        verified_caller = (verified_receipt.get("caller_linkage")
            if isinstance(verified_receipt, Mapping) else None)
        verified_request_linkage = (verified_receipt.get("request_linkage")
            if isinstance(verified_receipt, Mapping) else None)
        verified_output_lineage = (verified_receipt.get(
            "assistant_output_lineage") if isinstance(verified_receipt, Mapping)
            else None)
        if (not isinstance(verified_receipt, Mapping)
                or verified_receipt.get("receipt_id") != receipt.receipt_id
                or verified_receipt.get("receipt_digest") != receipt.receipt_digest
                or verified_receipt.get("status") != "admitted_completed"
                or verified_receipt.get("prompt_digest") !=
                    digest_payload({"prompt": prompt})
                or verified_receipt.get("output_digest") != receipt.output_digest
                or verified_receipt.get("output_truncated") is not False
                or verified_receipt.get("fallback_occurred") is not False
                or not isinstance(verified_caller, Mapping)
                or verified_caller.get("session_id") != session_id
                or verified_caller.get("user_turn_id") != user_turn_id
                or verified_caller.get("client_request_id_digest") !=
                    client_request_id_digest
                or not isinstance(verified_request_linkage, Mapping)
                or any(verified_request_linkage.get(key) != value
                    for key, value in linkage.items())
                or not isinstance(verified_output_lineage, Mapping)
                or verified_output_lineage.get("status") !=
                    "exact_invocation_output_match"
                or verified_output_lineage.get("invocation_output_digest") !=
                    receipt.output_digest
                or verified_output_lineage.get("transcript_text_digest") !=
                    digest_payload({"text": receipt.output_text})):
            raise ValueError("durable_learning_serving_stored_receipt_binding_invalid")
        recorded = context["response_recorder"](session_id=session_id,
            user_turn_id=user_turn_id, receipt=receipt)
        assistant_turn = (recorded.get("assistant_turn")
            if isinstance(recorded, Mapping) else None)
        assistant_linkage = (assistant_turn.get("linkage")
            if isinstance(assistant_turn, Mapping) else None)
        if (not isinstance(recorded, Mapping)
                or set(recorded) != {"session_id", "user_turn_id",
                    "invocation_receipt_id", "invocation_receipt_digest",
                    "assistant_turn_persisted", "assistant_turn"}
                or recorded.get("session_id") != session_id
                or recorded.get("user_turn_id") != user_turn_id
                or recorded.get("invocation_receipt_id") != receipt.receipt_id
                or recorded.get("invocation_receipt_digest") !=
                    receipt.receipt_digest
                or recorded.get("assistant_turn_persisted") is not True
                or not isinstance(assistant_turn, Mapping)
                or assistant_turn.get("role") != "assistant"
                or not isinstance(assistant_turn.get("turn_id"), str)
                or not isinstance(assistant_turn.get("text"), str)
                or assistant_turn.get("text") != receipt.output_text
                or assistant_turn.get("text_digest") != digest_payload({
                    "text": receipt.output_text})
                or not isinstance(assistant_linkage, Mapping)
                or assistant_linkage.get("source_user_turn_id") != user_turn_id
                or assistant_linkage.get("request_id") !=
                    verified_receipt.get("request_id")
                or assistant_linkage.get("invocation_receipt_id") != receipt.receipt_id
                or assistant_linkage.get("invocation_receipt_digest") !=
                    receipt.receipt_digest
                or assistant_linkage.get("loaded_model_identity") !=
                    verified_receipt.get("loaded_model_identity")
                or assistant_linkage.get("active_model_identity") !=
                    verified_receipt.get("loaded_model_identity")
                or assistant_linkage.get("loaded_model_identity_digest") !=
                    digest_payload(verified_receipt.get(
                        "loaded_model_identity", {}))
                or assistant_linkage.get("active_model_identity_digest") !=
                    digest_payload(verified_receipt.get(
                        "loaded_model_identity", {}))
                or assistant_linkage.get("assistant_output_lineage") !=
                    verified_output_lineage
                or assistant_linkage.get("durable_learning_protocol_id") !=
                    protocol.get("protocol_id")
                or assistant_linkage.get("durable_learning_phase") != phase
                or assistant_linkage.get("durable_learning_condition") != condition
                or assistant_linkage.get("durable_learning_task_digest") !=
                    task_digest):
            raise ValueError("durable_learning_serving_transcript_commit_invalid")
        return {"output": receipt.output_text,
            "invocation_receipt_id": receipt.receipt_id,
            "invocation_receipt_digest": receipt.receipt_digest}


class ConversationSessionDurableLearningContext:
    """Create idempotent transcript turns for a frozen Phase C invocation."""

    def __init__(self, *, conversation_session_store: Any,
            session_id: str) -> None:
        if (not callable(getattr(conversation_session_store, "load", None))
                or not callable(getattr(conversation_session_store,
                    "append_user_request", None))
                or not callable(getattr(conversation_session_store,
                    "append_turn_once", None))
                or not isinstance(session_id, str) or not session_id):
            raise ValueError("durable_learning_conversation_context_invalid")
        session = conversation_session_store.load(session_id)
        if (not isinstance(session, Mapping)
                or session.get("session_id") != session_id
                or session.get("lifecycle_state") != "active"):
            raise ValueError("durable_learning_conversation_session_invalid")
        self._sessions = conversation_session_store
        self._session_id = session_id
        self._context_lock = threading.Lock()
        self._turn_contexts: dict[tuple[str, str, str, str], dict[str, str]] = {}

    @property
    def conversation_session_store(self) -> Any:
        return self._sessions

    @property
    def session_id(self) -> str:
        return self._session_id

    def __call__(self, *, protocol: Mapping[str, Any], phase: str,
            condition: str, task_digest: str, prompt: str
            ) -> dict[str, Any]:
        task_key = ("acquisition_task_digests" if phase == "acquisition"
            else "delayed_probe_task_digests" if phase == "delayed_probe" else None)
        if (task_key is None or condition not in _CONDITIONS
                or task_digest not in protocol.get(task_key, ())
                or not isinstance(prompt, str) or not prompt):
            raise ValueError("durable_learning_conversation_turn_invalid")
        session = self._sessions.load(self._session_id)
        if (not isinstance(session, Mapping)
                or session.get("session_id") != self._session_id
                or session.get("lifecycle_state") != "active"):
            raise ValueError("durable_learning_conversation_session_invalid")
        request_identity = {"protocol_id": protocol["protocol_id"],
            "phase": phase, "condition": condition, "task_digest": task_digest}
        request_id = "durable-learning:" + digest_payload(request_identity)[:40]
        user_turn, _created = self._sessions.append_user_request(
            self._session_id, request_id=request_id, text=prompt, retain=False)
        user_turn_id = user_turn.get("turn_id")
        request_digest = user_turn.get("linkage", {}).get(
            "client_request_id_digest") if isinstance(
                user_turn.get("linkage"), Mapping) else None
        if (not isinstance(user_turn_id, str)
                or re.fullmatch(r"turn-[0-9a-f]{24}", user_turn_id) is None
                or user_turn.get("text") != prompt
                or not isinstance(request_digest, str)
                or re.fullmatch(r"[0-9a-f]{64}", request_digest) is None):
            raise ValueError("durable_learning_conversation_user_turn_invalid")
        context_key = (protocol["protocol_id"], phase, condition, task_digest)
        receipt_context = {"session_id": self._session_id,
            "user_turn_id": user_turn_id,
            "client_request_id_digest": request_digest,
            "conversation_session_store": self._sessions}
        with self._context_lock:
            previous = self._turn_contexts.get(context_key)
            if previous is not None and previous != receipt_context:
                raise ValueError("durable_learning_conversation_context_changed")
            self._turn_contexts[context_key] = receipt_context
        linkage = {"session_id": self._session_id,
            "user_turn_id": user_turn_id,
            "client_request_id_digest": request_digest,
            "chat_response_style": "default"}
        experiment_binding = {"protocol_id": protocol["protocol_id"],
            "phase": phase, "condition": condition,
            "task_digest": task_digest}
        return {"caller": "chat_service",
            "correlation_id": f"chat:{self._session_id}:{user_turn_id}",
            "caller_linkage": linkage,
            "client_request_id_digest": request_digest,
            "user_turn": user_turn,
            "response_recorder": lambda *, session_id, user_turn_id, receipt:
                self._record_response(session_id=session_id,
                    user_turn_id=user_turn_id, receipt=receipt,
                    protocol_id=experiment_binding["protocol_id"],
                    phase=experiment_binding["phase"],
                    condition=experiment_binding["condition"],
                    task_digest=experiment_binding["task_digest"])}

    def prepare_serving_turn(self, *, protocol: Mapping[str, Any], phase: str,
            condition: str, task_digest: str, prompt: str) -> dict[str, Any]:
        """Persist and expose the exact turn envelope for a separate broker.

        This operation only creates the idempotent user turn. It does not
        invoke a model or commit a response; callers must preserve that split
        when moving the serving broker outside the branch-owning process.
        """
        context = self(protocol=protocol, phase=phase, condition=condition,
            task_digest=task_digest, prompt=prompt)
        user_turn = context["user_turn"]
        if (not isinstance(user_turn, Mapping)
                or not isinstance(context.get("caller_linkage"), Mapping)):
            raise ValueError("durable_learning_serving_turn_preparation_invalid")
        semantic = {"schema_version":
                "sentientos.durable_learning_serving_turn_preparation:v1",
            "protocol_id": protocol.get("protocol_id"),
            "phase": phase, "condition": condition,
            "task_digest": task_digest,
            "session_id": self._session_id,
            "user_turn_id": user_turn.get("turn_id"),
            "prompt": user_turn.get("text"),
            "prompt_digest": user_turn.get("text_digest"),
            "client_request_id_digest": context.get(
                "client_request_id_digest"),
            "correlation_id": context.get("correlation_id"),
            "caller_linkage": dict(context["caller_linkage"]),
            "model_invocation_performed": False,
            "response_committed": False,
            "authority": False}
        if (semantic["prompt"] != prompt
                or semantic["user_turn_id"] != user_turn.get("turn_id")
                or semantic["correlation_id"] != (
                    f"chat:{self._session_id}:{semantic['user_turn_id']}")):
            raise ValueError("durable_learning_serving_turn_preparation_invalid")
        preparation = {**semantic,
            "preparation_digest": digest_payload(semantic)}
        return verify_durable_learning_serving_turn_preparation(
            preparation, protocol_id=protocol.get("protocol_id"),
            phase=phase, condition=condition, task_digest=task_digest,
            session_id=self._session_id)


    def receipt_context(self, *, protocol: Mapping[str, Any], phase: str,
            condition: str, task_digest: str) -> dict[str, Any]:
        """Resolve the persisted turn created for a task's serving call."""
        key = (protocol.get("protocol_id"), phase, condition, task_digest)
        with self._context_lock:
            context = self._turn_contexts.get(key)
            if context is not None:
                return dict(context)
        if (not isinstance(key[0], str) or phase not in {
                "acquisition", "delayed_probe"} or condition not in _CONDITIONS
                or not isinstance(task_digest, str)):
            raise ValueError("durable_learning_receipt_context_not_found")
        request_id = "durable-learning:" + digest_payload({
            "protocol_id": key[0], "phase": phase, "condition": condition,
            "task_digest": task_digest})[:40]
        request_digest = digest_payload({"client_request_id": request_id})
        session = self._sessions.load(self._session_id)
        turns = session.get("turns") if isinstance(session, Mapping) else None
        matches = [turn for turn in turns if isinstance(turn, Mapping)
            and turn.get("role") == "user"
            and isinstance(turn.get("linkage"), Mapping)
            and turn["linkage"].get("client_request_id_digest") == request_digest]
        if len(matches) != 1:
            raise ValueError("durable_learning_receipt_context_not_found")
        recovered = {"session_id": self._session_id,
            "user_turn_id": matches[0]["turn_id"],
            "client_request_id_digest": request_digest,
            "conversation_session_store": self._sessions}
        with self._context_lock:
            self._turn_contexts[key] = recovered
        return recovered

    def _record_response(self, *, session_id: str, user_turn_id: str,
            receipt: Any, protocol_id: str, phase: str, condition: str,
            task_digest: str) -> dict[str, Any]:
        if (session_id != self._session_id
                or not isinstance(protocol_id, str)
                or re.fullmatch(re.escape(PROTOCOL_ID_PREFIX) +
                    r"[0-9a-f]{24}", protocol_id) is None
                or phase not in {"acquisition", "delayed_probe"}
                or condition not in _CONDITIONS
                or not isinstance(task_digest, str)
                or re.fullmatch(r"sha256:[0-9a-f]{64}", task_digest) is None
                or not isinstance(receipt, LocalModelInvocationReceipt)
                or receipt.status != "admitted_completed"
                or not isinstance(receipt.output_text, str)
                or not receipt.output_text
                or receipt.output_truncated or receipt.fallback_occurred
                or receipt.effects.get("local_model_inference") is not True):
            raise ValueError("durable_learning_conversation_response_invalid")
        request = receipt.request
        identity = request.get("active_model_identity")
        if (not isinstance(identity, Mapping) or not identity
                or not isinstance(request.get("request_id"), str)):
            raise ValueError("durable_learning_conversation_invocation_invalid")
        output_lineage = {"status": "exact_invocation_output_match",
            "invocation_output_digest": receipt.output_digest,
            "transcript_text_digest": digest_payload({
                "text": receipt.output_text}),
            "invocation_output_text_sha256": hashlib.sha256(
                receipt.output_text.encode("utf-8")).hexdigest(),
            "transcript_text_sha256": hashlib.sha256(
                receipt.output_text.encode("utf-8")).hexdigest(),
            "output_truncated": False}
        assistant_linkage = {"request_id": request["request_id"],
                "invocation_receipt_id": receipt.receipt_id,
                "invocation_receipt_digest": receipt.receipt_digest,
                "source_user_turn_id": user_turn_id,
                "durable_learning_protocol_id": protocol_id,
                "durable_learning_phase": phase,
                "durable_learning_condition": condition,
                "durable_learning_task_digest": task_digest,
                "active_model_identity": dict(identity),
                "active_model_identity_digest": digest_payload(dict(identity)),
                "loaded_model_identity": dict(identity),
                "loaded_model_identity_digest": digest_payload(dict(identity)),
                "assistant_output_lineage": output_lineage,
                "response_origin": "model_generated"}
        # A process can stop after the transcript write succeeds but before
        # the caller records the outcome. Recover that exact commit on retry;
        # never append a second assistant turn for the same invocation receipt.
        try:
            assistant, _created = self._sessions.append_turn_once(
                self._session_id, role="assistant", text=receipt.output_text,
                linkage=assistant_linkage,
                identity_field="invocation_receipt_id",
                identity_value=receipt.receipt_id)
        except ValueError as exc:
            if getattr(exc, "args", [None])[0] in {
                    "turn_idempotency_identity_conflict"}:
                raise ValueError(
                    "durable_learning_conversation_response_conflict") from exc
            raise
        return {"session_id": self._session_id,
            "user_turn_id": user_turn_id,
            "invocation_receipt_id": receipt.receipt_id,
            "invocation_receipt_digest": receipt.receipt_digest,
            "assistant_turn_persisted": True,
            "assistant_turn": assistant}


def verify_durable_learning_serving_turn_preparation(value: Any, *,
        protocol_id: str, phase: str, condition: str, task_digest: str,
        session_id: str) -> dict[str, Any]:
    """Check a prepared turn before a separate serving broker uses its prompt.

    This validates content and caller correlation only. It does not
    authenticate the worker, process, or IPC channel that supplied the object.
    """
    fields = {"schema_version", "protocol_id", "phase", "condition",
        "task_digest", "session_id", "user_turn_id", "prompt",
        "prompt_digest", "client_request_id_digest", "correlation_id",
        "caller_linkage", "model_invocation_performed",
        "response_committed", "authority", "preparation_digest"}
    turn_id = value.get("user_turn_id") if isinstance(value, Mapping) else None
    linkage = value.get("caller_linkage") if isinstance(value, Mapping) else None
    prompt = value.get("prompt") if isinstance(value, Mapping) else None
    semantic = ({key: item for key, item in value.items()
        if key != "preparation_digest"} if isinstance(value, Mapping) else {})
    if (not isinstance(value, Mapping) or set(value) != fields
            or value.get("schema_version") !=
                "sentientos.durable_learning_serving_turn_preparation:v1"
            or value.get("protocol_id") != protocol_id
            or not isinstance(protocol_id, str)
            or re.fullmatch(re.escape(PROTOCOL_ID_PREFIX) +
                r"[0-9a-f]{24}", protocol_id) is None
            or value.get("phase") != phase
            or phase not in {"acquisition", "delayed_probe"}
            or value.get("condition") != condition
            or condition not in _CONDITIONS
            or value.get("task_digest") != task_digest
            or not isinstance(task_digest, str)
            or re.fullmatch(r"sha256:[0-9a-f]{64}", task_digest) is None
            or value.get("session_id") != session_id
            or not isinstance(session_id, str)
            or re.fullmatch(r"session-[0-9a-f]{24}", session_id) is None
            or not isinstance(turn_id, str)
            or re.fullmatch(r"turn-[0-9a-f]{24}", turn_id) is None
            or not isinstance(prompt, str) or not prompt
            or len(prompt.encode("utf-8")) > 64 * 1024
            or value.get("prompt_digest") != digest_payload({"text": prompt})
            or not isinstance(value.get("client_request_id_digest"), str)
            or re.fullmatch(r"[0-9a-f]{64}", value[
                "client_request_id_digest"]) is None
            or value.get("correlation_id") != f"chat:{session_id}:{turn_id}"
            or not isinstance(linkage, Mapping)
            or set(linkage) != {"session_id", "user_turn_id",
                "client_request_id_digest", "chat_response_style"}
            or linkage.get("session_id") != session_id
            or linkage.get("user_turn_id") != turn_id
            or linkage.get("client_request_id_digest") != value.get(
                "client_request_id_digest")
            or linkage.get("chat_response_style") != "default"
            or value.get("model_invocation_performed") is not False
            or value.get("response_committed") is not False
            or value.get("authority") is not False
            or value.get("preparation_digest") != digest_payload(semantic)):
        raise ValueError("durable_learning_serving_turn_preparation_invalid")
    return dict(value)


class ConditionRoutedDurableLearningContext:
    """Route each frozen condition to its own transcript context."""

    def __init__(self, *, contexts: Mapping[str,
            ConversationSessionDurableLearningContext],
            branch_ids: Mapping[str, str]) -> None:
        if (not isinstance(contexts, Mapping)
                or set(contexts) != set(_CONDITIONS)
                or any(not isinstance(context,
                    ConversationSessionDurableLearningContext)
                    for context in contexts.values())
                or not isinstance(branch_ids, Mapping)
                or set(branch_ids) != set(_CONDITIONS)
                or any(not isinstance(branch_id, str) or not branch_id
                    for branch_id in branch_ids.values())
                or len({context.session_id for context in contexts.values()})
                    != len(_CONDITIONS)):
            raise ValueError("durable_learning_condition_contexts_invalid")
        self._contexts = dict(contexts)
        self._branch_ids = dict(branch_ids)

    def _context_for(self, protocol: Mapping[str, Any],
            condition: str) -> ConversationSessionDurableLearningContext:
        protocol_ids = verify_durable_learning_protocol(protocol).get(
            "condition_branch_ids")
        if (protocol.get("schema_version") not in _BRANCH_PROTOCOL_SCHEMAS
                or not isinstance(protocol_ids, Mapping)
                or condition not in _CONDITIONS
                or protocol_ids.get(condition) != self._branch_ids.get(condition)):
            raise ValueError("durable_learning_condition_context_branch_mismatch")
        return self._contexts[condition]

    def session_id_for_condition(self, condition: str) -> str | None:
        """Expose the bound session identity without exposing its store."""
        context = self._contexts.get(condition)
        return context.session_id if context is not None else None

    def prepare_serving_turn(self, *, protocol: Mapping[str, Any], phase: str,
            condition: str, task_digest: str, prompt: str) -> dict[str, Any]:
        """Prepare one idempotent turn inside its condition-owned session."""
        return self._context_for(protocol, condition).prepare_serving_turn(
            protocol=protocol, phase=phase, condition=condition,
            task_digest=task_digest, prompt=prompt)

    def __call__(self, *, protocol: Mapping[str, Any], phase: str,
            condition: str, task_digest: str, prompt: str) -> Mapping[str, Any]:
        return self._context_for(protocol, condition)(protocol=protocol,
            phase=phase, condition=condition, task_digest=task_digest,
            prompt=prompt)

    def receipt_context(self, *, protocol: Mapping[str, Any], phase: str,
            condition: str, task_digest: str) -> Mapping[str, Any]:
        return self._context_for(protocol, condition).receipt_context(
            protocol=protocol, phase=phase, condition=condition,
            task_digest=task_digest)


@dataclass(frozen=True)
class ProductionDurableLearningRuntime:
    """Wired production components; constructing this object performs no call."""

    conversation_context: ConversationSessionDurableLearningContext
    receipt_verifier: LocalModelDurableLearningReceiptVerifier
    protocol_store: DurableDevelopmentalLearningProtocolStore
    invocation_executor: ProductionServingDurableLearningExecutor
    runner: DurableDevelopmentalLearningRunner


@dataclass(frozen=True)
class ProductionDurableLearningBranchRuntime:
    """Production wiring for condition branches; construction is inert."""

    contexts: Mapping[str, ConversationSessionDurableLearningContext]
    routed_context: ConditionRoutedDurableLearningContext
    branches: Mapping[str, DurableLearningConditionBranch]
    receipt_verifier: LocalModelDurableLearningReceiptVerifier
    protocol_store: DurableDevelopmentalLearningProtocolStore
    runner: DurableDevelopmentalLearningRunner


class DurableLearningConditionSessionProvisioningError(ValueError):
    """Provisioning failure that preserves identities created before failure."""

    def __init__(self, *, stores: Mapping[str, Any],
            session_ids: Mapping[str, str]) -> None:
        super().__init__(
            "durable_learning_condition_session_provisioning_incomplete")
        self.stores = dict(stores)
        self.session_ids = dict(session_ids)


def provision_durable_learning_condition_sessions(*, condition_state_roots: Mapping[
        str, Any], condition_session_store_roots: Mapping[str, Any],
        model_identity: Mapping[str, Any]
        ) -> tuple[dict[str, Any], dict[str, str]]:
    """Create two empty, condition-local stores and active transcript sessions.

    This is an explicit provisioning operation, separate from the inert runtime
    factory. It rejects existing session-store directories and any lexical or
    resolved overlap with either condition's resident state root. A failure
    during filesystem creation can leave an empty directory or session behind;
    callers should inspect and preserve that state rather than silently retry.
    """
    from pathlib import Path
    from .conversation_session import ConversationSessionStore

    if (not isinstance(condition_state_roots, Mapping)
            or set(condition_state_roots) != set(_CONDITIONS)
            or not isinstance(condition_session_store_roots, Mapping)
            or set(condition_session_store_roots) != set(_CONDITIONS)
            or not isinstance(model_identity, Mapping) or not model_identity):
        raise ValueError("durable_learning_condition_session_provisioning_invalid")
    try:
        json.dumps(dict(model_identity), sort_keys=True, separators=(",", ":"),
            ensure_ascii=False, allow_nan=False)
        state_roots = {condition: Path(condition_state_roots[condition]).resolve(
            strict=True) for condition in _CONDITIONS}
        session_root_paths = {condition: Path(
            condition_session_store_roots[condition]).expanduser()
            for condition in _CONDITIONS}
        session_roots = {condition: session_root_paths[condition].resolve(
            strict=False) for condition in _CONDITIONS}
    except (OSError, TypeError, ValueError) as exc:
        raise ValueError(
            "durable_learning_condition_session_root_invalid") from exc
    if (any(path.is_symlink() for path in session_root_paths.values())
            or any(not root.is_dir() for root in state_roots.values())
            or any(root.exists() for root in session_roots.values())):
        raise ValueError("durable_learning_condition_session_root_not_fresh")
    roots = [state_roots[condition] for condition in _CONDITIONS]
    roots.extend(session_roots[condition] for condition in _CONDITIONS)
    for index, left_root in enumerate(roots):
        for right_root in roots[index + 1:]:
            if (left_root == right_root or left_root in right_root.parents
                    or right_root in left_root.parents):
                raise ValueError(
                    "durable_learning_condition_storage_roots_overlap")

    stores: dict[str, Any] = {}
    session_ids: dict[str, str] = {}
    try:
        for condition in _CONDITIONS:
            store = ConversationSessionStore(session_roots[condition])
            stores[condition] = store
            session = store.create(model_identity=dict(model_identity),
                title=f"Durable learning {condition}")
            session_ids[condition] = session["session_id"]
    except (OSError, TypeError, ValueError) as exc:
        raise DurableLearningConditionSessionProvisioningError(
            stores=stores, session_ids=session_ids) from exc
    if (stores[_CONDITIONS[0]] is stores[_CONDITIONS[1]]
            or session_ids[_CONDITIONS[0]] == session_ids[_CONDITIONS[1]]):
        raise ValueError("durable_learning_condition_session_provisioning_invalid")
    return stores, session_ids


def create_production_durable_learning_runtime(*, state_root: Any,
        serving_inference_controller: Any,
        conversation_session_store: Any, session_id: str,
        experience_source: ResidentDevelopmentalLearningExperienceSource,
        retained_state_snapshot_resolver: Callable[[], Mapping[str, Any]],
        experience_source_verifier: Callable[..., bool],
        feedback_policy_verifier: Callable[..., bool],
        condition_blind_scorer: Callable[..., Mapping[str, Any]],
        retained_update_attribution_verifier: Callable[..., Mapping[str, Any]] | None = None,
        allow_descriptive_only_execution: bool = False
        ) -> ProductionDurableLearningRuntime:
    """Wire the governed session path without starting inference or scoring."""
    if (not callable(getattr(serving_inference_controller, "generate", None))
            or not callable(getattr(serving_inference_controller,
                "verify_stored_chat_invocation", None))
            or not callable(experience_source_verifier)
            or not callable(feedback_policy_verifier)
            or not callable(condition_blind_scorer)):
        raise ValueError("durable_learning_production_runtime_dependencies_invalid")
    context = ConversationSessionDurableLearningContext(
        conversation_session_store=conversation_session_store,
        session_id=session_id)
    receipt_verifier = LocalModelDurableLearningReceiptVerifier(
        inference=serving_inference_controller,
        context_resolver=context.receipt_context,
        conversation_session_store=conversation_session_store,
        experience_source_verifier=experience_source_verifier,
        feedback_policy_verifier=feedback_policy_verifier)
    protocol_store = DurableDevelopmentalLearningProtocolStore(state_root,
        invocation_receipt_verifier=receipt_verifier,
        retained_update_attribution_verifier=(
            retained_update_attribution_verifier))
    executor = ProductionServingDurableLearningExecutor(
        serving_inference_controller=serving_inference_controller,
        invocation_context_resolver=context)
    runner = DurableDevelopmentalLearningRunner(
        protocol_store=protocol_store, invocation_executor=executor,
        experience_source=experience_source,
        retained_state_snapshot_resolver=retained_state_snapshot_resolver,
        condition_blind_scorer=condition_blind_scorer,
        allow_descriptive_only_execution=allow_descriptive_only_execution)
    return ProductionDurableLearningRuntime(context, receipt_verifier,
        protocol_store, executor, runner)


def create_production_durable_learning_branch_runtime(*, state_root: Any,
        serving_inference_controller: Any,
        conversation_session_store: Any | None = None,
        condition_session_stores: Mapping[str, Any] | None = None,
        condition_branch_ids: Mapping[str, str],
        condition_configs: Mapping[str, Mapping[str, Any]],
        experience_source_verifier: Callable[..., bool],
        feedback_policy_verifier: Callable[..., bool],
        condition_blind_scorer: Callable[..., Mapping[str, Any]],
        retained_update_attribution_verifier: Callable[..., Mapping[str, Any]] | None = None,
        allow_descriptive_only_execution: bool = False
        ) -> ProductionDurableLearningBranchRuntime:
    """Wire condition branches without inference, scoring, or writeback.

    Each condition config supplies ``experience_source``,
    ``retained_state_snapshot_resolver``, and ``session_id``. By default the
    conversation store and serving controller are shared. Protocol v10
    callers should supply distinct stores via ``condition_session_stores``.
    Branch sessions, resident owners, snapshot resolvers, contexts, and
    executors are condition-specific.
    """
    if (not callable(getattr(serving_inference_controller, "generate", None))
            or not callable(getattr(serving_inference_controller,
                "verify_stored_chat_invocation", None))
            or not callable(experience_source_verifier)
            or not callable(feedback_policy_verifier)
            or not callable(condition_blind_scorer)
            or type(allow_descriptive_only_execution) is not bool
            or not isinstance(condition_branch_ids, Mapping)
            or set(condition_branch_ids) != set(_CONDITIONS)
            or not isinstance(condition_configs, Mapping)
            or set(condition_configs) != set(_CONDITIONS)):
        raise ValueError("durable_learning_production_branch_runtime_invalid")
    if (any(not isinstance(condition_branch_ids[condition], str)
                or not condition_branch_ids[condition]
                for condition in _CONDITIONS)
            or len(set(condition_branch_ids.values())) != len(_CONDITIONS)):
        raise ValueError("durable_learning_production_branch_ids_invalid")
    if condition_session_stores is not None and (
            not isinstance(condition_session_stores, Mapping)
            or set(condition_session_stores) != set(_CONDITIONS)
            or any(not callable(getattr(condition_session_stores[c], "load", None))
                or not callable(getattr(condition_session_stores[c],
                    "append_user_request", None))
                or not callable(getattr(condition_session_stores[c], "append_turn", None))
                or not callable(getattr(condition_session_stores[c],
                    "list_recent", None))
                for c in _CONDITIONS)):
        raise ValueError("durable_learning_production_session_stores_invalid")
    receipt_session_store = conversation_session_store
    if condition_session_stores is not None:
        if (condition_session_stores[_CONDITIONS[0]] is
                condition_session_stores[_CONDITIONS[1]]):
            raise ValueError("durable_learning_production_session_stores_not_distinct")
        if receipt_session_store is None:
            receipt_session_store = condition_session_stores[_CONDITIONS[0]]
    if not callable(getattr(receipt_session_store, "load", None)):
        raise ValueError("durable_learning_production_session_store_required")
    contexts: dict[str, ConversationSessionDurableLearningContext] = {}
    executors: dict[str, ProductionServingDurableLearningExecutor] = {}
    branches: dict[str, DurableLearningConditionBranch] = {}
    for condition in _CONDITIONS:
        config = condition_configs[condition]
        session_store = (condition_session_stores[condition]
            if condition_session_stores is not None else conversation_session_store)
        if (not isinstance(config, Mapping)
                or set(config) != {"experience_source",
                    "retained_state_snapshot_resolver", "session_id"}
                or not isinstance(config.get("experience_source"),
                    ResidentDevelopmentalLearningExperienceSource)
                or not callable(config.get("retained_state_snapshot_resolver"))
                or not isinstance(config.get("session_id"), str)
                or not config["session_id"]):
            raise ValueError("durable_learning_production_branch_config_invalid")
        contexts[condition] = ConversationSessionDurableLearningContext(
            conversation_session_store=session_store,
            session_id=config["session_id"])
        executors[condition] = ProductionServingDurableLearningExecutor(
            serving_inference_controller=serving_inference_controller,
            invocation_context_resolver=contexts[condition])
    if (contexts[_CONDITIONS[0]].session_id ==
            contexts[_CONDITIONS[1]].session_id
            or condition_configs[_CONDITIONS[0]]["experience_source"]._owner is
                condition_configs[_CONDITIONS[1]]["experience_source"]._owner
            or executors[_CONDITIONS[0]] is executors[_CONDITIONS[1]]):
        raise ValueError("durable_learning_production_branch_isolation_invalid")
    routed_context = ConditionRoutedDurableLearningContext(
        contexts=contexts, branch_ids=condition_branch_ids)
    receipt_verifier = LocalModelDurableLearningReceiptVerifier(
        inference=serving_inference_controller,
        context_resolver=routed_context.receipt_context,
        conversation_session_store=receipt_session_store,
        experience_source_verifier=experience_source_verifier,
        feedback_policy_verifier=feedback_policy_verifier)
    protocol_store = DurableDevelopmentalLearningProtocolStore(state_root,
        invocation_receipt_verifier=receipt_verifier,
        retained_update_attribution_verifier=(
            retained_update_attribution_verifier))
    for condition in _CONDITIONS:
        config = condition_configs[condition]
        branches[condition] = DurableLearningConditionBranch(
            branch_id=condition_branch_ids[condition],
            experience_source=config["experience_source"],
            retained_state_snapshot_resolver=(
                config["retained_state_snapshot_resolver"]),
            invocation_executor=executors[condition],
            conversation_context=contexts[condition],
            conversation_session_store=contexts[condition].conversation_session_store,
            session_id=contexts[condition].session_id)
    first_config = condition_configs[_CONDITIONS[0]]
    runner = DurableDevelopmentalLearningRunner(
        protocol_store=protocol_store,
        invocation_executor=executors[_CONDITIONS[0]],
        experience_source=first_config["experience_source"],
        retained_state_snapshot_resolver=(
            first_config["retained_state_snapshot_resolver"]),
        condition_blind_scorer=condition_blind_scorer,
        allow_descriptive_only_execution=allow_descriptive_only_execution,
        condition_branches=branches)
    return ProductionDurableLearningBranchRuntime(contexts,
        routed_context, branches, receipt_verifier, protocol_store, runner)
